-- ============================================================
--  121_experiencias_bpm.sql — Experiencias de clase: Curso de Buenas Prácticas de Manufactura — BPM
--
--  Generado por scripts/generar-migracion-experiencias.mjs bpm
--  a partir de contenido/experiencias/bpm. No editar a mano.
--
--  35 clases con experiencia interactiva (mapa conceptual,
--  mapa de proceso, caso, errores frecuentes, repaso, resumen y
--  referencias): 202.036 caracteres de lectura, mínimo
--  4.234 por clase.
--
--  Por clase: si no está, avisa y sigue; si no tiene experiencia,
--  retira (borrado lógico) el texto corto de la siembra e inserta la
--  experiencia como primer bloque, conservando videos y enlaces; si ya
--  la tiene, la actualiza. Si el curso está publicado, deja aprobada
--  una versión nueva (077). Nunca detiene el arranque.
-- ============================================================

DO $exp$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Buenas Prácticas de Manufactura — BPM$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Buenas Prácticas de Manufactura — BPM$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: qué son las BPM y por qué importan
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El análisis final no lo puede ver todo","texto":"Un lote de 500.000 tabletas se libera con un muestreo de unas pocas decenas de unidades. Si una sola caja de otro producto se coló en la línea de empaque, o si un residuo del lote anterior quedó en la tolva, es muy probable que el análisis final no lo detecte. Por eso la calidad de un medicamento no se comprueba al final: se construye en cada paso. Ese es el corazón de las Buenas Prácticas de Manufactura."},"objetivos":["Definir las BPM y su lugar dentro del sistema de aseguramiento de la calidad.","Explicar por qué el control de calidad del producto terminado no basta.","Reconocer los riesgos que las BPM buscan prevenir: contaminación, contaminación cruzada y mezclas.","Ubicar el recorrido del curso desde el marco legal hasta la certificación del INVIMA."],"conceptos":[{"icono":"ShieldCheck","termino":"Buenas Prácticas de Manufactura","definicion":"La parte del aseguramiento de la calidad que garantiza que los medicamentos se fabrican y controlan de forma consistente según estándares de calidad adecuados para su uso y según su registro sanitario."},{"icono":"Layers","termino":"Aseguramiento de la calidad","definicion":"El sistema completo de actividades organizadas para que el producto tenga la calidad requerida. Incluye las BPM, el control de calidad y la gestión de riesgos."},{"icono":"Shuffle","termino":"Mezcla (mix-up)","definicion":"Confusión entre materiales, productos, rótulos o documentos de lotes distintos. Es una de las causas más frecuentes de retiros del mercado y rara vez la detecta el muestreo final."},{"icono":"Bug","termino":"Contaminación cruzada","definicion":"La presencia de un material o producto en otro. Puede llegar por residuos en equipos, por el aire, por las personas o por mezclas."}],"secciones":[{"titulo":"La calidad se construye, no se inspecciona","parrafos":["Las BPM existen porque hay riesgos que ningún análisis final puede descartar. Un muestreo estadístico detecta defectos frecuentes, pero no una caja equivocada entre miles ni una contaminación localizada en unas pocas unidades. Por eso las BPM exigen controlar todo lo que rodea a la fabricación: quién trabaja y cómo se entrena, dónde se fabrica, con qué equipos, con qué materiales, con qué instrucciones y con qué registros.","La OMS describe las BPM como la parte del aseguramiento de la calidad que garantiza que los productos se fabrican y controlan de forma consistente según estándares adecuados para su uso y según su autorización de comercialización. En Colombia, esa autorización es el **registro sanitario** del INVIMA: fabricar fuera de lo registrado, aunque el producto «salga bien», es un incumplimiento.","Las BPM se apoyan en una idea simple que guiará todo el curso: **lo que no está escrito no ocurrió**. Cada operación tiene un procedimiento, cada lote tiene un registro y cada decisión de calidad queda documentada. No es burocracia: es la única forma de reconstruir qué pasó cuando algo sale mal."]},{"titulo":"Cómo está organizado este curso","parrafos":["La **unidad 1** explica de dónde salen las BPM y cuál es el marco legal colombiano: los decretos, la Resolución 1160 de 2016 y las normas especiales. La **unidad 2** recorre los recursos: personal, instalaciones, equipos y sistemas críticos como el agua y el aire. La **unidad 3** entra al proceso productivo: contaminación cruzada, despeje de línea, rendimientos, registros de lote y materiales.","La **unidad 4** se dedica a los productos estériles y a los cambios del Anexo 1 de 2022. La **unidad 5** cierra con la fabricación por contrato, la autoinspección y el procedimiento de certificación ante el INVIMA. En cada clase encontrarás un caso para decidir, un mapa del proceso que puedes practicar y las referencias para leer la norma en su fuente."]}],"errores":[{"error":"Pensar que las BPM son responsabilidad solo de aseguramiento de calidad.","correccion":"Las BPM las cumple cada persona que toca el producto: producción, almacén, mantenimiento y control de calidad."},{"error":"Confiar en que el análisis final detectará cualquier problema.","correccion":"Las mezclas y la contaminación localizada se previenen en el proceso; el análisis final solo confirma."},{"error":"Fabricar distinto a lo registrado porque «da el mismo resultado».","correccion":"Cualquier cambio frente al registro sanitario se gestiona por control de cambios y, si aplica, ante el INVIMA."}],"comprueba":[{"pregunta":"¿Qué tres riesgos principales previenen las BPM?","respuesta":"La contaminación, la contaminación cruzada y las mezclas o confusiones."},{"pregunta":"¿Por qué no basta el control de calidad del producto terminado?","respuesta":"Porque el muestreo no detecta defectos raros o localizados, como una caja equivocada o un residuo en pocas unidades."},{"pregunta":"¿Qué significa «lo que no está escrito no ocurrió»?","respuesta":"Que toda actividad de BPM debe estar documentada para demostrar que se hizo y reconstruir lo que pasó."}],"resumen":["Las BPM garantizan que cada lote se fabrique **igual y según el registro sanitario**.","Previenen contaminación, contaminación cruzada y **mezclas** que el análisis final no ve.","La calidad **se construye** con personas, instalaciones, procesos y registros."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"OMS/OPS. Informe 32, Anexo 1: Prácticas adecuadas de fabricación de productos farmacéuticos.","url":"https://www3.paho.org/hq/dmdocuments/2008/1_Anexo_1_informe_32.pdf"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"}],"imagenes":[{"ubicacion":"Después de la situación inicial","descripcion":"Ilustración de una línea de producción con una lupa que solo alcanza a ver unas pocas tabletas del lote, mientras el resto queda fuera del foco; colores azul y turquesa de Edvanta.","alt":"El muestreo final solo ve una pequeña parte del lote"}],"keywords":["qué son las bpm","buenas prácticas de manufactura qué son","curso de bpm gratis","curso gmp gratis","buenas prácticas de manufactura farmacéutica","bpm industria farmacéutica","importancia de las bpm","bpm en colombia","curso de buenas prácticas de manufactura","gmp farmacéutica en español"],"mapa":{"centro":"Qué protegen las BPM","ramas":[{"titulo":"Al paciente","icono":"Users","nodos":["Medicamento seguro y eficaz","Igual en cada lote","Como dice el registro sanitario"]},{"titulo":"De qué riesgos","icono":"AlertTriangle","nodos":["Contaminación","Contaminación cruzada","Mezclas y confusiones"]},{"titulo":"Con qué recursos","icono":"Factory","nodos":["Personal entrenado","Instalaciones y equipos adecuados","Procesos validados"]},{"titulo":"Con qué evidencia","icono":"FileCheck","nodos":["Procedimientos escritos","Registros completos","Revisión antes de liberar"]}]},"proceso":{"titulo":"Cómo protegen las BPM un lote, de principio a fin","intro":"","pasos":[{"titulo":"Materiales aprobados","detalle":"Solo entran a producción materias primas y material de envase de proveedores aprobados, analizados y liberados por control de calidad.","icono":"PackageCheck","evidencia":"Certificados y rótulos de aprobado."},{"titulo":"Área y equipos listos","detalle":"El área está limpia, sin materiales del lote anterior y con los equipos calificados, calibrados y rotulados como limpios.","icono":"ClipboardCheck","evidencia":"Despeje de línea verificado."},{"titulo":"Fabricar según instrucciones","detalle":"Se sigue la orden de producción aprobada, con pesajes verificados y controles en proceso.","icono":"Factory","evidencia":"Registro de lote diligenciado en el momento."},{"titulo":"Controlar y conciliar","detalle":"Se calculan rendimientos, se concilia el material impreso y se investigan las desviaciones.","icono":"Calculator","evidencia":"Conciliación y desviaciones cerradas."},{"titulo":"Analizar y revisar","detalle":"Control de calidad analiza el producto y aseguramiento de calidad revisa todo el registro del lote.","icono":"FileSearch","evidencia":"Certificado de análisis y revisión del registro."},{"titulo":"Liberar","detalle":"La persona autorizada decide la liberación solo si todo cumple con el registro sanitario y las BPM.","icono":"Signature","evidencia":"Liberación firmada."}]},"caso":{"titulo":"El lote que cumple todas las especificaciones","contexto":"Un lote de jarabe cumple todas las especificaciones en el laboratorio. Al revisar el registro de lote, aseguramiento de calidad encuentra que el despeje de línea antes del envasado no tiene la firma de verificación y que la conciliación de etiquetas muestra 300 unidades faltantes.","pregunta":"¿Se puede liberar el lote?","opciones":[{"texto":"Sí, porque el análisis demuestra que el producto cumple.","correcta":false,"retro":"El análisis no puede descartar una mezcla de etiquetas: 300 etiquetas faltantes podrían estar en otro producto o en este lote mal rotuladas."},{"texto":"No hasta investigar el faltante de etiquetas y la falta de verificación del despeje, evaluar el impacto y documentar la decisión.","correcta":true,"retro":"Las BPM existen justamente para estos riesgos que el análisis no ve. El lote queda retenido hasta cerrar la investigación."},{"texto":"Sí, si el jefe de producción firma ahora el despeje de línea.","correcta":false,"retro":"Firmar después lo que no se verificó en su momento es una falla grave de integridad de datos."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción al curso: qué son las BPM y por qué importan$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción al curso: qué son las BPM y por qué importan$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 02. Origen de las BPM: de la tragedia de la talidomida a la OMS
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Cada norma tiene una historia detrás","texto":"En 1937, un jarabe de sulfanilamida disuelto en dietilenglicol causó más de cien muertes en Estados Unidos. A comienzos de los años sesenta, la talidomida, vendida como sedante para embarazadas, dejó miles de niños con malformaciones en varios países. Muchas reglas que hoy parecen exageradas en una planta nacieron de tragedias así. Entender ese origen ayuda a cumplirlas con convicción."},"objetivos":["Relacionar las principales tragedias farmacéuticas con el nacimiento de la regulación.","Describir cómo la OMS adoptó las primeras BPM y por qué buscaba armonizarlas.","Explicar qué lección de cada tragedia sigue vigente en las BPM actuales."],"conceptos":[{"icono":"AlertTriangle","termino":"Elixir de sulfanilamida (1937)","definicion":"Un solvente tóxico, el dietilenglicol, causó más de cien muertes en Estados Unidos. Impulsó la ley de 1938 que exigió demostrar la seguridad antes de comercializar."},{"icono":"Users","termino":"Talidomida (1957-1962)","definicion":"Sedante que causó malformaciones graves en recién nacidos. Llevó a exigir pruebas de eficacia y seguridad más estrictas y a reforzar el control de la fabricación."},{"icono":"Globe","termino":"BPM de la OMS","definicion":"La OMS preparó a finales de los años sesenta un texto de BPM para que los países compartieran un mismo estándar de fabricación y control de calidad."},{"icono":"Droplets","termino":"Dietilenglicol, una lección que se repite","definicion":"Las intoxicaciones por jarabes contaminados con dietilenglicol se han repetido en varios países, incluso en este siglo. Por eso las BPM exigen verificar la identidad de cada materia prima."}],"secciones":[{"titulo":"Tragedias que cambiaron la regulación","parrafos":["En 1937, una empresa estadounidense disolvió sulfanilamida en dietilenglicol para venderla como jarabe. Nadie probó la toxicidad del solvente y más de cien personas murieron. La respuesta fue la ley federal de alimentos, medicamentos y cosméticos de 1938, que obligó a demostrar la seguridad de un medicamento antes de venderlo. La lección para la fabricación es directa: **cada componente debe identificarse y controlarse**, incluidos los excipientes y los solventes.","Entre finales de los años cincuenta y comienzos de los sesenta, la talidomida se vendió en varios países como sedante y para las náuseas del embarazo. Miles de niños nacieron con malformaciones graves. En Estados Unidos no se aprobó gracias a la insistencia de una evaluadora de la FDA que pidió más datos, y el episodio llevó a las enmiendas de 1962, que exigieron demostrar eficacia y reforzaron los requisitos de fabricación.","Estas lecciones no son historia antigua. Las intoxicaciones por jarabes contaminados con dietilenglicol o etilenglicol se han repetido en distintos países en las últimas décadas. Cada vez, la causa de fondo fue la misma: una materia prima que no se verificó. Por eso las BPM insisten en la identidad de cada materia prima y en calificar a los proveedores."]},{"titulo":"La OMS y la armonización","parrafos":["Con el comercio internacional de medicamentos, cada país necesitaba confiar en lo que importaba. La OMS preparó a finales de los años sesenta un texto de Buenas Prácticas de Manufactura y lo vinculó a un esquema de certificación de la calidad de los productos que se comercializan entre países. Desde entonces, su Comité de Expertos en Especificaciones para las Preparaciones Farmacéuticas actualiza las BPM y sus anexos en una serie de informes técnicos.","Colombia, como muchos países de la región, construyó sus normas de BPM a partir de esos informes de la OMS. Por eso, cuando se lee un manual de BPM colombiano, se reconocen la estructura y el lenguaje de la OMS. En la siguiente clase verás cuáles son esos informes técnicos y qué aporta cada uno."]}],"errores":[{"error":"Ver las BPM como trámites sin sentido.","correccion":"Cada requisito tiene un porqué; conocer su origen ayuda a cumplirlo con criterio."},{"error":"Aceptar certificados de análisis sin verificar la identidad del material.","correccion":"Califica al proveedor y verifica la identidad de las materias primas según tu procedimiento."}],"comprueba":[{"pregunta":"¿Qué causó la tragedia de la sulfanilamida de 1937?","respuesta":"El uso de dietilenglicol, un solvente tóxico, sin pruebas de seguridad."},{"pregunta":"¿Por qué la OMS creó un texto de BPM?","respuesta":"Para que los países compartieran un estándar de fabricación y pudieran confiar en los medicamentos del comercio internacional."},{"pregunta":"¿Qué lección de BPM deja el dietilenglicol?","respuesta":"Que hay que verificar la identidad de cada materia prima y calificar a los proveedores."}],"resumen":["Las BPM nacieron de **tragedias reales**: sulfanilamida, talidomida y otras.","La OMS creó un estándar común y lo **actualiza** en sus informes técnicos.","La lección que más se repite: **verificar la identidad** de cada materia prima."],"referencias":[{"cita":"OMS/OPS. Informe 32, Anexo 1: Prácticas adecuadas de fabricación de productos farmacéuticos.","url":"https://www3.paho.org/hq/dmdocuments/2008/1_Anexo_1_informe_32.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"En la sección de tragedias","descripcion":"Línea de tiempo ilustrada (1937, 1962, finales de los sesenta, hoy) con iconos de frasco, recién nacido, globo de la OMS y escudo de BPM, en los colores de marca.","alt":"Línea de tiempo del origen de las Buenas Prácticas de Manufactura"}],"keywords":["historia de las bpm","origen de las buenas prácticas de manufactura","talidomida y regulación de medicamentos","tragedia de la sulfanilamida 1937","dietilenglicol jarabes","historia de las gmp","oms buenas prácticas de manufactura origen"],"mapa":{"centro":"De la tragedia a la norma","ramas":[{"titulo":"Sulfanilamida","icono":"Droplets","nodos":["Solvente tóxico sin pruebas","Ley de 1938 en EE. UU.","Lección: identidad y seguridad de cada componente"]},{"titulo":"Talidomida","icono":"Users","nodos":["Malformaciones congénitas","Enmiendas de 1962","Lección: evidencia antes de comercializar"]},{"titulo":"OMS","icono":"Globe","nodos":["Primer texto de BPM a fines de los sesenta","Esquema de certificación internacional","Informes técnicos que se actualizan"]},{"titulo":"Hoy","icono":"ShieldCheck","nodos":["BPM adoptadas por cada país","Inspección y certificación","Gestión de riesgos"]}]},"proceso":{"titulo":"Cómo una tragedia se convierte en un requisito de BPM","intro":"","pasos":[{"titulo":"Ocurre el daño","detalle":"Un producto causa daño a pacientes: muertes, malformaciones o intoxicaciones.","icono":"AlertTriangle","evidencia":"Reportes de casos y farmacovigilancia."},{"titulo":"Se investiga la causa","detalle":"Las autoridades rastrean el origen: un solvente tóxico, una contaminación, una mezcla o una falta de estudios.","icono":"Search","evidencia":"Informes de investigación."},{"titulo":"Se legisla","detalle":"La ley exige demostrar seguridad, eficacia o calidad antes de comercializar.","icono":"Gavel","evidencia":"Leyes y decretos."},{"titulo":"Se traduce en práctica","detalle":"La regla general se vuelve un requisito concreto: identidad de cada materia prima, proveedores calificados, registros.","icono":"ClipboardList","evidencia":"Manuales de BPM."},{"titulo":"Se inspecciona","detalle":"La autoridad verifica el cumplimiento con guías de inspección y certificación.","icono":"ShieldCheck","evidencia":"Actas y certificados de BPM."}]},"caso":{"titulo":"Un proveedor nuevo de glicerina","contexto":"Compras consigue glicerina un 30 % más barata con un distribuidor nuevo que entrega un certificado de análisis impecable. Producción necesita el material para un jarabe pediátrico esta semana.","pregunta":"¿Qué indica la historia de las BPM?","opciones":[{"texto":"Usarla con el certificado del distribuidor, porque cumple la especificación.","correcta":false,"retro":"Los casos de dietilenglicol se dieron precisamente con certificados que no correspondían al material real."},{"texto":"Calificar al proveedor, verificar la cadena de suministro y analizar la identidad de cada contenedor, incluida la prueba de dietilenglicol y etilenglicol que exige la farmacopea, antes de aprobarla.","correcta":true,"retro":"La identidad de cada contenedor y la calificación del proveedor son la defensa directa contra la tragedia que más se ha repetido en la historia de los jarabes."},{"texto":"Mezclarla con la glicerina del proveedor anterior para reducir el riesgo.","correcta":false,"retro":"Mezclar no reduce el riesgo: lo esconde y contamina el material bueno."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Origen de las BPM: de la tragedia de la talidomida a la OMS$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Origen de las BPM: de la tragedia de la talidomida a la OMS$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 03. Informes técnicos de la OMS: Informe 32 (TRS 823), TRS 961 y TRS 986
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"«¿El manual sale del Informe 32 o del 986?»","texto":"En una capacitación, alguien dice que las BPM colombianas «son el Informe 32». Otra persona responde que la OMS ya lo actualizó varias veces. Las dos tienen algo de razón. Para leer bien un manual de BPM, y para saber qué versión de un requisito aplica, hay que conocer la serie de informes técnicos de la OMS y cómo se fue actualizando."},"objetivos":["Explicar qué es la Serie de Informes Técnicos (TRS) de la OMS.","Ubicar el Informe 32 (TRS 823), el TRS 961 y el TRS 986 en la evolución de las BPM.","Identificar los anexos de la OMS que complementan las BPM principales."],"conceptos":[{"icono":"BookOpen","termino":"Serie de Informes Técnicos (TRS)","definicion":"Publicación de la OMS donde su Comité de Expertos en Especificaciones para las Preparaciones Farmacéuticas adopta guías. Cada informe trae anexos con guías específicas."},{"icono":"FileText","termino":"Informe 32 (TRS 823, 1992)","definicion":"Su Anexo 1 contiene las prácticas adecuadas de fabricación de productos farmacéuticos. Fue durante años la base de las BPM en la región."},{"icono":"Files","termino":"TRS 961 (2011)","definicion":"Informe 45 del Comité. Reunió una actualización de los principios de BPM y varios anexos, como los de sistemas HVAC y productos estériles de esa época."},{"icono":"FileCheck","termino":"TRS 986, Anexo 2 (2014)","definicion":"Los principios principales de BPM de la OMS actualizados, que incorporan la gestión de riesgos para la calidad y la revisión de calidad del producto."}],"secciones":[{"titulo":"Cómo funciona la serie de informes","parrafos":["La OMS no publica una «norma de BPM» única que se reemplaza de golpe. Su Comité de Expertos en Especificaciones para las Preparaciones Farmacéuticas se reúne y adopta guías que se publican como anexos de un informe numerado dentro de la Serie de Informes Técnicos (TRS, por sus siglas en inglés). Una guía nueva puede actualizar solo una parte: por ejemplo, el agua, la validación o los productos estériles.","El **Informe 32**, publicado como TRS 823 en 1992, incluyó en su Anexo 1 las prácticas adecuadas de fabricación de productos farmacéuticos. Ese texto se tradujo y circuló ampliamente en América Latina, y por eso muchas personas todavía llaman «el Informe 32» a las BPM. Luego vinieron actualizaciones: el **TRS 961** (2011) reunió principios actualizados y varios anexos técnicos, y el **TRS 986** (2014), en su Anexo 2, publicó los principios principales de BPM vigentes, con elementos como la gestión de riesgos para la calidad y la revisión de calidad del producto."]},{"titulo":"Qué consultar para cada tema","parrafos":["Los principios principales (TRS 986, Anexo 2) cubren el sistema de calidad, el personal, las instalaciones, los equipos, los materiales, la documentación, la producción y el control de calidad. Para temas técnicos se consulta el anexo especializado más reciente: la guía de **validación** del TRS 1019 (2019), la de **agua para uso farmacéutico** del TRS 1033 (2021), la de **sistemas HVAC** para no estériles del TRS 1010 (2018) y la de **productos estériles** del TRS 1044 (2022).","En Colombia, la norma obligatoria es la que adoptó el Ministerio de Salud en la Resolución 1160 de 2016. Los informes de la OMS son la fuente de donde salió y la mejor referencia para interpretar un requisito. Cuando la OMS publica una guía más reciente, sirve como estado del arte, aunque la obligación legal siga siendo la de la resolución vigente."]}],"errores":[{"error":"Llamar «Informe 32» a toda la normativa de BPM.","correccion":"Distingue la norma colombiana (Resolución 1160 de 2016) de los informes técnicos de la OMS que la inspiraron."},{"error":"Citar guías de la OMS desactualizadas.","correccion":"Busca siempre el anexo más reciente del tema antes de citarlo."}],"comprueba":[{"pregunta":"¿Qué contiene el Anexo 1 del Informe 32 (TRS 823)?","respuesta":"Las prácticas adecuadas de fabricación de productos farmacéuticos de la OMS de 1992."},{"pregunta":"¿Qué incorporó el TRS 986, Anexo 2?","respuesta":"Los principios principales de BPM actualizados, con gestión de riesgos para la calidad y revisión de calidad del producto."},{"pregunta":"¿Dónde está la guía de la OMS sobre agua para uso farmacéutico?","respuesta":"En el TRS 1033, Anexo 3, de 2021."}],"resumen":["La OMS publica sus guías como **anexos de informes técnicos** numerados.","Informe 32 (1992), TRS 961 (2011) y TRS 986 (2014) marcan la evolución de los principios.","Para temas técnicos se usa el **anexo especializado más reciente**."],"referencias":[{"cita":"OMS/OPS. Informe 32, Anexo 1: Prácticas adecuadas de fabricación de productos farmacéuticos.","url":"https://www3.paho.org/hq/dmdocuments/2008/1_Anexo_1_informe_32.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"OMS. TRS 1019, Anexo 3: Good manufacturing practices: guidelines on validation (2019).","url":"https://cdn.who.int/media/docs/default-source/medicines/norms-and-standards/guidelines/production/trs1019-annex3-gmp-validation.pdf?sfvrsn=9440a5c_0&download=true"},{"cita":"OMS. TRS 1033, Anexo 3: Good manufacturing practices: water for pharmaceutical use (2021).","url":"https://www.who.int/publications/m/item/annex-3-trs-1033"},{"cita":"OMS. TRS 1010, Anexo 8: Guidelines on heating, ventilation and air-conditioning systems for non-sterile pharmaceutical products (2018).","url":"https://gmp-compliance.org/files/guidemgr/TRS1010annex8.pdf"},{"cita":"OMS. TRS 1044, Anexo 2: WHO good manufacturing practices for sterile pharmaceutical products (2022).","url":"https://www.who.int/publications/m/item/trs1044-annex2"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Estantería ilustrada con informes numerados (823, 961, 986, 1010, 1019, 1033, 1044) y etiquetas de tema, en azul y lavanda.","alt":"Serie de informes técnicos de la OMS sobre BPM"}],"keywords":["informe 32 oms","trs 823 anexo 1","trs 986 anexo 2","trs 961 oms","informes técnicos oms bpm","bpm oms en español","who trs gmp","anexos de la oms buenas prácticas"],"mapa":{"centro":"Las BPM de la OMS en el tiempo","ramas":[{"titulo":"Informe 32","icono":"FileText","nodos":["TRS 823, 1992","Anexo 1: prácticas adecuadas de fabricación","Base histórica en la región"]},{"titulo":"TRS 961","icono":"Files","nodos":["Informe 45, 2011","Principios actualizados","Anexos técnicos de la época"]},{"titulo":"TRS 986","icono":"FileCheck","nodos":["Informe 48, 2014","Anexo 2: principios principales","Gestión de riesgos y revisión de producto"]},{"titulo":"Anexos especializados","icono":"Layers","nodos":["Validación: TRS 1019","Agua: TRS 1033","HVAC: TRS 1010","Estériles: TRS 1044"]}]},"proceso":{"titulo":"Cómo encontrar la guía correcta de la OMS","intro":"","pasos":[{"titulo":"Define el tema","detalle":"Escribe la pregunta concreta: por ejemplo, ¿cuánto debe durar la calificación de un sistema de agua?","icono":"Search","evidencia":"Pregunta documentada."},{"titulo":"Revisa la norma colombiana","detalle":"Busca primero qué dice la Resolución 1160 de 2016 y sus manuales.","icono":"Landmark","evidencia":"Cita de la norma."},{"titulo":"Ubica el anexo de la OMS","detalle":"Busca el anexo especializado más reciente sobre el tema en la serie TRS.","icono":"BookOpen","evidencia":"Número de TRS y anexo."},{"titulo":"Verifica la versión","detalle":"Confirma que no exista una guía más nueva que la reemplace.","icono":"RefreshCw","evidencia":"Fecha de publicación consultada."},{"titulo":"Cita las dos fuentes","detalle":"En tus procedimientos, cita la norma que obliga y la guía que explica.","icono":"FileCheck","evidencia":"Referencias en el documento."}]},"caso":{"titulo":"Un procedimiento que cita el Informe 32","contexto":"Revisas el procedimiento de calificación del sistema de agua de tu planta. Su única referencia es el Informe 32 de 1992.","pregunta":"¿Qué mejora propones?","opciones":[{"texto":"Dejarlo igual, porque el Informe 32 es la base de las BPM.","correcta":false,"retro":"Es la base histórica, pero el tema del agua tiene una guía específica mucho más reciente."},{"texto":"Citar la Resolución 1160 de 2016 como norma obligatoria y la guía de agua del TRS 1033 (2021) como referencia técnica, y revisar si el procedimiento refleja la calificación por fases.","correcta":true,"retro":"Así el procedimiento queda anclado a la norma vigente y al estado del arte del tema."},{"texto":"Reemplazar todas las referencias por guías de la FDA.","correcta":false,"retro":"Las guías de la FDA pueden ayudar, pero la base colombiana viene de la OMS y de la Resolución 1160."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Informes técnicos de la OMS: Informe 32 (TRS 823), TRS 961 y TRS 986$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Informes técnicos de la OMS: Informe 32 (TRS 823), TRS 961 y TRS 986$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 04. PIC/S y la convergencia regulatoria internacional
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Exportar sin repetir cada inspección","texto":"Un laboratorio colombiano quiere exportar a varios países de la región. Cada autoridad podría pedir su propia inspección, con requisitos parecidos pero no iguales. La convergencia regulatoria busca lo contrario: que una inspección bien hecha y un estándar común generen confianza entre autoridades. PIC/S es uno de los motores de esa convergencia."},"objetivos":["Explicar qué es PIC/S y qué aporta su guía de BPM.","Diferenciar PIC/S, ICH y OMS en el panorama regulatorio.","Reconocer por qué la convergencia importa para la industria colombiana."],"conceptos":[{"icono":"ShieldCheck","termino":"PIC/S","definicion":"Esquema de cooperación de inspección farmacéutica que reúne autoridades sanitarias. Busca guías comunes de BPM, inspectores formados con el mismo criterio y confianza mutua."},{"icono":"BookOpen","termino":"Guía PE 009","definicion":"La guía de BPM de PIC/S, con una Parte I para medicamentos, una Parte II para principios activos y anexos como el 1 (estériles) y el 15 (calificación y validación)."},{"icono":"Network","termino":"ICH","definicion":"Consejo que reúne autoridades e industria para armonizar requisitos técnicos, como las guías Q de calidad."},{"icono":"Globe","termino":"Convergencia regulatoria","definicion":"Proceso por el que las autoridades acercan sus requisitos y prácticas para reconocer el trabajo de otras sin perder control."}],"secciones":[{"titulo":"Qué es PIC/S y por qué se cita tanto","parrafos":["PIC/S nació de la cooperación entre autoridades de inspección europeas y hoy reúne inspectorados de varios continentes. Sus miembros comparten la guía de BPM, se evalúan mutuamente y forman a sus inspectores con criterios comunes. Para una empresa, que su autoridad sea parte de PIC/S facilita que otras autoridades confíen en sus inspecciones.","La guía de PIC/S (PE 009) es prácticamente equivalente a la guía de BPM de la Unión Europea. Por eso documentos como el **Anexo 1** sobre productos estériles o el **Anexo 15** sobre calificación y validación se citan en todo el mundo como referencia técnica, aunque un país no sea miembro. Antes de afirmar que un país pertenece a PIC/S, consulta la lista de miembros vigente en su sitio oficial: cambia con el tiempo."]},{"titulo":"La convergencia en la práctica colombiana","parrafos":["Colombia adoptó sus BPM a partir de los informes de la OMS y el INVIMA ha trabajado en la cooperación internacional, incluido su ingreso a la Coalición Internacional de Autoridades Reguladoras de Medicamentos (ICMRA). Para la industria, esto significa que conocer las guías internacionales no es un lujo: es la forma de anticipar hacia dónde se mueven los requisitos y de preparar plantas capaces de exportar.","Una regla práctica: cuando escribas un procedimiento, ancla la obligación en la norma colombiana y usa PIC/S, ICH y la OMS para explicar el cómo. Así cumples hoy y estás preparado para los cambios que vienen."]}],"errores":[{"error":"Afirmar que un país es miembro de PIC/S sin verificarlo.","correccion":"Consulta la lista vigente en el sitio oficial de PIC/S."},{"error":"Tratar las guías internacionales como si fueran ley colombiana.","correccion":"Úsalas como referencia técnica y ancla la obligación en la norma nacional."}],"comprueba":[{"pregunta":"¿Qué contiene la guía PE 009 de PIC/S?","respuesta":"La guía de BPM con una parte para medicamentos, otra para principios activos y anexos como el 1 y el 15."},{"pregunta":"¿En qué se diferencia ICH de PIC/S?","respuesta":"ICH armoniza requisitos técnicos con autoridades e industria (como las guías Q); PIC/S coopera en inspección y en la guía de BPM."}],"resumen":["PIC/S comparte **guía de BPM, formación y confianza** entre inspectorados.","Sus anexos 1 y 15 son **referencia técnica mundial**.","Conocer la convergencia prepara a la planta para **inspecciones y exportación**."],"referencias":[{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"},{"cita":"PIC/S. Guide to GMP, Annex 15: Qualification and Validation.","url":"https://picscheme.org/docview/3443"},{"cita":"Comisión Europea. EU GMP Annex 1: Manufacture of Sterile Medicinal Products (2022).","url":"https://health.ec.europa.eu/system/files/2022-08/20220825_gmp-an1_en_0.pdf"},{"cita":"ICH. Quality Guidelines (índice oficial de las guías Q).","url":"https://www.ich.org/page/quality-guidelines"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Mapa del mundo estilizado con nodos conectados por líneas turquesa que representan la cooperación entre autoridades.","alt":"Convergencia regulatoria internacional entre autoridades sanitarias"}],"keywords":["qué es pic/s","pics gmp guía pe 009","convergencia regulatoria farmacéutica","pic/s colombia invima","diferencia entre ich y pic/s","anexo 1 y anexo 15 pics"],"mapa":{"centro":"Actores de la convergencia","ramas":[{"titulo":"OMS","icono":"Globe","nodos":["Guías de BPM y anexos","Precalificación","Base de muchas normas nacionales"]},{"titulo":"PIC/S","icono":"ShieldCheck","nodos":["Guía PE 009 y anexos","Formación de inspectores","Cooperación entre inspectorados"]},{"titulo":"ICH","icono":"Network","nodos":["Guías Q de calidad","Q9 riesgos y Q10 sistema de calidad","Armonización técnica"]},{"titulo":"Colombia","icono":"Landmark","nodos":["BPM por Resolución 1160 de 2016","Cooperación internacional del INVIMA","Ingreso del INVIMA a ICMRA"]}]},"proceso":{"titulo":"Cómo preparar una planta para exportar","intro":"","pasos":[{"titulo":"Identificar mercados","detalle":"Lista los países destino y sus autoridades sanitarias.","icono":"Globe","evidencia":"Plan de mercados."},{"titulo":"Comparar requisitos","detalle":"Contrasta las BPM colombianas con las guías que aplica cada autoridad (OMS, PIC/S, otras).","icono":"Scale","evidencia":"Análisis de brechas."},{"titulo":"Cerrar brechas","detalle":"Prioriza con análisis de riesgo las brechas que afectan la calidad y la aceptación de las inspecciones.","icono":"Wrench","evidencia":"Plan de acción con responsables."},{"titulo":"Autoinspeccionar con criterio internacional","detalle":"Usa las guías internacionales en tus autoinspecciones para anticipar hallazgos.","icono":"ClipboardCheck","evidencia":"Informe de autoinspección."},{"titulo":"Mantener la vigilancia normativa","detalle":"Sigue las nuevas versiones de guías y su adopción por el INVIMA.","icono":"RefreshCw","evidencia":"Registro de actualizaciones normativas."}]},"caso":{"titulo":"El Anexo 1 en una planta colombiana","contexto":"Una planta de inyectables colombiana discute si debe aplicar el Anexo 1 de 2022, porque «Colombia no lo adoptó textualmente».","pregunta":"¿Cuál es la mejor postura?","opciones":[{"texto":"Ignorarlo hasta que el INVIMA lo exija por resolución.","correcta":false,"retro":"Ignorar el estado del arte deja a la planta expuesta en inspecciones y la aleja de los mercados de exportación."},{"texto":"Cumplir la norma colombiana y usar el Anexo 1 y el TRS 1044 como referencia técnica para cerrar brechas priorizadas por riesgo, como la estrategia de control de la contaminación.","correcta":true,"retro":"Es la postura que protege al paciente, resiste una inspección y prepara la planta para exportar."},{"texto":"Copiar el Anexo 1 completo como procedimiento interno.","correcta":false,"retro":"Una guía no es un procedimiento: hay que traducirla a la realidad de la planta."}]}}$j$::jsonb;
