  END IF;

  -- 05. Decreto 677 de 1995 y Decreto 549 de 2001: base legal de la fabricación y la certificación
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Sin certificado no hay fabricación","texto":"Una empresa compra una planta en Funza, contrata personal y tiene listo el registro sanitario de un producto. Pero el INVIMA no le ha certificado las BPM. ¿Puede fabricar? No. La base legal que lo impide son dos decretos: uno define el régimen sanitario de los medicamentos y otro creó el procedimiento para certificar el cumplimiento de las BPM."},"objetivos":["Explicar qué regula el Decreto 677 de 1995 en materia de fabricación y control de calidad.","Describir el papel del Decreto 549 de 2001 en la certificación de BPM.","Relacionar estos decretos con el procedimiento vigente del Decreto 335 de 2022."],"conceptos":[{"icono":"Landmark","termino":"Decreto 677 de 1995","definicion":"Reglamenta el régimen de registros sanitarios, licencias, control de calidad y vigilancia sanitaria de los medicamentos y otros productos. Exige que los fabricantes cumplan las BPM."},{"icono":"ShieldCheck","termino":"Decreto 549 de 2001","definicion":"Estableció el procedimiento para obtener del INVIMA el certificado de cumplimiento de BPM de los laboratorios fabricantes de medicamentos."},{"icono":"FileCheck","termino":"Certificado de BPM","definicion":"El documento con el que el INVIMA declara que una planta cumple las BPM para determinadas áreas y formas farmacéuticas. Es requisito para fabricar."},{"icono":"RefreshCw","termino":"Decreto 335 de 2022","definicion":"Actualizó el procedimiento para obtener los certificados de cumplimiento de buenas prácticas ante el INVIMA."}],"secciones":[{"titulo":"El Decreto 677 de 1995: el marco general","parrafos":["El Decreto 677 de 1995 reglamenta el régimen de registros sanitarios, licencias, control de calidad y vigilancia sanitaria de los medicamentos, cosméticos, preparaciones farmacéuticas a base de recursos naturales y otros productos. Para la fabricación, su mensaje central es que los laboratorios fabricantes deben cumplir las Buenas Prácticas de Manufactura y que el INVIMA vigila ese cumplimiento.","El decreto también conecta el registro sanitario con el fabricante: el registro se otorga para un producto fabricado en un establecimiento determinado. Por eso un cambio de fabricante o de sitio de fabricación no es un asunto interno: tiene consecuencias regulatorias. El análisis de impacto normativo que publicó el Ministerio de Salud sobre este decreto muestra que sigue siendo una pieza central del sistema, aunque varias de sus partes se han modificado con normas posteriores."]},{"titulo":"Del Decreto 549 de 2001 al Decreto 335 de 2022","parrafos":["El Decreto 549 de 2001 estableció el procedimiento para que el INVIMA certificara el cumplimiento de las BPM en los laboratorios fabricantes de medicamentos. Introdujo la lógica que se mantiene: el interesado solicita, el INVIMA inspecciona con una guía y, si el concepto es favorable, expide un certificado para las áreas y formas farmacéuticas evaluadas.","En 2022, el Decreto 335 actualizó el procedimiento para obtener los certificados de cumplimiento de buenas prácticas. Lo verás en detalle en la unidad 5. Por ahora, la idea clave es la cadena: el **Decreto 677** obliga a cumplir BPM, la **Resolución 1160 de 2016** define qué son esas BPM y cómo se inspeccionan, y el **procedimiento de certificación** define cómo se demuestra el cumplimiento. Un certificado ampara áreas y formas farmacéuticas concretas: fabricar una forma no certificada es un incumplimiento aunque el resto de la planta esté certificada."]}],"errores":[{"error":"Creer que el certificado de BPM cubre toda la planta y cualquier producto.","correccion":"El certificado ampara áreas y formas farmacéuticas concretas; revisa su alcance."},{"error":"Cambiar de sitio de fabricación como un asunto interno.","correccion":"Un cambio de fabricante o de sitio tiene implicaciones regulatorias sobre el registro sanitario."}],"comprueba":[{"pregunta":"¿Qué decreto reglamenta el régimen de registros sanitarios y control de calidad de medicamentos?","respuesta":"El Decreto 677 de 1995."},{"pregunta":"¿Qué creó el Decreto 549 de 2001?","respuesta":"El procedimiento para que el INVIMA certifique el cumplimiento de BPM en los laboratorios fabricantes de medicamentos."},{"pregunta":"¿Qué norma actualizó el procedimiento de certificación en 2022?","respuesta":"El Decreto 335 de 2022."}],"resumen":["El **Decreto 677 de 1995** obliga a fabricar bajo BPM y conecta el registro sanitario con el fabricante.","El **Decreto 549 de 2001** creó la certificación de BPM; hoy el procedimiento lo regula el **Decreto 335 de 2022**.","El certificado ampara **áreas y formas farmacéuticas** concretas."],"referencias":[{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Presidencia de la República. Decreto 549 de 2001: certificado de cumplimiento de Buenas Prácticas de Manufactura.","url":"https://www.invima.gov.co/invima_website/static/attachments/normatividad_normatividad_interna/decreto-549-de-2001_2.pdf"},{"cita":"Presidencia de la República. Decreto 335 de 2022: procedimiento para obtener los certificados de cumplimiento de buenas prácticas.","url":"https://www.invima.gov.co/sites/default/files/medicamentos-y-productos-biologicos/tecnico-medicamentos/medicamentos-sintesis-quimica-y-biologica/Decreto%20No.%20335%20de%202022.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa de proceso","descripcion":"Cadena de eslabones con íconos: decreto, resolución, inspección, certificado y medicamento, en azul y turquesa.","alt":"Cadena legal de la fabricación de medicamentos en Colombia"}],"keywords":["decreto 677 de 1995","decreto 549 de 2001","certificado de bpm invima","certificación bpm colombia","decreto 677 resumen","base legal bpm colombia","decreto 335 de 2022"],"mapa":{"centro":"Base legal de la fabricación en Colombia","ramas":[{"titulo":"Régimen sanitario","icono":"Landmark","nodos":["Decreto 677 de 1995","Registros sanitarios","Control de calidad y vigilancia"]},{"titulo":"Certificación","icono":"ShieldCheck","nodos":["Decreto 549 de 2001","Certificado de BPM por áreas","Hoy: Decreto 335 de 2022"]},{"titulo":"Contenido técnico","icono":"BookOpen","nodos":["Resolución 1160 de 2016","Manuales de BPM","Guías de inspección"]},{"titulo":"Autoridad","icono":"Gavel","nodos":["INVIMA certifica e inspecciona","Medidas sanitarias","Vigilancia posterior"]}]},"proceso":{"titulo":"La cadena legal de un medicamento fabricado en Colombia","intro":"","pasos":[{"titulo":"Cumplir las BPM","detalle":"La planta implementa las BPM de la Resolución 1160 de 2016 en las áreas que va a usar.","icono":"Factory","evidencia":"Sistema de calidad implementado."},{"titulo":"Solicitar la certificación","detalle":"El fabricante solicita al INVIMA la certificación para sus áreas y formas farmacéuticas.","icono":"FileText","evidencia":"Solicitud radicada."},{"titulo":"Recibir la inspección","detalle":"El INVIMA inspecciona con la guía correspondiente y emite un concepto.","icono":"ShieldCheck","evidencia":"Acta de visita."},{"titulo":"Obtener el certificado","detalle":"Con concepto favorable, el INVIMA expide el certificado de BPM para lo evaluado.","icono":"Award","evidencia":"Certificado vigente."},{"titulo":"Fabricar productos registrados","detalle":"Solo se fabrican productos con registro sanitario en áreas certificadas.","icono":"Pill","evidencia":"Registro sanitario y certificado alineados."},{"titulo":"Mantener y renovar","detalle":"El cumplimiento se sostiene, se vigila y el certificado se renueva según el procedimiento vigente.","icono":"RefreshCw","evidencia":"Autoinspecciones y renovación."}]},"caso":{"titulo":"Una forma farmacéutica nueva","contexto":"Una planta certificada para sólidos orales no estériles quiere empezar a fabricar suspensiones orales en un área nueva, ya construida y calificada.","pregunta":"¿Qué necesita antes de fabricar para el mercado?","opciones":[{"texto":"Nada más, porque la planta ya tiene certificado de BPM.","correcta":false,"retro":"El certificado ampara las áreas y formas farmacéuticas evaluadas; una forma nueva en un área nueva requiere su propia certificación."},{"texto":"Obtener la certificación de BPM del INVIMA para el área y la forma farmacéutica nuevas, y asegurar que el registro sanitario del producto ampare ese fabricante.","correcta":true,"retro":"Es la cadena completa: BPM certificadas para lo que se fabrica y registro sanitario coherente."},{"texto":"Fabricar los primeros lotes y avisar al INVIMA en la siguiente visita.","correcta":false,"retro":"Fabricar en un área no certificada para el mercado es un incumplimiento que puede derivar en medidas sanitarias."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Decreto 677 de 1995 y Decreto 549 de 2001: base legal de la fabricación y la certificación$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Decreto 677 de 1995 y Decreto 549 de 2001: base legal de la fabricación y la certificación$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 06. Resolución 1160 de 2016: manuales y guías de inspección
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Leer la norma con los ojos del inspector","texto":"Dos plantas tienen el mismo manual de calidad. Una pasa la visita del INVIMA sin hallazgos mayores; la otra recibe un concepto con requerimientos. La diferencia no está en el manual sino en que la primera usó las guías de inspección de la Resolución 1160 de 2016 para autoevaluarse: sabía exactamente qué le iban a preguntar."},"objetivos":["Describir la estructura de la Resolución 1160 de 2016: manuales de BPM y guías de inspección.","Diferenciar el manual general de BPM del manual para estériles.","Usar las guías de inspección como herramienta de autoevaluación.","Reconocer las modificaciones posteriores, como la Resolución 886 de 2019."],"conceptos":[{"icono":"BookOpen","termino":"Manual de BPM","definicion":"El texto que describe los requisitos: sistema de calidad, personal, instalaciones, equipos, materiales, documentación, producción, control de calidad, contratos, quejas, retiros y autoinspección."},{"icono":"Syringe","termino":"Manual para estériles","definicion":"Requisitos adicionales para fabricar productos estériles: áreas limpias por grados, procesamiento aséptico, esterilización y monitoreo."},{"icono":"ClipboardCheck","termino":"Guía de inspección","definicion":"La lista de verificación con la que el INVIMA evalúa el cumplimiento. Hay una general y una para estériles."},{"icono":"RefreshCw","termino":"Modificaciones","definicion":"La resolución ha tenido ajustes posteriores, como la Resolución 886 de 2019. Por eso conviene consultar el texto compilado del normograma del INVIMA."}],"secciones":[{"titulo":"Qué trae la resolución","parrafos":["La Resolución 1160 de 2016 del Ministerio de Salud y Protección Social establece los manuales de Buenas Prácticas de Manufactura y las guías de inspección para los laboratorios o establecimientos de producción de medicamentos, con miras a la obtención del certificado de cumplimiento de BPM. Sus anexos incluyen un manual general de BPM, un manual para medicamentos estériles y las guías de inspección correspondientes.","Los manuales siguen la estructura de las BPM de la OMS: gestión de la calidad, saneamiento e higiene, calificación y validación, quejas, retiros, contratos, autoinspección, personal, instalaciones, equipos, materiales, documentación, producción y control de calidad. El manual para estériles agrega los requisitos de áreas limpias, procesamiento aséptico, esterilización y monitoreo ambiental que verás en la unidad 4."]},{"titulo":"Las guías de inspección como herramienta propia","parrafos":["Las guías de inspección convierten los manuales en preguntas verificables: ¿existe el procedimiento?, ¿está aprobado?, ¿se ejecuta como está escrito?, ¿hay registros?, ¿se investigan las desviaciones? El inspector las usa durante la visita y, con ellas, clasifica las deficiencias según su riesgo.","La mejor forma de preparar una visita es usar esas mismas guías en la **autoinspección**. Así la planta encuentra sus brechas antes que el inspector y llega con un plan de mejoramiento en marcha. La resolución ha tenido modificaciones, como la Resolución 886 de 2019, por lo que es buena práctica consultar el texto compilado que publica el INVIMA en su normograma antes de actualizar procedimientos."]}],"errores":[{"error":"Usar una versión desactualizada de la resolución.","correccion":"Consulta el texto compilado del normograma del INVIMA con sus modificaciones."},{"error":"Preparar la visita solo revisando documentos.","correccion":"La guía verifica que lo escrito se cumpla en la práctica: recorre la planta."}],"comprueba":[{"pregunta":"¿Qué establece la Resolución 1160 de 2016?","respuesta":"Los manuales de BPM y las guías de inspección para obtener el certificado de cumplimiento de BPM."},{"pregunta":"¿Para qué sirven las guías de inspección dentro de la empresa?","respuesta":"Para autoinspeccionarse con los mismos criterios del INVIMA y cerrar brechas antes de la visita."}],"resumen":["La Resolución 1160 de 2016 trae **manuales de BPM y guías de inspección**.","Hay requisitos generales y **adicionales para estériles**.","La guía de inspección es la mejor **herramienta de autoevaluación**."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"},{"cita":"Ministerio de Salud y Protección Social. Resolución 886 de 2019, que modifica la Resolución 1160 de 2016.","url":"https://ambitojuridico.com/sites/default/files/BancoMedios/Archivos/res-0886-19%28minsalud%29.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Carpeta abierta con cuatro separadores (manual general, manual estériles, guía general, guía estériles) en colores de marca.","alt":"Estructura de la Resolución 1160 de 2016"}],"keywords":["resolución 1160 de 2016","resolución 1160 de 2016 bpm","guía de inspección bpm invima","manual de bpm colombia","resolución 886 de 2019","anexos resolución 1160","bpm medicamentos estériles colombia"],"mapa":{"centro":"Resolución 1160 de 2016","ramas":[{"titulo":"Manuales","icono":"BookOpen","nodos":["Manual general de BPM","Manual para medicamentos estériles","Basados en los informes de la OMS"]},{"titulo":"Guías de inspección","icono":"ClipboardCheck","nodos":["Guía general","Guía para estériles","Criterios de evaluación"]},{"titulo":"Uso interno","icono":"Search","nodos":["Autoinspección","Análisis de brechas","Preparación de visitas"]},{"titulo":"Vigencia","icono":"RefreshCw","nodos":["Resolución 886 de 2019","Texto compilado del INVIMA","Vigilancia normativa"]}]},"proceso":{"titulo":"Autoevaluación con la guía de inspección","intro":"","pasos":[{"titulo":"Descargar la versión vigente","detalle":"Consulta el texto compilado de la resolución y la guía que aplica a tus áreas (general o estériles).","icono":"FileText","evidencia":"Versión y fecha de consulta registradas."},{"titulo":"Asignar capítulos","detalle":"Reparte los capítulos entre auditores independientes del área evaluada.","icono":"Users","evidencia":"Plan de autoinspección."},{"titulo":"Verificar en sitio","detalle":"Responde cada pregunta con evidencia: documento, registro u observación directa.","icono":"Search","evidencia":"Lista de verificación diligenciada."},{"titulo":"Clasificar hallazgos","detalle":"Clasifica cada brecha como crítica, mayor o menor según su riesgo.","icono":"AlertTriangle","evidencia":"Informe de hallazgos."},{"titulo":"Planear y cerrar","detalle":"Define acciones, responsables y fechas; verifica el cierre con evidencia.","icono":"CheckCircle2","evidencia":"Plan de mejoramiento con cierres."}]},"caso":{"titulo":"Un manual de calidad impecable","contexto":"El manual de calidad de una planta cita la Resolución 1160 de 2016 en cada capítulo. En la autoinspección, el auditor encuentra que tres procedimientos de limpieza no se siguen como están escritos.","pregunta":"¿Cómo clasificarías la situación frente a la guía de inspección?","opciones":[{"texto":"Sin hallazgo, porque los procedimientos existen y citan la norma.","correcta":false,"retro":"La guía no pregunta solo si el documento existe, sino si se cumple. Un procedimiento que no se sigue es una deficiencia."},{"texto":"Como un hallazgo cuya gravedad depende del riesgo: si la limpieza afecta productos o hay riesgo de contaminación cruzada, puede ser mayor; se investiga la causa y se corrige.","correcta":true,"retro":"La clasificación depende del riesgo para el producto. Tres procedimientos incumplidos sugieren además una falla del sistema."},{"texto":"Como un hallazgo menor siempre, porque es solo documentación.","correcta":false,"retro":"No es solo documentación: refleja lo que pasa en la planta y puede afectar la calidad del producto."}]}}$j$::jsonb;
