  END IF;

  -- 07. Normas especiales: Res. 3028/2008 (áreas especiales), fitoterapéuticos (Res. 3131/1998, Decreto 2266/2004)
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"No todos los productos caben en la misma área","texto":"Una planta de sólidos quiere aprovechar la capacidad de su línea para fabricar un antibiótico de la familia de las penicilinas. En papel, la máquina es la misma. En la realidad, una traza de penicilina en otro producto puede causar una reacción alérgica grave a un paciente sensible. Para estos casos existen normas especiales que exigen áreas separadas y requisitos propios."},"objetivos":["Explicar qué regula la Resolución 3028 de 2008 sobre áreas técnicas y áreas especiales.","Reconocer por qué ciertos productos exigen instalaciones exclusivas.","Ubicar el marco de los productos fitoterapéuticos: Resolución 3131 de 1998 y Decreto 2266 de 2004."],"conceptos":[{"icono":"Building2","termino":"Áreas técnicas de producción","definicion":"Las áreas de un establecimiento farmacéutico definidas por la Resolución 3028 de 2008 según los productos y formas farmacéuticas que se fabrican."},{"icono":"Lock","termino":"Áreas especiales","definicion":"Áreas que se exigen separadas o exclusivas para productos de alto riesgo de sensibilización o toxicidad, como los betalactámicos."},{"icono":"Sparkles","termino":"Productos fitoterapéuticos","definicion":"Productos elaborados con plantas medicinales. Tienen un régimen propio de registro y vigilancia (Decreto 2266 de 2004) y un manual de BPM específico (Resolución 3131 de 1998)."},{"icono":"Biohazard","termino":"Sensibilización","definicion":"Capacidad de un producto de causar reacciones alérgicas con cantidades mínimas. Es la razón de fondo de las áreas exclusivas para penicilinas y cefalosporinas."}],"secciones":[{"titulo":"Áreas técnicas y áreas especiales","parrafos":["La Resolución 3028 de 2008 define las áreas técnicas de producción de los establecimientos farmacéuticos y las áreas especiales que se requieren para ciertos grupos de productos. Su lógica es la del riesgo: hay productos que, aun en cantidades mínimas, pueden dañar a un paciente que los recibe sin necesitarlos. El ejemplo clásico son los **betalactámicos** (penicilinas y cefalosporinas), cuya capacidad de sensibilización obliga a fabricarlos en instalaciones exclusivas y separadas, con sistemas de aire independientes.","Al planear una ampliación o un producto nuevo, la primera pregunta no es si «cabe en la máquina», sino en qué área técnica puede fabricarse y si el certificado de BPM de la planta la ampara. Fabricar un producto que exige área especial en un área común es una deficiencia grave por el riesgo directo para los pacientes. En la unidad 3 verás con más detalle el control de los productos de alto riesgo."]},{"titulo":"Fitoterapéuticos: un régimen propio","parrafos":["Los productos fitoterapéuticos se elaboran con material vegetal y tienen retos distintos: variabilidad natural de la planta, contaminación microbiológica y por plaguicidas o metales, identificación botánica y control de marcadores. El Decreto 2266 de 2004 reglamenta su régimen de registros sanitarios y de vigilancia y control, y la Resolución 3131 de 1998 adoptó el manual de BPM para productos farmacéuticos con base en recursos naturales.","Para quien trabaja en estas plantas, la recepción e identificación de la materia prima vegetal es tan crítica como el proceso. Un error de especie o una adulteración pueden cambiar por completo la seguridad del producto, aunque el resto del proceso sea impecable."]}],"errores":[{"error":"Decidir la fabricación de un producto solo por capacidad de equipos.","correccion":"Primero verifica el área técnica exigida y el alcance del certificado de BPM."},{"error":"Tratar la materia prima vegetal como un excipiente más.","correccion":"Aplica identificación botánica y controles de contaminantes según el manual específico."}],"comprueba":[{"pregunta":"¿Qué define la Resolución 3028 de 2008?","respuesta":"Las áreas técnicas de producción de los establecimientos farmacéuticos y las áreas especiales para ciertos productos."},{"pregunta":"¿Por qué los betalactámicos requieren área exclusiva?","respuesta":"Por su capacidad de sensibilización: trazas mínimas pueden causar reacciones alérgicas graves."},{"pregunta":"¿Qué normas aplican a los fitoterapéuticos?","respuesta":"El Decreto 2266 de 2004 (registro y vigilancia) y la Resolución 3131 de 1998 (manual de BPM)."}],"resumen":["La **Resolución 3028 de 2008** define áreas técnicas y **áreas especiales**.","Los **betalactámicos** exigen instalaciones exclusivas por riesgo de sensibilización.","Los fitoterapéuticos tienen **régimen y BPM propios**."],"referencias":[{"cita":"Ministerio de la Protección Social. Resolución 3028 de 2008: áreas técnicas de producción y áreas especiales.","url":"https://normograma.invima.gov.co/compilacion/docs/resolucion_minproteccion_3028_2008.htm"},{"cita":"Ministerio de Salud. Resolución 3131 de 1998: Manual de BPM para productos farmacéuticos con base en recursos naturales.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/RESOLUCION-3131-de-1998.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"}],"imagenes":[{"ubicacion":"En la sección de áreas","descripcion":"Plano de planta con un área de betalactámicos aislada, con su propio sistema de aire y esclusas, separada de las áreas generales.","alt":"Área especial exclusiva para betalactámicos separada de la producción general"}],"keywords":["resolución 3028 de 2008","áreas especiales betalactámicos","áreas técnicas de producción farmacéutica","resolución 3131 de 1998","decreto 2266 de 2004","bpm fitoterapéuticos","betalactámicos área exclusiva"],"mapa":{"centro":"Normas especiales de fabricación","ramas":[{"titulo":"Áreas","icono":"Building2","nodos":["Resolución 3028 de 2008","Áreas técnicas por producto","Áreas especiales separadas"]},{"titulo":"Alto riesgo","icono":"Biohazard","nodos":["Betalactámicos","Otros productos de alta potencia","Contención y segregación"]},{"titulo":"Fitoterapéuticos","icono":"Sparkles","nodos":["Resolución 3131 de 1998 (BPM)","Decreto 2266 de 2004 (registro)","Materias primas vegetales"]},{"titulo":"Qué verificar","icono":"ClipboardCheck","nodos":["Alcance del certificado","Flujos y presiones","Validación de limpieza"]}]},"proceso":{"titulo":"Antes de fabricar un producto nuevo en la planta","intro":"","pasos":[{"titulo":"Clasificar el producto","detalle":"Determina su grupo: general, alto riesgo de sensibilización, alta potencia o fitoterapéutico.","icono":"Tag","evidencia":"Ficha del producto."},{"titulo":"Identificar el área técnica","detalle":"Revisa la Resolución 3028 de 2008 y las normas especiales que apliquen.","icono":"Building2","evidencia":"Análisis normativo."},{"titulo":"Verificar el certificado","detalle":"Confirma que el certificado de BPM ampare esa área y forma farmacéutica.","icono":"ShieldCheck","evidencia":"Alcance del certificado."},{"titulo":"Evaluar el riesgo de contaminación cruzada","detalle":"Analiza flujos, aire, equipos compartidos y limpieza con criterio de riesgo.","icono":"AlertTriangle","evidencia":"Evaluación de riesgo."},{"titulo":"Decidir por control de cambios","detalle":"Aprueba, ajusta o rechaza la introducción del producto con evidencia.","icono":"GitBranch","evidencia":"Control de cambios cerrado."}]},"caso":{"titulo":"La cefalosporina en la línea de sólidos","contexto":"Un cliente pide fabricar por contrato una cefalosporina oral. La planta tiene capacidad ociosa en su línea de sólidos generales y la limpieza está validada para los productos actuales.","pregunta":"¿Qué responde aseguramiento de calidad?","opciones":[{"texto":"Aceptar, porque la limpieza está validada.","correcta":false,"retro":"La limpieza validada para otros productos no resuelve el riesgo de sensibilización de los betalactámicos, que exigen área especial."},{"texto":"No aceptar en la línea general: las cefalosporinas requieren área especial exclusiva y separada, con certificación de BPM para esa área.","correcta":true,"retro":"Es un requisito de diseño, no de limpieza. La respuesta protege a los pacientes de los demás productos."},{"texto":"Aceptar haciendo una campaña al final del año.","correcta":false,"retro":"Las campañas no sustituyen la segregación que exigen los betalactámicos."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Normas especiales: Res. 3028/2008 (áreas especiales), fitoterapéuticos (Res. 3131/1998, Decreto 2266/2004)$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Normas especiales: Res. 3028/2008 (áreas especiales), fitoterapéuticos (Res. 3131/1998, Decreto 2266/2004)$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
