    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 08. Introducción a la unidad: los recursos que sostienen las BPM
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"El mejor procedimiento falla en una mala instalación","texto":"Un laboratorio escribió procedimientos impecables para evitar la contaminación cruzada. Pero la sala de pesaje compartía el aire con el pasillo, los operarios cruzaban por la misma puerta con material limpio y sucio, y el agua purificada tenía un ramal sin recirculación. Los papeles estaban bien; los recursos no. Esta unidad trata de lo que sostiene a las BPM en el mundo físico."},"objetivos":["Identificar los cuatro grupos de recursos que exigen las BPM.","Relacionar cada recurso con los riesgos que controla.","Anticipar los temas de la unidad: personal, higiene, instalaciones, equipos, agua, aire y áreas limpias."],"conceptos":[{"icono":"Users","termino":"Personal","definicion":"Suficiente, calificado y entrenado, con responsabilidades escritas. Es el recurso que más influye en el cumplimiento diario."},{"icono":"Building2","termino":"Instalaciones","definicion":"Ubicadas, diseñadas y mantenidas para minimizar errores y permitir una limpieza eficaz, con flujos ordenados de personas y materiales."},{"icono":"Wrench","termino":"Equipos","definicion":"Adecuados para su uso, fáciles de limpiar, calificados, calibrados y mantenidos."},{"icono":"Droplets","termino":"Sistemas de apoyo críticos","definicion":"Agua, aire (HVAC), vapor y gases que tocan el producto o su entorno. Se diseñan, califican y monitorean como parte del proceso."}],"secciones":[{"titulo":"Por qué los recursos van antes que los procesos","parrafos":["Las BPM de la OMS dedican capítulos completos al personal, las instalaciones y los equipos antes de hablar de producción. La razón es práctica: un proceso validado solo es reproducible si las personas saben ejecutarlo, si el espacio impide confusiones y si los equipos y servicios trabajan dentro de lo especificado.","Cada recurso controla riesgos concretos. Un personal mal entrenado produce errores y mezclas. Unas instalaciones mal diseñadas facilitan la contaminación cruzada. Un equipo sin calibrar entrega datos falsos. Un sistema de agua mal mantenido puede contaminar todos los productos líquidos de la planta. Por eso el inspector del INVIMA recorre la planta, entrevista al personal y revisa los registros de mantenimiento, no solo los procedimientos.","En esta unidad recorrerás esos recursos en orden: primero las personas y su higiene, luego el diseño de instalaciones, después los equipos y, por último, los sistemas críticos de agua y aire y la clasificación de áreas limpias."]}],"errores":[{"error":"Compensar con procedimientos un problema de diseño.","correccion":"Cuando el riesgo es físico, la solución también debe serlo: barreras, aire, flujos."},{"error":"Olvidar los servicios como el agua y el aire.","correccion":"Trátalos como parte del producto: se califican y monitorean."}],"comprueba":[{"pregunta":"¿Cuáles son los cuatro grupos de recursos de esta unidad?","respuesta":"Personal, instalaciones, equipos y sistemas de apoyo críticos."},{"pregunta":"¿Por qué el inspector recorre la planta?","respuesta":"Porque verifica que los recursos reales permitan cumplir lo que dicen los documentos."}],"resumen":["Las BPM se sostienen en **personas, espacios, equipos y servicios**.","Cada recurso **controla un riesgo** concreto.","Un diseño deficiente **no se compensa** con papeles."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Cuatro columnas ilustradas que sostienen un techo con la sigla BPM: personas, espacios, equipos y servicios, en la paleta de Edvanta.","alt":"Los cuatro recursos que sostienen las Buenas Prácticas de Manufactura"}],"keywords":["recursos bpm","personal instalaciones y equipos bpm","requisitos de instalaciones farmacéuticas","bpm personal y equipos","sistemas de apoyo crítico farmacéutico"],"mapa":{"centro":"Recursos que sostienen las BPM","ramas":[{"titulo":"Personas","icono":"Users","nodos":["Personal clave","Capacitación","Higiene y vestimenta"]},{"titulo":"Espacios","icono":"Building2","nodos":["Flujos y esclusas","Acabados sanitarios","Áreas limpias"]},{"titulo":"Máquinas","icono":"Wrench","nodos":["Calificación","Calibración","Mantenimiento y limpieza"]},{"titulo":"Servicios","icono":"Wind","nodos":["Agua farmacéutica","HVAC","Vapor y gases"]}]},"proceso":{"titulo":"Cómo se verifica un recurso antes de usarlo","intro":"","pasos":[{"titulo":"Definir requisitos","detalle":"Qué competencias, qué área, qué equipo o qué calidad de servicio necesita el proceso.","icono":"ClipboardList","evidencia":"Perfiles de cargo, URS y especificaciones."},{"titulo":"Proveer el recurso","detalle":"Contratar y entrenar, construir, comprar e instalar según lo especificado.","icono":"Factory","evidencia":"Registros de compra, obra y contratación."},{"titulo":"Demostrar que es apto","detalle":"Evaluar la competencia, calificar el área y los equipos, calificar los sistemas.","icono":"ClipboardCheck","evidencia":"Evaluaciones y calificaciones aprobadas."},{"titulo":"Mantenerlo bajo control","detalle":"Reentrenar, limpiar, calibrar, mantener y monitorear.","icono":"RefreshCw","evidencia":"Programas y registros de mantenimiento."}]},"caso":{"titulo":"Dónde invertir primero","contexto":"Una planta pequeña tiene presupuesto para una sola mejora este año: nuevos procedimientos escritos, una esclusa para la sala de pesaje o software de gestión documental. La sala de pesaje comparte aire con el pasillo y allí se pesan activos potentes.","pregunta":"¿Qué priorizarías con criterio de riesgo?","opciones":[{"texto":"El software de gestión documental, porque ordena todo.","correcta":false,"retro":"Ayuda, pero no controla el riesgo físico de contaminación cruzada que hoy existe."},{"texto":"La esclusa y el control de aire de la sala de pesaje, porque contiene el riesgo más alto para el producto y el personal.","correcta":true,"retro":"Las BPM priorizan los riesgos para el paciente. Un procedimiento no compensa un diseño que dispersa polvo de activos potentes."},{"texto":"Reescribir los procedimientos de pesaje.","correcta":false,"retro":"Útil, pero insuficiente si el espacio sigue permitiendo la dispersión."}]}}$j$::jsonb;
