  -- 09. Personal clave, responsabilidades y capacitación
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"¿Quién libera este lote?","texto":"Un viernes en la tarde, el jefe de producción está de vacaciones, la directora técnica en una reunión externa y hay un lote que el cliente necesita el lunes. El supervisor de turno pregunta si puede firmar la liberación «para no perder la venta». La respuesta depende de algo que las BPM exigen escribir antes de que pase: quiénes son las personas clave y qué puede delegarse."},"objetivos":["Identificar el personal clave que exigen las BPM y sus responsabilidades.","Explicar la independencia entre producción y control de calidad.","Diseñar un programa de capacitación con evaluación de eficacia."],"conceptos":[{"icono":"UserCheck","termino":"Personal clave","definicion":"Los responsables de producción, de control de calidad y la persona autorizada que libera los lotes. Deben ser profesionales calificados, de tiempo completo y con funciones escritas."},{"icono":"Signature","termino":"Persona autorizada","definicion":"Quien certifica que cada lote se fabricó y controló según las BPM y el registro sanitario antes de liberarlo. En Colombia esta responsabilidad suele recaer en la dirección técnica."},{"icono":"Scale","termino":"Independencia","definicion":"Producción y control de calidad deben tener jefaturas distintas e independientes: quien fabrica no decide si su producto cumple."},{"icono":"GraduationCap","termino":"Capacitación eficaz","definicion":"Entrenamiento inicial y continuo en BPM y en las tareas del cargo, con evaluación de que la persona realmente aprendió y lo aplica."}],"secciones":[{"titulo":"Quiénes son y qué no se puede mezclar","parrafos":["Las BPM exigen que la empresa tenga personal suficiente y calificado y que las responsabilidades de cada persona estén escritas en descripciones de cargo, sin vacíos ni superposiciones. Entre todo el personal, hay tres funciones clave: el responsable de **producción**, el responsable de **control de calidad** y la **persona autorizada** que libera cada lote.","La regla central es la **independencia**: los responsables de producción y de control de calidad deben ser personas distintas y ninguno debe depender del otro. Si quien fabrica decidiera si su lote cumple, la presión por producir pesaría sobre la decisión de calidad. Las funciones clave pueden delegarse en personas calificadas, por escrito, pero la responsabilidad no se transfiere.","En el caso del viernes, la respuesta correcta está escrita de antemano: si la liberación requiere a la persona autorizada y no hay un suplente designado y calificado, el lote espera. Ninguna venta justifica una liberación firmada por quien no tiene la autoridad ni la formación."]},{"titulo":"Capacitar para que cambie la práctica","parrafos":["Todo el personal que entra a las áreas de producción y control debe recibir capacitación inicial en BPM y entrenamiento en los procedimientos de su cargo, además de capacitación continua. Quien trabaja en áreas limpias o con materiales potentes, tóxicos o sensibilizantes necesita entrenamiento específico. Los visitantes y el personal no entrenado solo entran con supervisión e información previa.","Un registro de asistencia no demuestra aprendizaje. Un programa sólido define qué debe saber cada cargo (matriz de entrenamiento), entrena antes de que la persona ejecute la tarea, **evalúa la eficacia** (evaluación escrita, observación en el puesto o desempeño en indicadores) y reentrena cuando cambia un procedimiento o cuando una desviación revela una brecha."]}],"errores":[{"error":"Descripciones de cargo genéricas que no dicen quién decide qué.","correccion":"Escribe responsabilidades concretas, sin vacíos ni superposiciones, y quiénes son los suplentes."},{"error":"Medir la capacitación por asistencia.","correccion":"Evalúa la eficacia: conocimiento, ejecución en el puesto o indicadores."},{"error":"Dejar que producción y calidad dependan de la misma jefatura operativa.","correccion":"Garantiza la independencia de control de calidad en el organigrama y en la práctica."}],"comprueba":[{"pregunta":"¿Quiénes son el personal clave según las BPM?","respuesta":"El responsable de producción, el de control de calidad y la persona autorizada que libera los lotes."},{"pregunta":"¿Por qué producción y control de calidad deben ser independientes?","respuesta":"Para que la presión por producir no influya en la decisión de si un producto cumple."},{"pregunta":"¿Cómo se demuestra que una capacitación fue eficaz?","respuesta":"Con evaluación del aprendizaje y de su aplicación: prueba, observación en el puesto o indicadores."}],"resumen":["Tres funciones clave: **producción, control de calidad y persona autorizada**.","Producción y calidad son **independientes**; la responsabilidad no se delega.","La capacitación vale cuando **cambia la práctica** y se demuestra."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10 Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"}],"imagenes":[{"ubicacion":"En la sección de personal clave","descripcion":"Organigrama ilustrado con tres figuras destacadas (producción, control de calidad y persona autorizada) y una línea que muestra su independencia.","alt":"Personal clave de las BPM y su independencia"}],"keywords":["personal clave bpm","persona autorizada liberación de lotes","capacitación en bpm","matriz de entrenamiento farmacéutica","independencia control de calidad y producción","director técnico laboratorio farmacéutico","eficacia de la capacitación bpm"],"mapa":{"centro":"Personas que hacen cumplir las BPM","ramas":[{"titulo":"Personal clave","icono":"UserCheck","nodos":["Jefe de producción","Jefe de control de calidad","Persona autorizada"]},{"titulo":"Reglas","icono":"Scale","nodos":["Funciones escritas","Sin vacíos ni superposiciones","Independencia producción–calidad"]},{"titulo":"Capacitación","icono":"GraduationCap","nodos":["Inducción en BPM","Entrenamiento en procedimientos","Evaluación de eficacia"]},{"titulo":"Delegación","icono":"Users","nodos":["Solo a personas calificadas","Por escrito","La responsabilidad no se delega"]}]},"proceso":{"titulo":"Programa de capacitación con eficacia demostrada","intro":"","pasos":[{"titulo":"Matriz de entrenamiento","detalle":"Define, por cargo, los procedimientos y temas de BPM que cada persona debe dominar.","icono":"ClipboardList","evidencia":"Matriz aprobada."},{"titulo":"Inducción en BPM","detalle":"Antes de entrar a producción, la persona recibe los principios de BPM, higiene y seguridad.","icono":"GraduationCap","evidencia":"Registro de inducción."},{"titulo":"Entrenamiento en el puesto","detalle":"Un entrenador calificado enseña y observa la tarea hasta que la persona la ejecuta sola.","icono":"Users","evidencia":"Registro de entrenamiento firmado."},{"titulo":"Evaluar la eficacia","detalle":"Evalúa con prueba escrita, observación o indicadores que la persona aplica lo aprendido.","icono":"Target","evidencia":"Resultados de evaluación."},{"titulo":"Autorizar","detalle":"Solo con evaluación aprobada se habilita a la persona para ejecutar la tarea de forma independiente.","icono":"BadgeCheck","evidencia":"Autorización registrada."},{"titulo":"Reentrenar","detalle":"Cuando cambia un procedimiento o una desviación revela una brecha, se reentrena y se reevalúa.","icono":"RefreshCw","evidencia":"Registro de reentrenamiento."}]},"caso":{"titulo":"La liberación del viernes","contexto":"La persona autorizada no está y no hay suplente designado. El supervisor de producción ofrece firmar la liberación porque «conoce el producto mejor que nadie».","pregunta":"¿Qué corresponde?","opciones":[{"texto":"Aceptar la firma del supervisor porque conoce el proceso.","correcta":false,"retro":"Conocer el proceso no le da independencia ni autoridad para liberar. Viola la separación entre producción y calidad."},{"texto":"Mantener el lote retenido hasta que lo revise la persona autorizada o un suplente designado por escrito y calificado, y registrar la necesidad de nombrar suplentes.","correcta":true,"retro":"Protege la independencia de la decisión y revela una brecha del sistema: debe haber suplentes formalmente designados."},{"texto":"Liberar y que la persona autorizada firme el lunes.","correcta":false,"retro":"Firmar después lo que se decidió sin ella es una falla de integridad de datos y de BPM."}]}}$j$::jsonb;
