  END IF;

  -- 10. Higiene personal, salud y vestimenta por áreas
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La mayor fuente de partículas camina","texto":"Una persona en reposo desprende miles de partículas por minuto; al caminar, muchas más. Cada partícula puede llevar microorganismos. En un área de sólidos eso puede contaminar un granulado; en un área estéril puede arruinar un lote completo. Por eso la higiene y la vestimenta no son asuntos de presentación personal: son controles del proceso."},"objetivos":["Describir los requisitos de salud e higiene del personal en BPM.","Relacionar la vestimenta con el tipo de área y el riesgo del producto.","Aplicar un procedimiento de ingreso y vestido a un área de producción."],"conceptos":[{"icono":"Hand","termino":"Higiene personal","definicion":"Lavado de manos, uñas cortas, sin joyas ni cosméticos que se desprendan, y prohibición de comer, beber o fumar en áreas de producción y almacenamiento."},{"icono":"UserCheck","termino":"Control de salud","definicion":"Exámenes al ingreso y periódicos, y la obligación de reportar enfermedades o lesiones abiertas que puedan afectar el producto."},{"icono":"Shirt","termino":"Vestimenta por áreas","definicion":"Uniforme adecuado a la operación y al grado del área, que protege el producto de la persona y, cuando aplica, a la persona del producto."},{"icono":"DoorOpen","termino":"Vestier y esclusa","definicion":"Zonas de cambio de ropa ordenadas por etapas, de lo sucio a lo limpio, que separan el exterior del área de producción."}],"secciones":[{"titulo":"Salud e higiene: requisitos de todos los días","parrafos":["Las BPM piden exámenes de salud al ingreso y con la periodicidad que defina la empresa, y que nadie con una enfermedad infecciosa o lesiones abiertas en zonas expuestas trabaje en contacto con el producto. Para que esto funcione, el personal debe saber que **reportar no lo castiga**: si una persona oculta una gripa o una herida por miedo a perder el día, el control falla.","Las prácticas de higiene son concretas: lavado y desinfección de manos al ingresar y después de cualquier contaminación, uñas cortas y sin esmalte, sin joyas, relojes ni maquillaje que se desprenda, y prohibición de comer, beber, fumar o guardar alimentos y medicamentos personales en las áreas de producción, laboratorio y almacenamiento. Las instrucciones deben estar visibles en los vestieres."]},{"titulo":"Vestimenta según el área","parrafos":["La vestimenta se escoge según el riesgo. En áreas de producción de **no estériles**, el uniforme suele incluir ropa de trabajo limpia de uso exclusivo, cofia que cubra todo el cabello, cubrebarba cuando aplique, calzado exclusivo o cubrezapatos, y tapabocas y guantes en las operaciones con producto expuesto. Para productos potentes se suman protección respiratoria y vestimenta que proteja al operario.","En áreas **estériles** los requisitos aumentan con el grado: en los grados A y B se usa vestimenta estéril de una pieza o de dos piezas que cubra cabeza, cara, cuerpo, manos y pies, con un proceso de vestido calificado y entrenamiento demostrado. Lo verás en la unidad 4. El vestier se diseña por etapas, de lo sucio a lo limpio, con un banco o línea que separe las zonas, y la secuencia de vestido se publica con imágenes."]}],"errores":[{"error":"Usar el uniforme fuera de la planta.","correccion":"La ropa de trabajo es de uso exclusivo y se cambia en el vestier."},{"error":"Cofias que dejan cabello expuesto.","correccion":"Toda la cabellera y la barba deben quedar cubiertas."},{"error":"Castigar a quien reporta una enfermedad.","correccion":"Promueve el reporte: es la única forma de que el control de salud funcione."}],"comprueba":[{"pregunta":"¿Por qué el personal es una fuente importante de contaminación?","respuesta":"Porque desprende partículas y microorganismos, más aún al moverse."},{"pregunta":"¿Qué está prohibido en las áreas de producción?","respuesta":"Comer, beber, fumar y guardar alimentos o medicamentos personales; también joyas y cosméticos que se desprendan."},{"pregunta":"¿Cómo se diseña un vestier?","respuesta":"Por etapas, de lo sucio a lo limpio, con separación clara y la secuencia de vestido publicada."}],"resumen":["La persona es una **fuente de contaminación**: se controla con salud, higiene y vestimenta.","La vestimenta depende del **grado del área y del riesgo** del producto.","El reporte de salud funciona solo si **no se castiga**."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"Comisión Europea. EU GMP Annex 1: Manufacture of Sterile Medicinal Products (2022).","url":"https://health.ec.europa.eu/system/files/2022-08/20220825_gmp-an1_en_0.pdf"}],"imagenes":[{"ubicacion":"En la sección de vestimenta","descripcion":"Secuencia ilustrada de vestido en cinco pasos (cofia, cubrebarba, uniforme, calzado, guantes) con figuras planas en azul y turquesa.","alt":"Secuencia de vestido para ingresar a un área de producción farmacéutica"}],"keywords":["higiene del personal bpm","vestimenta en áreas de producción farmacéutica","uniforme bpm industria farmacéutica","salud del personal bpm","vestier farmacéutico","requisitos de higiene en bpm","cómo vestirse para área limpia"],"mapa":{"centro":"La persona como fuente de contaminación","ramas":[{"titulo":"Salud","icono":"UserCheck","nodos":["Exámenes al ingreso y periódicos","Reporte de enfermedad o heridas","Exclusión temporal si hay riesgo"]},{"titulo":"Higiene","icono":"Hand","nodos":["Lavado y desinfección de manos","Sin joyas ni maquillaje","Sin comida ni bebida en áreas"]},{"titulo":"Vestimenta","icono":"Shirt","nodos":["Según grado del área","Cabello y barba cubiertos","Calzado exclusivo"]},{"titulo":"Comportamiento","icono":"Users","nodos":["Movimientos lentos en áreas limpias","No tocar el producto expuesto","Mínimo personal necesario"]}]},"proceso":{"titulo":"Ingreso a un área de producción de no estériles","intro":"","pasos":[{"titulo":"Verificar condición de salud","detalle":"Antes de ingresar, la persona confirma que no tiene síntomas ni heridas expuestas; si las tiene, reporta al supervisor.","icono":"UserCheck","evidencia":"Reporte de salud cuando aplique."},{"titulo":"Retirar objetos personales","detalle":"Deja joyas, reloj, celular, maquillaje y alimentos fuera del área.","icono":"Lock","evidencia":"Casillero asignado."},{"titulo":"Lavar y desinfectar las manos","detalle":"Sigue la técnica publicada de lavado y desinfección.","icono":"Hand","evidencia":"Instructivo visible en el vestier."},{"titulo":"Vestirse en orden","detalle":"Cofia, cubrebarba si aplica, uniforme, calzado exclusivo; tapabocas y guantes según la operación.","icono":"Shirt","evidencia":"Secuencia ilustrada de vestido."},{"titulo":"Pasar por la esclusa","detalle":"Cruza la esclusa respetando que no se abran las dos puertas a la vez.","icono":"DoorOpen","evidencia":"Enclavamiento o señalización de puertas."},{"titulo":"Trabajar con disciplina","detalle":"Sin tocar el producto expuesto, con movimientos controlados y cambiando guantes cuando se contaminen.","icono":"ShieldCheck","evidencia":"Observación del supervisor."}]},"caso":{"titulo":"Una herida en la mano","contexto":"Una operaria de la sala de mezclado se cortó un dedo en su casa. Dice que con el guante no pasa nada y que si reporta pierde el bono del mes.","pregunta":"¿Qué debe hacer el supervisor?","opciones":[{"texto":"Dejarla trabajar con doble guante.","correcta":false,"retro":"Un guante puede romperse; una herida abierta en contacto con el producto es un riesgo que las BPM piden evitar."},{"texto":"Reasignarla temporalmente a una tarea sin contacto con el producto, registrar el caso y revisar que la política de incentivos no castigue el reporte de salud.","correcta":true,"retro":"Protege el producto y corrige la causa de fondo: un sistema que desincentiva reportar es una falla de BPM."},{"texto":"Enviarla a casa sin registrar nada.","correcta":false,"retro":"Sin registro no hay trazabilidad, y el problema del incentivo sigue sin corregirse."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Higiene personal, salud y vestimenta por áreas$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Higiene personal, salud y vestimenta por áreas$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 11. Diseño de instalaciones: flujos, esclusas y acabados sanitarios
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un plano que se puede leer como un proceso","texto":"En una buena planta farmacéutica, el plano cuenta una historia: las materias primas entran por un lado, pasan por cuarentena, pesaje y producción, y el producto terminado sale por otro sin cruzarse con lo que llega. Las personas siguen su propio recorrido. En una mala planta, todo se cruza en un mismo pasillo. El diseño de las instalaciones es la primera barrera contra las mezclas y la contaminación."},"objetivos":["Aplicar los principios de flujo de personas y materiales en un plano.","Explicar la función de las esclusas y de las cascadas de presión.","Identificar los acabados sanitarios que exigen las áreas de producción."],"conceptos":[{"icono":"Route","termino":"Flujo lógico","definicion":"Ordenar las áreas según la secuencia de operaciones para que materiales y personas avancen sin regresar ni cruzarse innecesariamente."},{"icono":"DoorOpen","termino":"Esclusa","definicion":"Recinto con dos puertas que no se abren a la vez, entre áreas de distinta clasificación, para el paso de personas o materiales."},{"icono":"Layers","termino":"Acabados sanitarios","definicion":"Superficies lisas, sin grietas, impermeables y fáciles de limpiar, con uniones redondeadas entre pared y piso cuando aplica."},{"icono":"Building2","termino":"Áreas separadas","definicion":"Zonas definidas para recepción, cuarentena, muestreo, pesaje, producción, empaque, rechazos y producto terminado."}],"secciones":[{"titulo":"Flujos y zonas","parrafos":["Las BPM piden que las instalaciones se ubiquen, diseñen, construyan y mantengan para minimizar el riesgo de errores y permitir una limpieza y un mantenimiento eficaces. En la práctica, el diseño parte del **flujo de materiales**: recepción, cuarentena, muestreo, almacenamiento de aprobados, pesaje, producción, empaque, cuarentena de producto terminado y despacho. Cada etapa tiene su espacio y la secuencia evita que lo que entra se cruce con lo que sale.","El **flujo de personas** se diseña aparte: vestieres, esclusas y pasillos que permitan llegar a cada sala sin atravesar otras. El pesaje de activos se hace en un área o cabina con extracción localizada, y el muestreo de materias primas en un lugar que no contamine el material ni el ambiente. Los baños y comedores se ubican fuera de las áreas productivas y sin comunicación directa con ellas."]},{"titulo":"Barreras y acabados","parrafos":["Las **esclusas** separan áreas con distinta exigencia de limpieza. Sus puertas no deben abrirse al mismo tiempo, lo que se logra con enclavamientos o señales. Junto con el sistema de aire, que mantiene presiones diferenciales entre las áreas (la cascada de presión que verás en la clase de HVAC), impiden que el aire contaminado pase a donde está el producto expuesto, o que el polvo de un activo potente salga de su sala.","Los **acabados** deben permitir limpiar de verdad: paredes, pisos y techos lisos, sin grietas ni juntas abiertas, resistentes a los agentes de limpieza; uniones pared–piso redondeadas en las áreas de producción; ventanas selladas; luminarias empotradas; y tuberías y ductos instalados de modo que no creen recovecos difíciles de limpiar, idealmente con acceso para mantenimiento desde fuera del área. Los desagües, si existen, tienen sifón y se evitan en las áreas más críticas."]}],"errores":[{"error":"Diseñar las áreas según el espacio disponible y no según el proceso.","correccion":"Parte del flujo de materiales y personas y ajusta el espacio a esa secuencia."},{"error":"Esclusas con las dos puertas abiertas.","correccion":"Usa enclavamientos o señales y entrena al personal."},{"error":"Repisas, canaletas expuestas y luminarias colgantes en áreas de producción.","correccion":"Empotra, sella y elimina superficies que acumulen polvo."}],"comprueba":[{"pregunta":"¿Para qué sirve una esclusa?","respuesta":"Para separar áreas de distinta clasificación y permitir el paso de personas o materiales sin que se mezcle el aire de ambas."},{"pregunta":"Menciona tres acabados sanitarios.","respuesta":"Superficies lisas e impermeables, uniones pared–piso redondeadas y luminarias empotradas."},{"pregunta":"¿Por qué el pesaje necesita un área especial?","respuesta":"Porque genera polvo de activos; requiere extracción localizada para proteger el producto, el ambiente y al operario."}],"resumen":["El plano debe **leerse como el proceso**: flujos sin cruces.","Esclusas y presiones son **barreras** físicas contra la contaminación.","Los acabados deben permitir **limpiar de verdad**."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"OMS. TRS 1010, Anexo 8: Guidelines on heating, ventilation and air-conditioning systems for non-sterile pharmaceutical products (2018).","url":"https://gmp-compliance.org/files/guidemgr/TRS1010annex8.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa de proceso","descripcion":"Plano de planta con dos flujos superpuestos: materiales en turquesa y personal en lavanda, y esclusas resaltadas en azul.","alt":"Plano de planta farmacéutica con flujos de materiales y de personal"}],"keywords":["diseño de instalaciones farmacéuticas","flujo de materiales y personal bpm","esclusas en áreas de producción","acabados sanitarios farmacéuticos","diseño de plantas farmacéuticas gmp","layout planta farmacéutica","curva sanitaria pared piso"],"mapa":{"centro":"Instalaciones que previenen errores","ramas":[{"titulo":"Flujos","icono":"Route","nodos":["Materiales en una dirección","Personal por su propio recorrido","Sin cruces limpio–sucio"]},{"titulo":"Barreras","icono":"DoorOpen","nodos":["Esclusas de personal y materiales","Cascadas de presión","Puertas enclavadas"]},{"titulo":"Superficies","icono":"Layers","nodos":["Lisas e impermeables","Uniones redondeadas","Sin repisas ni recovecos"]},{"titulo":"Zonas","icono":"Building2","nodos":["Pesaje con extracción","Muestreo controlado","Rechazos con acceso restringido"]}]},"proceso":{"titulo":"Revisión de un plano de planta con criterio BPM","intro":"","pasos":[{"titulo":"Trazar el flujo de materiales","detalle":"Dibuja con un color el recorrido de las materias primas hasta el producto terminado.","icono":"Route","evidencia":"Plano con flujo de materiales."},{"titulo":"Trazar el flujo de personas","detalle":"Con otro color, el recorrido del personal desde el ingreso hasta cada sala.","icono":"Users","evidencia":"Plano con flujo de personal."},{"titulo":"Marcar los cruces","detalle":"Señala dónde se cruzan limpio y sucio, o materiales de distintos lotes.","icono":"Crosshair","evidencia":"Lista de cruces detectados."},{"titulo":"Ubicar barreras","detalle":"Verifica esclusas, presiones y separaciones entre áreas de distinta clasificación.","icono":"DoorOpen","evidencia":"Plano de presiones y clasificación."},{"titulo":"Revisar acabados","detalle":"Recorre el área con una lista de verificación de superficies, uniones, luminarias y tuberías.","icono":"ClipboardCheck","evidencia":"Lista de verificación diligenciada."},{"titulo":"Priorizar correcciones","detalle":"Clasifica las brechas por riesgo y define el plan de obra o de control.","icono":"AlertTriangle","evidencia":"Plan de mejoras aprobado."}]},"caso":{"titulo":"El pasillo único","contexto":"En una planta antigua, el producto terminado sale por el mismo pasillo por donde entran las materias primas desde cuarentena. Rediseñar cuesta mucho y tardaría un año.","pregunta":"¿Qué solución es defendible mientras tanto?","opciones":[{"texto":"No hacer nada hasta tener presupuesto para la obra.","correcta":false,"retro":"El riesgo de mezcla existe hoy; hay que controlarlo mientras se corrige el diseño."},{"texto":"Separar en el tiempo los movimientos con horarios definidos, señalizar, usar carros e identificación inequívoca, documentar el control temporal y planear la obra con fecha.","correcta":true,"retro":"Es un control provisional razonable, basado en riesgo y documentado, mientras se corrige la causa de diseño."},{"texto":"Pintar una línea en el piso para dividir el pasillo.","correcta":false,"retro":"Una línea sola no evita el cruce ni la confusión de materiales."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Diseño de instalaciones: flujos, esclusas y acabados sanitarios$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Diseño de instalaciones: flujos, esclusas y acabados sanitarios$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 12. Equipos: calificación (DQ/IQ/OQ/PQ), limpieza, mantenimiento y calibración
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La balanza que nadie verificó","texto":"Durante tres meses, una balanza de pesaje de activos marcó 2 % menos de lo real. Nadie lo notó porque su calibración anual estaba vigente y no se hacía verificación diaria. Resultado: decenas de lotes con más activo del declarado y una investigación enorme. Los equipos se califican, se calibran, se verifican, se limpian y se mantienen porque cada dato y cada lote dependen de ellos."},"objetivos":["Relacionar la calificación, la calibración y el mantenimiento en el ciclo de vida de un equipo.","Diseñar un control de estado (rótulos, bitácoras) para los equipos de producción.","Distinguir calibración de verificación intermedia."],"conceptos":[{"icono":"ClipboardCheck","termino":"Calificación","definicion":"DQ, IQ, OQ y PQ demuestran que el equipo está bien diseñado, instalado, opera y rinde como se espera. Se profundiza en el curso de Validaciones."},{"icono":"Ruler","termino":"Calibración","definicion":"Comparación del instrumento con un patrón trazable para conocer su error y ajustarlo si se sale de la tolerancia, a intervalos definidos."},{"icono":"Gauge","termino":"Verificación intermedia","definicion":"Comprobación frecuente (por ejemplo, diaria) con pesas o patrones para detectar desviaciones entre calibraciones."},{"icono":"Tag","termino":"Rótulo de estado","definicion":"Identificación visible de si el equipo está limpio, sucio, en mantenimiento, fuera de servicio o con calibración vigente."},{"icono":"FileText","termino":"Bitácora de uso","definicion":"Registro cronológico de uso, limpieza, mantenimiento y fallas de cada equipo crítico."}],"secciones":[{"titulo":"Diseño, limpieza y estado","parrafos":["Las BPM piden que los equipos se diseñen para su propósito y para limpiarse con facilidad. Las superficies en contacto con el producto no deben ser reactivas, aditivas ni absorbentes, y los lubricantes o refrigerantes no deben entrar en contacto con él. Cada equipo tiene un procedimiento de uso y otro de limpieza, y su estado se identifica con un **rótulo visible**: limpio, sucio, en mantenimiento o fuera de servicio, con fecha y responsable.","Los equipos críticos llevan una **bitácora** donde se registran el uso (producto y lote), las limpiezas, los mantenimientos, las calibraciones y las fallas. La bitácora permite reconstruir qué lotes pasaron por un equipo cuando se descubre un problema, y es uno de los primeros documentos que revisa un inspector."]},{"titulo":"Calibrar, verificar y mantener","parrafos":["La **calibración** compara un instrumento con un patrón de referencia trazable a patrones nacionales o internacionales, a intervalos definidos, y documenta el error encontrado. La **verificación intermedia** es una comprobación más frecuente y sencilla: por ejemplo, pesar diariamente pesas patrón en la balanza antes de usarla. Si la verificación falla, la balanza se retira de uso y se evalúa el impacto sobre todo lo pesado desde la última verificación conforme.","El **mantenimiento preventivo** se programa según el uso y las recomendaciones del fabricante, y cualquier reparación o cambio de componentes se evalúa por **control de cambios** para decidir si afecta la calificación. Recuerda la regla del curso de Validaciones: el equipo calificado conserva su estado mientras se mantenga bajo calibración, mantenimiento y control de cambios."]}],"errores":[{"error":"Equipos sin rótulo de estado.","correccion":"Cada equipo muestra si está limpio, sucio, en mantenimiento o fuera de servicio."},{"error":"Confiar solo en la calibración anual.","correccion":"Implementa verificaciones intermedias en los instrumentos críticos."},{"error":"Reparaciones sin control de cambios.","correccion":"Evalúa cada reparación para decidir si afecta la calificación."}],"comprueba":[{"pregunta":"¿Qué diferencia hay entre calibración y verificación intermedia?","respuesta":"La calibración compara con un patrón trazable a intervalos definidos; la verificación es una comprobación frecuente para detectar desviaciones entre calibraciones."},{"pregunta":"¿Para qué sirve la bitácora de un equipo?","respuesta":"Para registrar uso, limpieza, mantenimiento, calibraciones y fallas, y reconstruir qué lotes se afectaron."}],"resumen":["Los equipos se **califican, calibran, verifican, limpian y mantienen**.","El **rótulo de estado** y la **bitácora** hacen visible su condición.","Una verificación fallida obliga a **evaluar el impacto** sobre los lotes."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"PIC/S. Guide to GMP, Annex 15: Qualification and Validation.","url":"https://picscheme.org/docview/3443"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"OMS. TRS 1019, Anexo 3: Good manufacturing practices: guidelines on validation (2019).","url":"https://cdn.who.int/media/docs/default-source/medicines/norms-and-standards/guidelines/production/trs1019-annex3-gmp-validation.pdf?sfvrsn=9440a5c_0&download=true"}],"imagenes":[{"ubicacion":"En la sección de estado","descripcion":"Cuatro rótulos de estado ilustrados (limpio, sucio, en mantenimiento, fuera de servicio) con colores e iconos distintos, sobre fondo blanco.","alt":"Rótulos de estado de equipos farmacéuticos"}],"keywords":["calibración de equipos farmacéuticos","mantenimiento preventivo bpm","verificación diaria de balanzas","rótulos de estado de equipos","bitácora de equipos bpm","calificación de equipos bpm","equipos de producción farmacéutica requisitos"],"mapa":{"centro":"Ciclo de vida de un equipo","ramas":[{"titulo":"Antes de usar","icono":"ClipboardCheck","nodos":["URS y DQ","IQ, OQ y PQ","Procedimientos de uso y limpieza"]},{"titulo":"En uso","icono":"Factory","nodos":["Rótulo de estado","Bitácora","Verificación diaria"]},{"titulo":"Mantener","icono":"Wrench","nodos":["Mantenimiento preventivo","Calibración trazable","Control de cambios"]},{"titulo":"Cuando falla","icono":"AlertTriangle","nodos":["Fuera de servicio","Evaluación de impacto en lotes","Investigación"]}]},"proceso":{"titulo":"Qué hacer cuando la verificación diaria de una balanza falla","intro":"","pasos":[{"titulo":"Retirar de uso","detalle":"Rotula la balanza como fuera de servicio de inmediato.","icono":"Lock","evidencia":"Rótulo y registro en bitácora."},{"titulo":"Confirmar la falla","detalle":"Repite la verificación con las pesas patrón según el procedimiento, sin ajustar el equipo.","icono":"Search","evidencia":"Registro de la verificación repetida."},{"titulo":"Identificar lo afectado","detalle":"Con la bitácora, lista los lotes y pesajes desde la última verificación conforme.","icono":"FileSearch","evidencia":"Lista de lotes potencialmente afectados."},{"titulo":"Evaluar el impacto","detalle":"Calcula si el error pudo llevar los pesajes fuera de tolerancia y qué atributos afecta.","icono":"Calculator","evidencia":"Evaluación de impacto."},{"titulo":"Decidir sobre los lotes","detalle":"Aseguramiento de calidad decide retener, analizar adicionalmente o rechazar.","icono":"Gavel","evidencia":"Decisión documentada."},{"titulo":"Reparar, calibrar y cerrar","detalle":"Repara, calibra, verifica y libera el equipo; cierra la investigación con acciones preventivas.","icono":"CheckCircle2","evidencia":"Certificado de calibración y cierre de desviación."}]},"caso":{"titulo":"Calibración vigente, verificación fallida","contexto":"La balanza del pesaje de activos tiene calibración anual vigente. Hoy, la verificación diaria con una pesa de 1 kg da 980 g. El supervisor dice que «si la calibración está vigente, la balanza está bien».","pregunta":"¿Qué prevalece?","opciones":[{"texto":"La calibración vigente: se sigue usando hasta la próxima calibración.","correcta":false,"retro":"La calibración describe el estado en una fecha; la verificación de hoy muestra que el equipo cambió."},{"texto":"La verificación: se retira de uso y se evalúa el impacto sobre los pesajes desde la última verificación conforme.","correcta":true,"retro":"La verificación intermedia existe precisamente para detectar desviaciones entre calibraciones."},{"texto":"Ajustar la balanza para que marque 1 kg y continuar.","correcta":false,"retro":"Ajustar sin investigar oculta el problema y deja sin evaluar los lotes afectados."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Equipos: calificación (DQ/IQ/OQ/PQ), limpieza, mantenimiento y calibración$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Equipos: calificación (DQ/IQ/OQ/PQ), limpieza, mantenimiento y calibración$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
