    v_n := v_n + 1;
  END IF;

  -- 13. Sistemas de agua para uso farmacéutico
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un ramal olvidado","texto":"Durante una ampliación, se dejó un ramal de agua purificada hacia una sala que nunca se terminó. Ese tramo quedó sin recirculación. Meses después, los recuentos microbianos del anillo empezaron a subir sin causa aparente. La biopelícula había crecido en el ramal muerto y contaminaba el resto del sistema. El agua farmacéutica se comporta como un sistema vivo: se diseña y se cuida como tal."},"objetivos":["Diferenciar los tipos de agua para uso farmacéutico y sus usos.","Describir las partes de un sistema de agua y sus riesgos.","Explicar el monitoreo de rutina con límites de alerta y acción."],"conceptos":[{"icono":"Droplets","termino":"Agua potable","definicion":"Agua de alimentación del sistema y para limpiezas iniciales. Debe cumplir la norma de agua para consumo humano."},{"icono":"Filter","termino":"Agua purificada","definicion":"Agua para la fabricación de productos no estériles y el enjuague final de equipos de esos productos. Se controla en conductividad, carbono orgánico total y microbiología."},{"icono":"Syringe","termino":"Agua para inyectables","definicion":"Agua para productos parenterales y enjuagues finales de equipos y envases de estériles. Exige además control estricto de endotoxinas."},{"icono":"Bug","termino":"Biopelícula","definicion":"Comunidad de microorganismos adherida a las superficies internas. Crece en zonas estancadas y libera bacterias y endotoxinas al agua."},{"icono":"Thermometer","termino":"Sanitización","definicion":"Tratamiento periódico con calor, ozono o químicos para controlar la carga microbiana del sistema."}],"secciones":[{"titulo":"Tipos de agua y para qué se usan","parrafos":["La calidad del agua depende de su uso. El **agua potable** alimenta el sistema y sirve para limpiezas iniciales. El **agua purificada** se usa como componente de productos no estériles y en los enjuagues finales de los equipos que los fabrican. El **agua para inyectables** se usa en productos parenterales y en los enjuagues finales de equipos y envases de productos estériles. Las especificaciones de cada una están en la farmacopea.","La guía de la OMS sobre agua para uso farmacéutico (TRS 1033, Anexo 3) describe cómo diseñar, calificar, operar y monitorear estos sistemas, y acepta que el agua para inyectables se produzca por destilación o por otros métodos de purificación equivalentes, siempre que el sistema esté validado y controlado."]},{"titulo":"Diseño y control microbiológico","parrafos":["El riesgo principal de un sistema de agua es **microbiológico**. Por eso el diseño busca evitar el estancamiento: un **anillo** de distribución con recirculación continua y velocidad suficiente, tuberías de material sanitario con soldaduras de calidad, pendientes que permitan el drenaje completo, válvulas de diseño sanitario y la menor longitud posible de ramales sin flujo. El tanque de almacenamiento tiene venteo con filtro hidrofóbico y, según el diseño, se mantiene en caliente o se sanitiza periódicamente.","El monitoreo de rutina mide la calidad química (conductividad y carbono orgánico total, a menudo en línea) y la microbiológica en los puntos de uso, con **límites de alerta y de acción**. Superar un límite de alerta es una señal para investigar; superar el de acción exige investigar, evaluar el impacto sobre el producto y corregir. El análisis de **tendencias** es tan importante como cada resultado aislado: un aumento lento puede anunciar una biopelícula antes de que haya un resultado fuera de límite. La calificación por fases se trató en el curso de Validaciones y Calificaciones."]}],"errores":[{"error":"Ramales sin recirculación o con zonas muertas.","correccion":"Diseña anillos con recirculación continua y elimina los ramales sin uso."},{"error":"Mirar solo si cada resultado cumple.","correccion":"Analiza tendencias: un aumento sostenido anticipa problemas."},{"error":"Usar agua potable en enjuagues finales.","correccion":"Usa la misma calidad de agua que exige el producto."}],"comprueba":[{"pregunta":"¿Para qué se usa el agua para inyectables?","respuesta":"En productos parenterales y en los enjuagues finales de equipos y envases de productos estériles."},{"pregunta":"¿Qué es una biopelícula y dónde crece?","respuesta":"Una comunidad microbiana adherida a las superficies; crece donde el agua se estanca, como en ramales sin recirculación."},{"pregunta":"¿Qué diferencia hay entre límite de alerta y de acción?","respuesta":"El de alerta es una señal temprana para investigar; el de acción exige investigación, evaluación de impacto y corrección."}],"resumen":["Agua potable, purificada y para inyectables: **cada una para su uso**.","El riesgo principal es **microbiológico**: se evita el estancamiento.","Se monitorea con **límites de alerta y acción** y análisis de tendencias."],"referencias":[{"cita":"OMS. TRS 1033, Anexo 3: Good manufacturing practices: water for pharmaceutical use (2021).","url":"https://www.who.int/publications/m/item/annex-3-trs-1033"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"En la sección de diseño","descripcion":"Comparación ilustrada: a la izquierda un anillo con recirculación y flechas de flujo; a la derecha un ramal muerto con una biopelícula marcada en rojo.","alt":"Anillo de recirculación frente a un ramal muerto con biopelícula"}],"keywords":["sistemas de agua farmacéutica","agua purificada farmacéutica","agua para inyectables","tipos de agua en la industria farmacéutica","biopelícula en sistemas de agua","monitoreo de agua purificada","límites de alerta y acción agua","trs 1033 agua para uso farmacéutico"],"mapa":{"centro":"Sistema de agua farmacéutica","ramas":[{"titulo":"Generar","icono":"Filter","nodos":["Pretratamiento","Ósmosis inversa y electrodesionización","Destilación u otro método validado"]},{"titulo":"Almacenar","icono":"Database","nodos":["Tanque con venteo filtrado","Temperatura controlada","Capacidad adecuada"]},{"titulo":"Distribuir","icono":"RefreshCw","nodos":["Anillo con recirculación","Sin zonas muertas","Pendientes de drenaje"]},{"titulo":"Controlar","icono":"LineChart","nodos":["Conductividad y carbono orgánico total","Recuento microbiano","Endotoxinas en agua para inyectables"]}]},"proceso":{"titulo":"Respuesta a un resultado microbiológico sobre el límite de acción","intro":"","pasos":[{"titulo":"Registrar y notificar","detalle":"Registra el resultado, el punto y la fecha, y notifica a aseguramiento de calidad.","icono":"AlertTriangle","evidencia":"Registro de excursión."},{"titulo":"Verificar el muestreo y el análisis","detalle":"Revisa la técnica de muestreo, la manipulación y el ensayo para descartar un error de laboratorio.","icono":"Search","evidencia":"Revisión documentada."},{"titulo":"Investigar el sistema","detalle":"Revisa recirculación, temperatura, sanitizaciones, mantenimientos, ramales y tendencias recientes.","icono":"Droplets","evidencia":"Informe de investigación."},{"titulo":"Evaluar el impacto","detalle":"Identifica los lotes fabricados con agua de ese punto y evalúa el riesgo para cada uno.","icono":"FileSearch","evidencia":"Evaluación de impacto en lotes."},{"titulo":"Corregir","detalle":"Sanitiza, corrige la causa (por ejemplo, un ramal muerto) y aumenta temporalmente el muestreo.","icono":"Wrench","evidencia":"Acciones correctivas ejecutadas."},{"titulo":"Confirmar el control","detalle":"Demuestra con resultados posteriores que el sistema volvió a estar bajo control.","icono":"LineChart","evidencia":"Resultados de seguimiento y cierre."}]},"caso":{"titulo":"El agua del enjuague final","contexto":"Producción propone usar agua potable para el enjuague final de un tanque de fabricación de jarabe, porque «después se enjuaga con el propio producto».","pregunta":"¿Qué respondes?","opciones":[{"texto":"Aceptar, porque el agua potable es apta para consumo humano.","correcta":false,"retro":"El agua potable no tiene la calidad química ni microbiológica requerida para el contacto final con un producto farmacéutico."},{"texto":"El enjuague final de equipos de productos no estériles debe hacerse con agua de calidad igual a la del agua usada en el producto, es decir, agua purificada.","correcta":true,"retro":"El enjuague final deja la última película de agua en contacto con el producto: debe tener la calidad del agua del producto."},{"texto":"Aceptar si después se seca bien el tanque.","correcta":false,"retro":"Secar no elimina residuos químicos ni garantiza la calidad microbiológica."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Sistemas de agua para uso farmacéutico$t$ AND deleted_at IS NULL
