    v_n := v_n + 1;
  END IF;

  -- 14. Sistemas HVAC: presiones diferenciales, filtración y renovaciones de aire
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El aire viaja hacia donde hay menos presión","texto":"En una sala de pesaje de un antihipertensivo potente, el manómetro diferencial marcaba cero porque una compuerta se había cerrado durante un mantenimiento. Nadie revisó el registro esa semana. El polvo del activo salió al pasillo y llegó a la sala de empaque de otro producto. El sistema HVAC es una barrera invisible: cuando falla, la contaminación viaja con el aire."},"objetivos":["Explicar cómo las presiones diferenciales evitan la contaminación cruzada.","Describir las etapas de filtración y la función de los filtros HEPA.","Relacionar las renovaciones de aire con la limpieza del área y su recuperación."],"conceptos":[{"icono":"Wind","termino":"Cascada de presión","definicion":"Diferencias de presión entre áreas contiguas para que el aire fluya de la más limpia a la menos limpia, o hacia dentro de un área que contiene un producto potente."},{"icono":"Filter","termino":"Filtración por etapas","definicion":"Prefiltros, filtros intermedios y filtros finales de alta eficiencia (HEPA) en las áreas que lo requieren."},{"icono":"RefreshCw","termino":"Renovaciones de aire","definicion":"Número de veces por hora que el aire del recinto se reemplaza. Influye en la dilución de partículas y en el tiempo de recuperación."},{"icono":"Thermometer","termino":"Temperatura y humedad","definicion":"Se controlan para proteger el producto (por ejemplo, materiales higroscópicos) y para el confort del personal."},{"icono":"Gauge","termino":"Monitoreo","definicion":"Lectura y registro de presiones diferenciales, temperatura y humedad, con alarmas y gestión de excursiones."}],"secciones":[{"titulo":"Presiones: hacia dónde va el aire","parrafos":["El aire se mueve de las zonas de mayor presión a las de menor. Con esa física simple, el sistema HVAC (calefacción, ventilación y aire acondicionado) crea **cascadas de presión**. En una planta de productos no estériles, el objetivo suele ser doble: proteger el producto del ambiente exterior y evitar que el polvo de una sala pase a otra. Una sala que procesa un activo potente puede diseñarse con presión negativa respecto al pasillo, o con una esclusa que funcione como sumidero o como burbuja, para contener el polvo.","Para productos estériles, el Anexo 1 orienta una diferencia de presión del orden de 10 a 15 pascales entre áreas de grado distinto. Para no estériles, la guía de la OMS sobre HVAC (TRS 1010, Anexo 8) explica cómo elegir el concepto de contención según el producto. En todos los casos, las presiones se **monitorean**, se registran y tienen alarmas: una cascada que nadie mira no protege a nadie."]},{"titulo":"Filtración, caudal y condiciones","parrafos":["El aire pasa por **etapas de filtración**: prefiltros que retienen partículas gruesas, filtros intermedios y, en las áreas que lo requieren, filtros finales de alta eficiencia (HEPA) instalados en el punto de suministro. Los filtros HEPA se someten a pruebas de integridad después de su instalación y con la frecuencia definida, porque una fuga en el marco anula su eficiencia.","El **caudal** y las **renovaciones de aire** diluyen y arrastran las partículas generadas en el área. Su número se define en el diseño según la carga de partículas, la clasificación requerida y el tiempo de recuperación: el tiempo que tarda el área en volver a su condición después de una contaminación. La temperatura y la humedad se controlan según las necesidades del producto, por ejemplo cuando se manejan materiales higroscópicos. Si el sistema recircula aire, el diseño debe demostrar que no devuelve contaminación cruzada al área, lo que puede exigir filtración adicional o aire de un solo paso."]}],"errores":[{"error":"Registrar presiones sin revisar ni reaccionar.","correccion":"Define rangos, alarmas y la acción obligatoria ante cada excursión."},{"error":"Cambiar filtros sin probar su integridad.","correccion":"Prueba la integridad de los HEPA después de instalarlos."},{"error":"Recircular aire de áreas con productos potentes sin evaluar el riesgo.","correccion":"Evalúa la contaminación cruzada y usa filtración adecuada o aire de un solo paso."}],"comprueba":[{"pregunta":"¿Hacia dónde fluye el aire en una cascada de presión?","respuesta":"De la zona de mayor presión a la de menor presión."},{"pregunta":"¿Qué diferencia de presión orienta el Anexo 1 entre grados de áreas estériles?","respuesta":"Del orden de 10 a 15 pascales."},{"pregunta":"¿Qué es el tiempo de recuperación?","respuesta":"El tiempo que tarda un área en volver a su condición de limpieza después de una contaminación."}],"resumen":["El HVAC crea **cascadas de presión** que dirigen el aire.","La filtración termina en **HEPA** con integridad probada.","Presiones, temperatura y humedad se **monitorean y se gestionan** sus excursiones."],"referencias":[{"cita":"OMS. TRS 1010, Anexo 8: Guidelines on heating, ventilation and air-conditioning systems for non-sterile pharmaceutical products (2018).","url":"https://gmp-compliance.org/files/guidemgr/TRS1010annex8.pdf"},{"cita":"Comisión Europea. EU GMP Annex 1: Manufacture of Sterile Medicinal Products (2022).","url":"https://health.ec.europa.eu/system/files/2022-08/20220825_gmp-an1_en_0.pdf"},{"cita":"OMS. TRS 1044, Anexo 2: WHO good manufacturing practices for sterile pharmaceutical products (2022).","url":"https://www.who.int/publications/m/item/trs1044-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"En la sección de presiones","descripcion":"Corte transversal de tres salas con valores de presión (+15, +5, 0 Pa) y flechas de aire que van de la sala más limpia al pasillo.","alt":"Cascada de presiones diferenciales entre salas farmacéuticas"}],"keywords":["sistemas hvac farmacéuticos","presiones diferenciales bpm","cascada de presión salas limpias","filtros hepa farmacéutica","renovaciones de aire salas limpias","tiempo de recuperación área limpia","hvac industria farmacéutica","trs 1010 anexo 8 hvac"],"mapa":{"centro":"El aire como barrera","ramas":[{"titulo":"Presiones","icono":"Wind","nodos":["Cascada entre áreas","Del más limpio al menos limpio","Contención para potentes"]},{"titulo":"Filtración","icono":"Filter","nodos":["Prefiltros e intermedios","HEPA terminales","Pruebas de integridad"]},{"titulo":"Caudal","icono":"RefreshCw","nodos":["Renovaciones de aire","Dilución de partículas","Tiempo de recuperación"]},{"titulo":"Condiciones","icono":"Thermometer","nodos":["Temperatura","Humedad relativa","Alarmas y registros"]}]},"proceso":{"titulo":"Gestión de una excursión de presión diferencial","intro":"","pasos":[{"titulo":"Detectar","detalle":"La alarma o la lectura de rutina muestra una presión fuera del rango establecido.","icono":"Gauge","evidencia":"Registro de la lectura y la hora."},{"titulo":"Contener","detalle":"Detén las operaciones con producto expuesto en las áreas afectadas.","icono":"Hand","evidencia":"Registro de parada."},{"titulo":"Identificar la causa","detalle":"Revisa puertas, compuertas, ventiladores, filtros colmatados y mantenimientos recientes.","icono":"Search","evidencia":"Hallazgos de la revisión técnica."},{"titulo":"Restablecer","detalle":"Corrige la causa y confirma que las presiones vuelven a su rango de forma estable.","icono":"Wrench","evidencia":"Lecturas posteriores conformes."},{"titulo":"Evaluar el impacto","detalle":"Determina el tiempo de la excursión, qué se procesaba y si hubo riesgo de contaminación cruzada.","icono":"FileSearch","evidencia":"Evaluación de impacto."},{"titulo":"Cerrar la desviación","detalle":"Documenta la decisión sobre los lotes y las acciones preventivas.","icono":"CheckCircle2","evidencia":"Desviación cerrada."}]},"caso":{"titulo":"Tres días fuera de rango","contexto":"En una autoinspección se encuentra que la presión entre la sala de fabricación de un jarabe y el pasillo estuvo fuera de rango tres días seguidos, registrada pero sin investigación.","pregunta":"¿Cómo lo manejas?","opciones":[{"texto":"Anotarlo como hallazgo menor porque el dato sí se registró.","correcta":false,"retro":"Registrar sin reaccionar no es un control. Tres días sin investigar sugieren una falla del sistema de monitoreo."},{"texto":"Clasificarlo como hallazgo mayor, abrir una investigación retrospectiva sobre los lotes de esos días y corregir el procedimiento para que toda excursión dispare una acción.","correcta":true,"retro":"El riesgo de contaminación cruzada fue real y el sistema no reaccionó. La corrección debe atacar ambas cosas."},{"texto":"Recalibrar el manómetro y olvidar el asunto.","correcta":false,"retro":"Puede que el manómetro esté bien; sin investigar no sabes qué pasó ni qué lotes se afectaron."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Sistemas HVAC: presiones diferenciales, filtración y renovaciones de aire$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Sistemas HVAC: presiones diferenciales, filtración y renovaciones de aire$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 15. Clasificación de áreas limpias: ISO 14644 y grados OMS/GMP
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Grado B en reposo, ¿e ISO 7 en operación?","texto":"Un ingeniero de proyectos dice que la nueva sala «es ISO 7» y el jefe de calidad responde que eso no basta: necesita saber si es grado C en reposo o en operación. Los dos hablan de lo mismo con lenguajes distintos. La clasificación ISO cuenta partículas; los grados de las BPM agregan el estado de ocupación y los límites microbiológicos. Entender cómo encajan es clave para diseñar y calificar áreas limpias."},"objetivos":["Explicar la clasificación por partículas de la ISO 14644-1.","Relacionar los grados A, B, C y D con las clases ISO en reposo y en operación.","Diferenciar la clasificación de un área de su monitoreo de rutina."],"conceptos":[{"icono":"Microscope","termino":"ISO 14644-1","definicion":"Norma que clasifica la limpieza del aire por la concentración de partículas de determinados tamaños. Por ejemplo, ISO 5 admite hasta 3.520 partículas de 0,5 µm por metro cúbico."},{"icono":"Layers","termino":"Grados A, B, C y D","definicion":"Clasificación de las BPM para estériles que combina partículas, estado de ocupación y límites microbiológicos."},{"icono":"Users","termino":"En reposo y en operación","definicion":"En reposo: instalaciones y equipos funcionando, sin personal. En operación: el área trabajando normalmente, con personal."},{"icono":"Search","termino":"Clasificación vs monitoreo","definicion":"La clasificación demuestra que el área alcanza su grado en condiciones definidas; el monitoreo demuestra día a día que se mantiene."}],"secciones":[{"titulo":"ISO 14644-1: el conteo de partículas","parrafos":["La norma ISO 14644-1 clasifica la limpieza del aire de una sala por la concentración máxima de partículas en el aire para ciertos tamaños. Para el tamaño de referencia de 0,5 µm, una sala **ISO 5** admite hasta 3.520 partículas por metro cúbico; una **ISO 7**, hasta 352.000, y una **ISO 8**, hasta 3.520.000. La norma define también cuántos puntos muestrear según el área y cómo evaluar los resultados.","Una clasificación ISO por sí sola describe partículas, no microorganismos, y debe indicar el estado de ocupación en que se midió. Por eso las BPM no se quedan en la clase ISO."]},{"titulo":"Los grados de las BPM para estériles","parrafos":["El Anexo 1 de 2022 y la guía de la OMS para estériles (TRS 1044) definen cuatro grados. El **grado A** es la zona de operaciones de alto riesgo, como el llenado aséptico, y corresponde a ISO 5 tanto en reposo como en operación. El **grado B** es el entorno del grado A en el procesamiento aséptico: ISO 5 en reposo e ISO 7 en operación. El **grado C** corresponde a ISO 7 en reposo e ISO 8 en operación. El **grado D** corresponde a ISO 8 en reposo, y su límite en operación lo define el fabricante según su análisis de riesgo.","Los grados agregan **límites microbiológicos** (que verás en la unidad 4) y exigen que la clasificación se haga en reposo y en operación. Después de clasificar, el área entra a un **programa de monitoreo** de partículas y de microorganismos con límites de alerta y de acción. La clasificación es la foto inicial; el monitoreo es la película. Para áreas de no estériles, muchas plantas definen niveles de limpieza propios, a menudo tomando el grado D o una clase ISO como referencia, según su análisis de riesgo."]}],"errores":[{"error":"Decir «la sala es ISO 7» sin indicar el estado.","correccion":"Especifica siempre si la clase es en reposo o en operación."},{"error":"Confundir clasificación con monitoreo.","correccion":"La clasificación es inicial y periódica; el monitoreo es continuo y con tendencias."},{"error":"Clasificar antes de calificar el HVAC.","correccion":"Primero se demuestra que el sistema de aire funciona; luego se clasifica el área."}],"comprueba":[{"pregunta":"¿Cuántas partículas de 0,5 µm por metro cúbico admite una sala ISO 5?","respuesta":"Hasta 3.520."},{"pregunta":"¿A qué clases ISO corresponde el grado B?","respuesta":"ISO 5 en reposo e ISO 7 en operación."},{"pregunta":"¿Qué diferencia hay entre en reposo y en operación?","respuesta":"En reposo el área funciona sin personal; en operación trabaja normalmente con el personal."}],"resumen":["ISO 14644-1 **cuenta partículas**: ISO 5, 7 y 8 son las clases más usadas.","Los grados **A, B, C y D** suman estado de ocupación y límites microbiológicos.","Se clasifica **en reposo y en operación**; después se monitorea."],"referencias":[{"cita":"Comisión Europea. EU GMP Annex 1: Manufacture of Sterile Medicinal Products (2022).","url":"https://health.ec.europa.eu/system/files/2022-08/20220825_gmp-an1_en_0.pdf"},{"cita":"OMS. TRS 1044, Anexo 2: WHO good manufacturing practices for sterile pharmaceutical products (2022).","url":"https://www.who.int/publications/m/item/trs1044-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Tabla ilustrada de cuatro filas (grados A a D) y dos columnas (en reposo, en operación) con las clases ISO en celdas de colores de marca.","alt":"Equivalencia entre grados A, B, C y D y clases ISO 14644-1"}],"keywords":["clasificación de áreas limpias","iso 14644-1 clases","grados a b c d áreas limpias","iso 5 iso 7 iso 8","áreas limpias farmacéuticas","en reposo y en operación","salas limpias anexo 1","clasificación de cuartos limpios"],"mapa":{"centro":"Cómo se mide lo limpio","ramas":[{"titulo":"ISO 14644-1","icono":"Microscope","nodos":["ISO 5: 3.520 partículas ≥0,5 µm/m³","ISO 7: 352.000","ISO 8: 3.520.000"]},{"titulo":"Grados BPM","icono":"Layers","nodos":["A: ISO 5 en reposo y en operación","B: ISO 5 en reposo, ISO 7 en operación","C: ISO 7 en reposo, ISO 8 en operación","D: ISO 8 en reposo"]},{"titulo":"Estados","icono":"Users","nodos":["En reposo","En operación","Simulación de operación"]},{"titulo":"Después","icono":"LineChart","nodos":["Monitoreo de partículas","Monitoreo microbiológico","Tendencias"]}]},"proceso":{"titulo":"Clasificación de un área limpia nueva","intro":"","pasos":[{"titulo":"Definir el grado requerido","detalle":"Según la operación que se hará en el área y el riesgo del producto.","icono":"Target","evidencia":"Especificación del área en la URS."},{"titulo":"Calificar el HVAC","detalle":"Verifica caudales, presiones, integridad de HEPA y visualización de flujo antes de clasificar.","icono":"Wind","evidencia":"Informes de calificación del HVAC."},{"titulo":"Planear el muestreo","detalle":"Calcula el número de puntos según el área y la norma ISO 14644-1, y su ubicación.","icono":"MapPin","evidencia":"Plan de muestreo."},{"titulo":"Clasificar en reposo","detalle":"Mide partículas con el área instalada, equipos funcionando y sin personal.","icono":"Microscope","evidencia":"Resultados en reposo."},{"titulo":"Clasificar en operación","detalle":"Mide durante una operación normal o simulada, con el personal habitual.","icono":"Users","evidencia":"Resultados en operación."},{"titulo":"Definir el monitoreo","detalle":"Con los resultados, establece puntos, frecuencias y límites de alerta y acción para la rutina.","icono":"LineChart","evidencia":"Programa de monitoreo aprobado."}]},"caso":{"titulo":"La sala que solo se midió vacía","contexto":"Una sala de grado B se clasificó solo en reposo y cumplió ISO 5. El fabricante quiere empezar a producir sin la medición en operación porque «si vacía cumple ISO 5, con gente cumplirá ISO 7».","pregunta":"¿Es aceptable?","opciones":[{"texto":"Sí, porque ISO 7 es menos exigente que ISO 5.","correcta":false,"retro":"La suposición no reemplaza la evidencia: el personal y los procesos pueden generar más partículas de lo esperado."},{"texto":"No: el grado B exige demostrar ISO 5 en reposo e ISO 7 en operación; hay que clasificar en operación con el personal y las actividades reales.","correcta":true,"retro":"Los grados se definen para ambos estados. Solo la medición en operación demuestra que el área se mantiene con gente trabajando."},{"texto":"Sí, si se monitorea después.","correcta":false,"retro":"El monitoreo de rutina no sustituye la clasificación inicial en operación."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Clasificación de áreas limpias: ISO 14644 y grados OMS/GMP$t$ AND deleted_at IS NULL
