  -- 16. Introducción a la unidad: el proceso productivo bajo BPM
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Un lote es una historia que se debe poder contar","texto":"Seis meses después de vendido, un paciente reporta un sabor extraño en un jarabe. Con el número de lote, la empresa debe poder contar toda la historia: qué materias primas se usaron y de qué proveedores, quién pesó, en qué equipos, con qué controles en proceso, qué desviaciones hubo y quién liberó. Si la historia tiene huecos, no hay forma de saber qué pasó. Esta unidad trata de cómo se fabrica para que esa historia exista."},"objetivos":["Describir los documentos maestros y de lote que gobiernan la producción.","Reconocer los controles que previenen la contaminación cruzada y las mezclas.","Ubicar los temas de la unidad dentro del flujo de un lote."],"conceptos":[{"icono":"FileText","termino":"Fórmula maestra","definicion":"El documento aprobado que define composición, instrucciones de fabricación, controles en proceso y rendimientos esperados de un producto."},{"icono":"ClipboardList","termino":"Registro de lote","definicion":"La copia controlada de las instrucciones que se diligencia durante la fabricación de un lote concreto y cuenta su historia completa."},{"icono":"ShieldCheck","termino":"Controles en proceso","definicion":"Mediciones durante la fabricación que permiten ajustar el proceso y asegurar que el producto cumplirá."},{"icono":"Boxes","termino":"Trazabilidad","definicion":"La capacidad de seguir cada material y cada operación hacia atrás y hacia adelante a partir del número de lote."}],"secciones":[{"titulo":"De la fórmula maestra al lote","parrafos":["Todo producto tiene una **fórmula maestra** aprobada que coincide con su registro sanitario: lista de materiales y cantidades, equipos, instrucciones paso a paso, controles en proceso con sus límites, rendimientos esperados y precauciones especiales. Para cada lote se emite una **copia controlada** que se convierte en el **registro de lote**, donde cada operación se firma en el momento en que se hace.","Las BPM piden que las operaciones con distintos productos no se hagan simultánea ni consecutivamente en la misma sala si hay riesgo de mezcla o contaminación cruzada, que cada contenedor, equipo y sala esté identificado con el producto y el lote, y que cualquier desviación de las instrucciones se registre y se investigue. En esta unidad recorrerás esos controles: contaminación cruzada, productos de alto riesgo, despeje de línea, rendimientos, registro de lote y manejo de materiales."]}],"errores":[{"error":"Registros de lote que no identifican equipos ni personas.","correccion":"Cada operación registra equipo, fecha, hora, resultado y quién la hizo y verificó."},{"error":"Fabricar con una copia no controlada de la fórmula.","correccion":"Usa solo copias emitidas y numeradas por aseguramiento de calidad."}],"comprueba":[{"pregunta":"¿Qué diferencia hay entre la fórmula maestra y el registro de lote?","respuesta":"La fórmula maestra es el documento aprobado del producto; el registro de lote es la copia controlada que se diligencia para un lote concreto."},{"pregunta":"¿Qué es la trazabilidad?","respuesta":"La capacidad de seguir materiales y operaciones de un lote hacia atrás y hacia adelante."}],"resumen":["La **fórmula maestra** define el producto; el **registro de lote** cuenta la historia de cada lote.","La producción se apoya en **despeje, controles en proceso y conciliación**.","Sin trazabilidad no hay investigación posible."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa de proceso","descripcion":"Línea de tiempo de un lote con iconos de documento, caja, lista de chequeo, fábrica, calculadora y firma, en colores de marca.","alt":"Recorrido de un lote bajo Buenas Prácticas de Manufactura"}],"keywords":["proceso productivo bpm","fórmula maestra farmacéutica","registro de lote","trazabilidad de lotes farmacéuticos","producción bajo bpm"],"mapa":{"centro":"Fabricar bajo BPM","ramas":[{"titulo":"Documentos","icono":"FileText","nodos":["Fórmula maestra","Registro de lote","Procedimientos"]},{"titulo":"Materiales","icono":"Package","nodos":["Recepción y cuarentena","Muestreo y liberación","Material de envase impreso"]},{"titulo":"Controles","icono":"ShieldCheck","nodos":["Despeje de línea","Controles en proceso","Rendimientos y conciliación"]},{"titulo":"Riesgos","icono":"AlertTriangle","nodos":["Contaminación cruzada","Mezclas","Productos de alto riesgo"]}]},"proceso":{"titulo":"El recorrido de un lote","intro":"","pasos":[{"titulo":"Emitir el registro de lote","detalle":"Aseguramiento de calidad emite la copia controlada de la fórmula maestra con número de lote.","icono":"FileText","evidencia":"Registro emitido y numerado."},{"titulo":"Despachar materiales","detalle":"El almacén entrega materiales aprobados, pesados y verificados.","icono":"Package","evidencia":"Orden de despacho y pesajes verificados."},{"titulo":"Despejar la línea","detalle":"Producción despeja y una segunda persona verifica antes de iniciar.","icono":"ClipboardCheck","evidencia":"Despeje firmado."},{"titulo":"Fabricar y controlar","detalle":"Se ejecutan las etapas con controles en proceso registrados.","icono":"Factory","evidencia":"Registro de lote diligenciado."},{"titulo":"Conciliar","detalle":"Se calculan rendimientos y se concilia el material impreso.","icono":"Calculator","evidencia":"Conciliación dentro de límites."},{"titulo":"Revisar y liberar","detalle":"Aseguramiento de calidad revisa el registro y la persona autorizada decide.","icono":"Signature","evidencia":"Liberación firmada."}]},"caso":{"titulo":"La queja del sabor extraño","contexto":"Llega una queja por sabor extraño en un lote de jarabe vendido hace seis meses. El registro de lote no indica qué tanque se usó para la fabricación.","pregunta":"¿Qué revela esta situación?","opciones":[{"texto":"Nada importante: el tanque no afecta el sabor.","correcta":false,"retro":"Sin saber qué tanque se usó, no puedes revisar su limpieza ni qué producto se fabricó antes en él."},{"texto":"Una falla de trazabilidad: el registro de lote debe identificar los equipos usados; hay que investigar con otras fuentes y corregir la fórmula maestra.","correcta":true,"retro":"El registro de lote debe permitir reconstruir la historia completa, incluidos los equipos y su estado de limpieza."},{"texto":"Basta con analizar la muestra de retención.","correcta":false,"retro":"El análisis ayuda, pero no reemplaza la trazabilidad de equipos para encontrar la causa."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: el proceso productivo bajo BPM$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: el proceso productivo bajo BPM$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
