    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 21. Registro de lote y controles en proceso
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un registro diligenciado al final del turno","texto":"Durante una auditoría, el inspector compara la hora en que el registro de lote dice que se hizo un control de peso con la hora que muestra el impreso de la balanza: hay dos horas de diferencia. El operario admite que llenó el registro al final del turno, «de memoria». El dato de peso podía ser correcto, pero ya no se puede demostrar. El registro de lote solo vale si se escribe mientras ocurren las cosas."},"objetivos":["Describir el contenido de un registro de lote de fabricación y de empaque.","Aplicar las buenas prácticas de documentación al diligenciarlo.","Seleccionar controles en proceso para una forma farmacéutica."],"conceptos":[{"icono":"ClipboardList","termino":"Registro de lote","definicion":"Documento con la historia de un lote: materiales con sus lotes, pesajes, equipos, pasos, tiempos, controles en proceso, rendimientos, desviaciones y firmas."},{"icono":"Fingerprint","termino":"Buenas prácticas de documentación","definicion":"Escribir en el momento, con tinta indeleble, sin espacios en blanco, corrigiendo con una línea que deje leer el dato original, con firma, fecha y motivo."},{"icono":"Gauge","termino":"Control en proceso","definicion":"Medición durante la fabricación (peso, dureza, friabilidad, pH, volumen) para ajustar el proceso y asegurar que el producto cumplirá."},{"icono":"FileSearch","termino":"Revisión del registro","definicion":"Aseguramiento de calidad revisa el registro completo antes de la liberación: datos, cálculos, desviaciones y firmas."}],"secciones":[{"titulo":"Qué debe contar el registro","parrafos":["El registro de lote se emite como copia controlada de la fórmula maestra y se diligencia durante la fabricación. Debe permitir saber, para cada operación, **qué** se hizo, **con qué** materiales (con sus lotes), **en qué** equipo, **cuándo** y **quién** lo hizo y verificó. Incluye los pesajes con la verificación de una segunda persona en los materiales críticos, los tiempos de cada etapa, los controles en proceso con sus resultados, los rendimientos, las desviaciones y el despeje de línea.","El registro de **empaque** cuenta la segunda parte de la historia: material de envase usado con sus lotes, verificación del codificado de lote y vencimiento, controles en línea, conciliación del material impreso y muestras de retención. Ambos registros se revisan antes de la liberación."]},{"titulo":"Controles en proceso y buenas prácticas de documentación","parrafos":["Los **controles en proceso** se eligen según la forma farmacéutica y el riesgo: en sólidos, por ejemplo, humedad del granulado por pérdida por secado, peso, dureza, espesor, friabilidad y desintegración durante la compresión; en líquidos, pH, densidad, viscosidad y volumen de llenado; en todos, la verificación de identificación y codificado. Cada control tiene un límite y una acción definida si se sale.","Las **buenas prácticas de documentación** convierten el registro en evidencia confiable. Se escribe en el momento, con tinta indeleble; los espacios que no aplican se anulan; las correcciones se hacen con una línea que deje leer el dato original, con la firma, la fecha y el motivo; y nunca se usa corrector ni se transcribe «en limpio». Son los principios ALCOA+ aplicados al papel: atribuible, legible, contemporáneo, original y exacto."]}],"errores":[{"error":"Llenar el registro al final del turno.","correccion":"Se registra en el momento de la operación."},{"error":"Usar corrector o reescribir en limpio.","correccion":"Corrige con una línea, dejando legible el original, con firma, fecha y motivo."},{"error":"Controles en proceso sin acción definida.","correccion":"Cada control tiene límites y una acción si se sale."}],"comprueba":[{"pregunta":"¿Cómo se corrige un dato en un registro?","respuesta":"Con una línea que deje leer el original, el dato correcto, firma, fecha y motivo."},{"pregunta":"Menciona tres controles en proceso de una compresión.","respuesta":"Peso, dureza y friabilidad (también espesor y desintegración)."},{"pregunta":"¿Qué significa contemporáneo en ALCOA+?","respuesta":"Que el dato se registra en el momento en que ocurre la actividad."}],"resumen":["El registro de lote cuenta **qué, con qué, dónde, cuándo y quién**.","Los **controles en proceso** tienen límites y acciones.","Se escribe **en el momento** y se corrige sin ocultar el dato original."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"FDA. Data Integrity and Compliance With Drug CGMP: Questions and Answers (2018).","url":"https://www.fda.gov/media/119267/download"},{"cita":"PIC/S. PI 041: Good Practices for Data Management and Integrity in regulated GMP/GDP environments.","url":"https://picscheme.org/docview/4234"}],"imagenes":[{"ubicacion":"En la sección de documentación","descripcion":"Fragmento ilustrado de un registro con una corrección bien hecha (una línea, dato legible, firma, fecha y motivo) junto a una mal hecha con corrector, marcada con una X.","alt":"Corrección correcta e incorrecta en un registro de lote"}],"keywords":["registro de lote farmacéutico","batch record","controles en proceso","buenas prácticas de documentación","alcoa+ en registros de lote","revisión de registro de lote","cómo corregir un registro bpm"],"mapa":{"centro":"El registro de lote","ramas":[{"titulo":"Qué contiene","icono":"ClipboardList","nodos":["Materiales y sus lotes","Pesajes verificados","Equipos y tiempos"]},{"titulo":"Controles","icono":"Gauge","nodos":["En proceso con límites","Rendimientos","Conciliación"]},{"titulo":"Cómo se escribe","icono":"Fingerprint","nodos":["En el momento","Correcciones legibles","Sin espacios en blanco"]},{"titulo":"Quién revisa","icono":"FileSearch","nodos":["Producción completa","Calidad revisa","Persona autorizada libera"]}]},"proceso":{"titulo":"Revisión del registro de lote antes de la liberación","intro":"","pasos":[{"titulo":"Completitud","detalle":"Verifica que no haya espacios en blanco, que cada paso esté firmado y que los anexos (impresos de balanza, gráficos) estén.","icono":"ClipboardCheck","evidencia":"Lista de revisión diligenciada."},{"titulo":"Coherencia de datos","detalle":"Compara horas, pesos y resultados con los impresos de los equipos.","icono":"Search","evidencia":"Cruce con registros electrónicos."},{"titulo":"Cálculos","detalle":"Recalcula rendimientos y conciliaciones.","icono":"Calculator","evidencia":"Cálculos verificados."},{"titulo":"Controles en proceso","detalle":"Verifica que todos estén dentro de límites o con su desviación gestionada.","icono":"Gauge","evidencia":"Resultados revisados."},{"titulo":"Desviaciones","detalle":"Confirma que cada desviación está investigada y cerrada.","icono":"AlertTriangle","evidencia":"Desviaciones cerradas."},{"titulo":"Dictamen","detalle":"Aseguramiento de calidad emite su revisión para que la persona autorizada decida.","icono":"Signature","evidencia":"Revisión firmada."}]},"caso":{"titulo":"El corrector en el registro","contexto":"Al revisar un registro de lote, encuentras un dato de dureza tapado con corrector y reescrito encima, sin firma ni explicación.","pregunta":"¿Qué haces?","opciones":[{"texto":"Aceptarlo si el dato nuevo está dentro de especificación.","correcta":false,"retro":"No sabes cuál era el dato original ni por qué cambió: puede ocultar un resultado fuera de límite."},{"texto":"Abrir una desviación de integridad de datos, entrevistar a quien registró, buscar el dato original en otras fuentes y evaluar el impacto antes de liberar; reforzar el entrenamiento en buenas prácticas de documentación.","correcta":true,"retro":"Una corrección que oculta el dato original es un hallazgo de integridad: se investiga, no se acepta."},{"texto":"Pedir al operario que escriba la explicación ahora y firmar.","correcta":false,"retro":"Una explicación tardía sin evidencia no restablece la confiabilidad del dato."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Registro de lote y controles en proceso$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Registro de lote y controles en proceso$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 22. Recepción, cuarentena, muestreo y liberación de materias primas
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El contenedor 7 de 12","texto":"Llegan 12 tambores de un excipiente de un proveedor aprobado. Once traen el material correcto; el séptimo, por un error en la bodega del distribuidor, trae otro polvo blanco con la misma etiqueta. Si el laboratorio solo analiza una muestra compuesta de tres tambores, es probable que nadie lo note. Por eso la recepción, la cuarentena y el muestreo de materias primas están entre los controles más importantes de una planta."},"objetivos":["Describir los pasos desde la llegada de una materia prima hasta su liberación.","Explicar el estado de cuarentena y su control físico o informático.","Aplicar los principios de muestreo y de prueba de identidad por contenedor."],"conceptos":[{"icono":"Truck","termino":"Recepción","definicion":"Verificación de que lo que llega corresponde a lo pedido, a un proveedor aprobado, con rótulos y envases íntegros, y asignación de un número de lote interno."},{"icono":"Lock","termino":"Cuarentena","definicion":"Estado del material aislado física o informáticamente mientras se decide su aprobación o rechazo."},{"icono":"TestTube","termino":"Muestreo","definicion":"Toma de muestras representativas según un plan escrito, en un área que proteja el material y el ambiente."},{"icono":"Fingerprint","termino":"Identidad por contenedor","definicion":"Prueba de identidad de las muestras de los contenedores de materia prima, para detectar un contenedor equivocado."},{"icono":"BadgeCheck","termino":"Liberación","definicion":"Decisión de control de calidad de aprobar el material para su uso, con cambio de estado y fecha de reanálisis o vencimiento."}],"secciones":[{"titulo":"Recepción y cuarentena","parrafos":["Cada entrega se verifica contra el pedido y la lista de proveedores aprobados: nombre del material, código, cantidad, lote del fabricante, integridad de envases y sellos, rótulos legibles y certificado de análisis. Cualquier daño o discrepancia se registra y se informa a calidad. Luego se limpian los envases si es necesario, se asigna un **número de lote interno** y el material queda en **cuarentena**.","La cuarentena puede ser **física** (un área separada y rotulada) o **informática** (un sistema validado que impide despachar lo que no está aprobado). Lo importante es que nadie pueda usar el material antes de su liberación. Los materiales rechazados se separan en un área de acceso restringido."]},{"titulo":"Muestreo, identidad y liberación","parrafos":["El muestreo se hace según un **plan escrito**, por personal entrenado, en un área o cabina que proteja el material de la contaminación y evite contaminar el ambiente. La guía de la OMS sobre muestreo (TRS 929, Anexo 4) describe planes de muestreo según la homogeneidad del material y la confianza en el proveedor. Los envases muestreados se identifican y se cierran adecuadamente.","Las BPM dan especial importancia a la **identidad**: por regla general, se verifica la identidad de muestras de cada contenedor de materia prima, salvo que un procedimiento validado y un proveedor calificado justifiquen otra estrategia. El caso del contenedor 7 muestra por qué. Con los resultados conformes, control de calidad **libera** el material: cambia su estado a aprobado y asigna su fecha de reanálisis o vencimiento. El despacho a producción sigue el principio de que sale primero lo que vence primero (FEFO)."]}],"errores":[{"error":"Materiales en cuarentena que se pueden despachar.","correccion":"Bloquea física o informáticamente el material hasta su liberación."},{"error":"Muestrear en el almacén general.","correccion":"Usa un área o cabina de muestreo que proteja el material y el ambiente."},{"error":"Liberar con base solo en el certificado del proveedor.","correccion":"Verifica al menos la identidad de cada contenedor según tu procedimiento."}],"comprueba":[{"pregunta":"¿Qué formas de cuarentena existen?","respuesta":"Física, con área separada y rotulada, o informática, con un sistema validado que impide despachar."},{"pregunta":"¿Por qué se verifica la identidad de cada contenedor?","respuesta":"Porque un contenedor equivocado puede pasar inadvertido si solo se analiza una muestra compuesta."},{"pregunta":"¿Qué significa FEFO?","respuesta":"Que se despacha primero lo que vence primero."}],"resumen":["Recibir, aislar, muestrear, analizar y **liberar**: en ese orden.","La **cuarentena** impide usar lo que no está aprobado.","La **identidad por contenedor** es la defensa contra el error más peligroso."],"referencias":[{"cita":"OMS. TRS 929, Anexo 4: WHO guidelines for sampling of pharmaceutical products and related materials.","url":"https://www.who.int/publications/m/item/annex-4-trs-929"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"En la sección de muestreo","descripcion":"Ilustración de una cabina de muestreo con flujo de aire, un analista con vestimenta y tambores numerados del 1 al 12, el 7 resaltado.","alt":"Muestreo de materias primas por contenedor en una cabina"}],"keywords":["recepción de materias primas farmacéuticas","cuarentena de materias primas","muestreo de materias primas","identidad por contenedor","liberación de materias primas","plan de muestreo oms trs 929","fefo almacén farmacéutico"],"mapa":{"centro":"De la puerta del almacén a producción","ramas":[{"titulo":"Recibir","icono":"Truck","nodos":["Documentos y pedido","Proveedor aprobado","Envases íntegros"]},{"titulo":"Aislar","icono":"Lock","nodos":["Cuarentena física o informática","Rótulo de estado","Lote interno"]},{"titulo":"Muestrear y analizar","icono":"TestTube","nodos":["Plan de muestreo","Área de muestreo","Identidad por contenedor"]},{"titulo":"Decidir","icono":"BadgeCheck","nodos":["Aprobado o rechazado","Reanálisis o vencimiento","Despacho FEFO"]}]},"proceso":{"titulo":"Recepción de una materia prima","intro":"","pasos":[{"titulo":"Verificar la entrega","detalle":"Compara con el pedido, la lista de proveedores aprobados y el certificado; revisa envases y sellos.","icono":"Truck","evidencia":"Registro de recepción."},{"titulo":"Asignar lote interno","detalle":"Da un número de lote interno y rotula cada contenedor.","icono":"Tag","evidencia":"Rótulos de recepción."},{"titulo":"Poner en cuarentena","detalle":"Ubica el material en cuarentena física o informática.","icono":"Lock","evidencia":"Estado en el sistema o rótulo de cuarentena."},{"titulo":"Muestrear","detalle":"Toma las muestras según el plan, en el área de muestreo, e identifica los envases muestreados.","icono":"TestTube","evidencia":"Registro de muestreo."},{"titulo":"Analizar","detalle":"Control de calidad analiza según la especificación, incluida la identidad por contenedor.","icono":"FlaskConical","evidencia":"Resultados analíticos."},{"titulo":"Liberar o rechazar","detalle":"Con resultados conformes, se aprueba con fecha de reanálisis; si no, se rechaza y se separa.","icono":"BadgeCheck","evidencia":"Rótulo de aprobado o rechazado y certificado interno."}]},"caso":{"titulo":"Muestra compuesta para ahorrar tiempo","contexto":"Para acelerar la liberación de 12 tambores de un excipiente, el laboratorio propone analizar solo una muestra compuesta de tres tambores, incluida la identidad.","pregunta":"¿Qué recomiendas?","opciones":[{"texto":"Aceptar, porque el proveedor está aprobado.","correcta":false,"retro":"La aprobación del proveedor no descarta un contenedor equivocado, como el tambor 7 del caso."},{"texto":"Mantener la prueba de identidad sobre muestras de cada contenedor según el procedimiento; la muestra compuesta puede usarse para otros ensayos si el plan de muestreo lo justifica.","correcta":true,"retro":"La identidad por contenedor es la defensa contra el error más peligroso; los demás ensayos pueden seguir un plan estadístico justificado."},{"texto":"Analizar solo el certificado del proveedor.","correcta":false,"retro":"El certificado no reemplaza la verificación de identidad de lo que realmente llegó."}]}}$j$::jsonb;
