  -- 23. Material de envase, rotulado, rechazos y devoluciones
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Una plegadiza que no coincidía con el registro","texto":"Un laboratorio en Cali recibe plegadizas para un jarabe pediátrico. El inspector de recepción nota que el texto del registro sanitario no coincide con el arte aprobado. El lote se rotula como rechazado, se guarda bajo llave y se notifica al proveedor. Dos meses después llega una devolución de un distribuidor con cajas expuestas a humedad y aseguramiento de calidad decide destruirla, con acta. Material impreso, rechazos y devoluciones: tres controles que el inspector revisa al recorrer el almacén."},"objetivos":["Aplicar los controles BPM al material de envase impreso.","Gestionar los materiales y productos rechazados.","Decidir sobre productos devueltos con criterio de calidad."],"conceptos":[{"icono":"Tag","termino":"Material impreso","definicion":"Etiquetas, plegadizas, insertos y foil impreso. Es crítico porque lleva la información del producto: se almacena con acceso restringido, se entrega controlado y se concilia."},{"icono":"ShieldCheck","termino":"Rótulo de estado","definicion":"Cuarentena, aprobado o rechazado, con etiquetas o un sistema informático validado."},{"icono":"XCircle","termino":"Rechazado","definicion":"Material o producto que no cumple. Se identifica, se separa en un área restringida y se devuelve, se reprocesa solo si está autorizado o se destruye."},{"icono":"RefreshCw","termino":"Devolución","definicion":"Producto que regresa del mercado. Solo vuelve al inventario si calidad demuestra que su calidad no se afectó; si hay duda, se destruye."}],"secciones":[{"titulo":"Material de envase y rotulado","parrafos":["Los manuales de BPM de la Resolución 1160 de 2016 dan a los materiales de envase el mismo rigor que a las materias primas: se compran a proveedores aprobados según especificaciones, cada recepción se revisa, se identifica con un lote interno, se pone en cuarentena y se muestrea antes de que control de calidad la apruebe. El **material impreso** es crítico porque contiene la información del producto: se verifica contra el arte aprobado y el registro sanitario, se guarda en condiciones seguras y con acceso restringido, se entrega a producción solo con autorización y en las cantidades necesarias, y se concilia al final.","Las etiquetas sueltas se manejan en contenedores cerrados para evitar mezclas, y el material impreso obsoleto (por ejemplo, tras un cambio de arte) se destruye de forma documentada. El **codificado** de lote y vencimiento en línea se verifica al inicio y durante el envasado."]},{"titulo":"Rechazos y devoluciones","parrafos":["Todo material debe mostrar su **estado**. Los materiales y productos **rechazados** se identifican de forma clara, se guardan separados en un área restringida y se devuelven al proveedor, se reprocesan solo si está autorizado y documentado, o se destruyen con acta.","Los productos **devueltos** del mercado solo se reincorporan al inventario si control de calidad los evalúa y comprueba que su calidad no se afectó, considerando las condiciones de almacenamiento y transporte, el tiempo transcurrido y el estado del envase. Si hay cualquier duda, se destruyen. Los **retiros del mercado** siguen un procedimiento propio y, en Colombia, se coordinan con el INVIMA."]}],"errores":[{"error":"Material impreso en estanterías abiertas.","correccion":"Guárdalo con acceso restringido y entrégalo controlado."},{"error":"Rechazos mezclados con material aprobado.","correccion":"Sepáralos en un área bajo llave, con rótulo de rechazado."},{"error":"Reincorporar devoluciones sin evaluación.","correccion":"Calidad evalúa y documenta; ante la duda, se destruye."}],"comprueba":[{"pregunta":"¿Por qué el material impreso es crítico?","respuesta":"Porque contiene la información del producto; una mezcla de rótulos puede llevar al paciente un producto equivocado."},{"pregunta":"¿Qué destinos puede tener un material rechazado?","respuesta":"Devolución al proveedor, reproceso autorizado y documentado, o destrucción con acta."},{"pregunta":"¿Cuándo vuelve al inventario una devolución?","respuesta":"Solo si calidad demuestra que su calidad no se afectó; si hay duda, se destruye."}],"resumen":["El material impreso se maneja como **material crítico**: aprobado, restringido y conciliado.","Los **rechazados** se separan bajo llave y tienen un destino documentado.","Las **devoluciones** solo vuelven con evidencia; ante la duda, se destruyen."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"}],"imagenes":[{"ubicacion":"En la sección de rechazos","descripcion":"Almacén ilustrado con tres zonas por color: cuarentena (ámbar), aprobado (turquesa) y rechazado bajo llave (rojo suave), con rótulos de estado.","alt":"Zonas de cuarentena, aprobado y rechazado en un almacén farmacéutico"}],"keywords":["material de envase impreso bpm","rotulado de estado cuarentena aprobado rechazado","manejo de rechazos farmacéuticos","devoluciones de productos farmacéuticos","destrucción de material impreso","control de etiquetas farmacéuticas"],"mapa":{"centro":"Materiales que pueden confundir","ramas":[{"titulo":"Material impreso","icono":"Tag","nodos":["Arte aprobado","Acceso restringido","Entrega y conciliación"]},{"titulo":"Estados","icono":"ShieldCheck","nodos":["Cuarentena","Aprobado","Rechazado"]},{"titulo":"Rechazos","icono":"XCircle","nodos":["Área bajo llave","Devolución o destrucción","Acta y registro"]},{"titulo":"Devoluciones","icono":"RefreshCw","nodos":["Evaluación de calidad","Condiciones de almacenamiento","Ante la duda, destruir"]}]},"proceso":{"titulo":"Decisión sobre una devolución del mercado","intro":"","pasos":[{"titulo":"Recibir y aislar","detalle":"La devolución entra a un área separada, identificada como devolución pendiente de evaluación.","icono":"Lock","evidencia":"Registro de recepción de devoluciones."},{"titulo":"Reunir información","detalle":"Motivo de la devolución, tiempo fuera, condiciones de almacenamiento y transporte declaradas.","icono":"FileSearch","evidencia":"Información del cliente o distribuidor."},{"titulo":"Inspeccionar","detalle":"Calidad revisa el estado del envase, sellos, rótulos y signos de manipulación o exposición.","icono":"Search","evidencia":"Informe de inspección."},{"titulo":"Evaluar el riesgo","detalle":"Decide si hay evidencia suficiente de que la calidad no se afectó; si hay duda, no se reincorpora.","icono":"AlertTriangle","evidencia":"Evaluación documentada."},{"titulo":"Decidir","detalle":"Reincorporar con aprobación de calidad o destruir con acta.","icono":"Gavel","evidencia":"Decisión firmada y acta si aplica."}]},"caso":{"titulo":"Cajas húmedas devueltas","contexto":"Un distribuidor devuelve 40 cajas de un jarabe porque «el cliente canceló el pedido». Las cajas exteriores muestran manchas de humedad; los frascos parecen intactos.","pregunta":"¿Qué decide calidad?","opciones":[{"texto":"Reincorporarlas: los frascos están intactos.","correcta":false,"retro":"La humedad revela condiciones de almacenamiento desconocidas que pudieron afectar el producto o sus rótulos."},{"texto":"No reincorporarlas sin evidencia de condiciones adecuadas; ante la duda, destruirlas con acta y registrar la decisión.","correcta":true,"retro":"La regla de BPM es clara: sin evidencia de que la calidad no se afectó, no vuelve al mercado."},{"texto":"Reetiquetar las cajas y venderlas en otra región.","correcta":false,"retro":"Reetiquetar no resuelve la incertidumbre sobre la calidad del producto."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Material de envase, rotulado, rechazos y devoluciones$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Material de envase, rotulado, rechazos y devoluciones$t$;
