  -- 24. Introducción a la unidad: por qué los estériles son distintos
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Una prueba que no puede demostrar lo que promete","texto":"La prueba de esterilidad analiza unas pocas unidades de un lote de miles. Si un lote tuviera una unidad contaminada de cada mil, la probabilidad de detectarla con esa muestra sería muy baja. Por eso, en los productos estériles, la esterilidad no se demuestra al final: se garantiza con el diseño del proceso, de las instalaciones y del trabajo de las personas. Esa idea explica por qué los requisitos se multiplican en esta unidad."},"objetivos":["Explicar por qué la prueba de esterilidad no basta para asegurar la esterilidad de un lote.","Identificar los riesgos propios de los productos estériles: microorganismos, endotoxinas y partículas.","Ubicar los temas de la unidad dentro de la estrategia de control de la contaminación."],"conceptos":[{"icono":"Syringe","termino":"Producto estéril","definicion":"Producto libre de microorganismos viables, como inyectables, colirios o soluciones para irrigación. Llega directo a la sangre, al ojo o a tejidos sin las defensas habituales."},{"icono":"Bug","termino":"Endotoxinas","definicion":"Restos de la pared de bacterias gramnegativas que causan fiebre y reacciones graves aunque las bacterias estén muertas. Por eso se controlan aparte de la esterilidad."},{"icono":"Microscope","termino":"Partículas","definicion":"Material visible o subvisible que no debe estar en un inyectable. Se controla en el ambiente, en los componentes y en el producto."},{"icono":"ShieldCheck","termino":"Aseguramiento de la esterilidad","definicion":"Conjunto de medidas de diseño, proceso, personal y monitoreo que, juntas, dan confianza en la esterilidad. La prueba final solo confirma."}],"secciones":[{"titulo":"Riesgos que no perdonan","parrafos":["Un comprimido contaminado con pocos microorganismos pasa por un estómago ácido; un inyectable contaminado llega directo a la sangre. Además del riesgo microbiológico, los estériles deben controlar las **endotoxinas**, que causan reacciones aunque las bacterias ya no estén vivas, y las **partículas**, que pueden obstruir capilares o causar inflamación.","La **prueba de esterilidad** tiene un límite estadístico: analiza una muestra pequeña y solo detecta contaminaciones frecuentes. Por eso las BPM para estériles, el Anexo 1 de 2022 y la guía de la OMS (TRS 1044, Anexo 2) se concentran en el proceso. En Colombia, la Resolución 1160 de 2016 incluye un manual específico de BPM para medicamentos estériles y una guía de inspección propia."]},{"titulo":"El mapa de la unidad","parrafos":["En esta unidad verás los principales cambios del **Anexo 1 de 2022** y del TRS 1044, la clasificación por **grados** y el **monitoreo ambiental** dentro de una estrategia de control de la contaminación, el **llenado aséptico** y su validación con simulaciones con medio de cultivo, y la comparación entre **esterilización terminal** y **procesamiento aséptico**. El hilo conductor es uno: en estériles, cada barrera se diseña, se valida y se vigila, porque ninguna prueba final puede compensar una barrera rota."]}],"errores":[{"error":"Confiar en la prueba de esterilidad para liberar.","correccion":"La liberación se apoya en el proceso validado, el monitoreo y la revisión del lote; la prueba solo confirma."},{"error":"Olvidar las endotoxinas.","correccion":"Contrólalas en agua, componentes y producto: no desaparecen con la esterilización."}],"comprueba":[{"pregunta":"¿Por qué la prueba de esterilidad no basta?","respuesta":"Porque analiza una muestra pequeña y tiene baja probabilidad de detectar contaminaciones ocasionales."},{"pregunta":"¿Qué son las endotoxinas?","respuesta":"Restos de la pared de bacterias gramnegativas que causan fiebre y reacciones aunque las bacterias estén muertas."}],"resumen":["En estériles, la esterilidad **se asegura con el proceso**, no con la prueba final.","Se controlan **microorganismos, endotoxinas y partículas**.","Cada barrera se **diseña, valida y vigila**."],"referencias":[{"cita":"Comisión Europea. EU GMP Annex 1: Manufacture of Sterile Medicinal Products (2022).","url":"https://health.ec.europa.eu/system/files/2022-08/20220825_gmp-an1_en_0.pdf"},{"cita":"OMS. TRS 1044, Anexo 2: WHO good manufacturing practices for sterile pharmaceutical products (2022).","url":"https://www.who.int/publications/m/item/trs1044-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa de proceso","descripcion":"Capas concéntricas ilustradas alrededor de un vial: diseño, instalaciones, componentes, personal, monitoreo y prueba final, en tonos de azul a turquesa.","alt":"Capas de protección de un producto estéril"}],"keywords":["bpm productos estériles","fabricación de medicamentos estériles","por qué la prueba de esterilidad no basta","endotoxinas en inyectables","aseguramiento de la esterilidad","manual bpm estériles colombia"],"mapa":{"centro":"Qué hace distintos a los estériles","ramas":[{"titulo":"Riesgos","icono":"Bug","nodos":["Microorganismos","Endotoxinas","Partículas"]},{"titulo":"Límites de la prueba","icono":"TestTube","nodos":["Muestra pequeña","Baja probabilidad de detectar","Solo confirma"]},{"titulo":"Cómo se asegura","icono":"ShieldCheck","nodos":["Áreas por grados","Procesos validados","Personal calificado"]},{"titulo":"Qué verás","icono":"BookOpen","nodos":["Anexo 1 de 2022","Grados y monitoreo","Llenado aséptico y esterilización"]}]},"proceso":{"titulo":"Capas que protegen un inyectable","intro":"","pasos":[{"titulo":"Diseño del producto y del proceso","detalle":"Se elige el método de esterilización más seguro que tolere el producto.","icono":"Lightbulb","evidencia":"Justificación del método."},{"titulo":"Instalaciones por grados","detalle":"Áreas limpias A, B, C y D según la operación, con HVAC calificado.","icono":"Building2","evidencia":"Clasificación de áreas."},{"titulo":"Componentes controlados","detalle":"Envases, tapones y soluciones se lavan, esterilizan o despirogenizan con procesos validados.","icono":"Package","evidencia":"Validaciones de procesos de componentes."},{"titulo":"Personal calificado","detalle":"Entrenamiento, vestido calificado y participación en simulaciones del proceso aséptico.","icono":"Users","evidencia":"Registros de calificación del personal."},{"titulo":"Monitoreo continuo","detalle":"Partículas y microorganismos en aire, superficies y personal, con tendencias.","icono":"LineChart","evidencia":"Programa y resultados de monitoreo."},{"titulo":"Prueba final","detalle":"Esterilidad, endotoxinas y partículas confirman, pero no sustituyen, lo anterior.","icono":"TestTube","evidencia":"Certificado de análisis."}]},"caso":{"titulo":"Esterilidad conforme, monitoreo fuera de límite","contexto":"Un lote de viales cumple la prueba de esterilidad. Durante su llenado, sin embargo, una placa de sedimentación del grado A mostró crecimiento microbiano.","pregunta":"¿Qué pesa más en la decisión?","opciones":[{"texto":"La prueba de esterilidad conforme: el lote está estéril.","correcta":false,"retro":"La prueba tiene baja probabilidad de detectar una contaminación ocasional. El hallazgo en grado A es una señal directa de riesgo."},{"texto":"El hallazgo en grado A: se investiga el evento, se identifica el microorganismo y se evalúa el impacto antes de decidir sobre el lote.","correcta":true,"retro":"En estériles, el monitoreo del proceso pesa tanto o más que la prueba final, porque esta no puede demostrar la esterilidad de todo el lote."},{"texto":"Repetir la prueba de esterilidad con más unidades.","correcta":false,"retro":"Más unidades no resuelven el límite estadístico ni explican el hallazgo del ambiente."}]}}$j$::jsonb;
