  -- 30. Requisitos BPM para la fabricación y el análisis por contrato
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El titular sin planta","texto":"En Colombia es frecuente que el titular de un registro sanitario no tenga planta propia y contrate a un laboratorio certificado para fabricar, y a otro para analizar. Si un lote sale mal, el paciente y el INVIMA no preguntan quién lo fabricó por contrato: preguntan al titular. Por eso las BPM dedican un capítulo completo a lo que se fabrica o se analiza por contrato."},"objetivos":["Explicar las responsabilidades del contratante y del contratista según las BPM.","Evaluar a un contratista antes de encargarle una actividad.","Reconocer los límites de la subcontratación."],"conceptos":[{"icono":"Building2","termino":"Contratante","definicion":"Quien encarga la actividad. Evalúa al contratista, le entrega la información necesaria, controla la actividad y sigue siendo responsable de la calidad."},{"icono":"Factory","termino":"Contratista","definicion":"Quien ejecuta la actividad. Debe tener instalaciones, equipos, personal y certificado de BPM adecuados, y no subcontratar sin autorización escrita."},{"icono":"FileText","termino":"Contrato escrito","definicion":"Documento que define con claridad las responsabilidades de cada parte, incluidas las técnicas en un acuerdo técnico de calidad."},{"icono":"Search","termino":"Derecho de auditoría","definicion":"El contratante, y la autoridad, pueden auditar las instalaciones y registros del contratista."}],"secciones":[{"titulo":"Responsabilidades que no se delegan","parrafos":["El capítulo de producción y análisis por contrato de las BPM de la OMS, recogido en los manuales de la Resolución 1160 de 2016, establece que toda actividad contratada debe estar definida, acordada y controlada por escrito para evitar malentendidos que afecten la calidad. El **contratante** sigue siendo responsable de la calidad del medicamento frente al INVIMA y frente al paciente: tercerizar una actividad no traslada esa responsabilidad.","Antes de contratar, el contratante evalúa que el **contratista** tenga la capacidad técnica, las instalaciones, el personal y el **certificado de BPM vigente** para la forma farmacéutica o el análisis que se va a encargar, normalmente con una auditoría. Luego le entrega toda la información necesaria: fórmulas, especificaciones, métodos, riesgos del producto y cualquier precaución especial."]},{"titulo":"Subcontratación, cambios y vigilancia","parrafos":["El contratista no puede **subcontratar** ninguna parte del trabajo sin la autorización escrita del contratante, y debe permitir **auditorías** del contratante y de la autoridad. Los cambios en el proceso, los materiales o las instalaciones que puedan afectar la calidad deben notificarse y aprobarse antes de implementarse, y las desviaciones relevantes deben comunicarse en los plazos acordados.","En el registro sanitario figura el fabricante del producto, y el INVIMA verifica que ese fabricante tenga certificado de BPM vigente para el área correspondiente. Durante una inspección, puede pedir los contratos y los acuerdos técnicos. La guía de la FDA sobre acuerdos de calidad en la fabricación por contrato, aunque no es norma colombiana, es una buena referencia para estructurarlos; la verás en la clase siguiente."]}],"errores":[{"error":"Contratar solo con base en el precio.","correccion":"Evalúa y audita la capacidad técnica y el certificado de BPM."},{"error":"Contratos comerciales sin acuerdo técnico.","correccion":"Formaliza un acuerdo técnico de calidad con responsabilidades claras."},{"error":"No verificar el alcance del certificado del contratista.","correccion":"Confirma que ampare la forma farmacéutica y el área que vas a usar."}],"comprueba":[{"pregunta":"¿Quién responde por la calidad cuando se fabrica por contrato?","respuesta":"El contratante, que no traslada su responsabilidad al contratista."},{"pregunta":"¿Puede el contratista subcontratar?","respuesta":"Solo con autorización escrita del contratante."}],"resumen":["El **contratante responde** por la calidad aunque terceriza.","El contratista necesita **BPM vigentes** para la actividad y permite auditorías.","Nada se subcontrata **sin autorización escrita**."],"referencias":[{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"FDA. Contract Manufacturing Arrangements for Drugs: Quality Agreements (2016).","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/contract-manufacturing-arrangements-drugs-quality-agreements-guidance-industry"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Dos edificios ilustrados unidos por un documento con sello: contratante y contratista, con una lupa de auditoría.","alt":"Relación entre contratante y contratista en la fabricación por contrato"}],"keywords":["fabricación por contrato bpm","maquila farmacéutica colombia","análisis por contrato","responsabilidades contratante contratista bpm","subcontratación bpm","auditoría a fabricantes por contrato"],"mapa":{"centro":"Fabricar o analizar por contrato","ramas":[{"titulo":"Contratante","icono":"Building2","nodos":["Evalúa y aprueba","Entrega información técnica","Responde por la calidad"]},{"titulo":"Contratista","icono":"Factory","nodos":["BPM vigentes para la actividad","No subcontrata sin permiso","Permite auditorías"]},{"titulo":"Documentos","icono":"FileText","nodos":["Contrato","Acuerdo técnico de calidad","Registros accesibles"]},{"titulo":"Control","icono":"Search","nodos":["Auditorías","Indicadores","Gestión de cambios y desviaciones"]}]},"proceso":{"titulo":"Seleccionar y controlar a un fabricante por contrato","intro":"","pasos":[{"titulo":"Definir el alcance","detalle":"Qué actividades se contratan: fabricación, empaque, análisis, almacenamiento.","icono":"ClipboardList","evidencia":"Alcance documentado."},{"titulo":"Preseleccionar","detalle":"Verifica certificado de BPM vigente para el área y la forma farmacéutica.","icono":"ShieldCheck","evidencia":"Copia del certificado y su alcance."},{"titulo":"Auditar","detalle":"Audita instalaciones, sistema de calidad y capacidad técnica.","icono":"Search","evidencia":"Informe de auditoría."},{"titulo":"Contratar y acordar","detalle":"Firma el contrato y el acuerdo técnico de calidad con la matriz de responsabilidades.","icono":"FileText","evidencia":"Contrato y acuerdo firmados."},{"titulo":"Transferir","detalle":"Transfiere la tecnología y la información técnica, con validaciones en el sitio del contratista.","icono":"Truck","evidencia":"Protocolos de transferencia y validación."},{"titulo":"Vigilar","detalle":"Revisa indicadores, desviaciones, cambios y reaudita con la frecuencia definida.","icono":"LineChart","evidencia":"Indicadores y auditorías periódicas."}]},"caso":{"titulo":"El análisis que se subcontrató","contexto":"Durante una auditoría, el titular descubre que su fabricante por contrato envió los ensayos microbiológicos a un tercer laboratorio, sin avisarle.","pregunta":"¿Qué significa?","opciones":[{"texto":"No importa si el tercer laboratorio es competente.","correcta":false,"retro":"La subcontratación sin autorización escrita viola las BPM y el contrato; el titular no evaluó a ese laboratorio."},{"texto":"Es un incumplimiento: el contratista no puede subcontratar sin autorización escrita; hay que evaluar al tercero, revisar el impacto en los lotes y formalizar o suspender la práctica.","correcta":true,"retro":"El contratante debe controlar toda la cadena; una subcontratación oculta rompe ese control."},{"texto":"Es responsabilidad exclusiva del fabricante.","correcta":false,"retro":"La responsabilidad por la calidad sigue siendo del titular contratante."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
