  -- 31. Acuerdo técnico de calidad
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"¿Quién libera el lote?","texto":"Un titular de registro de ibuprofeno en suspensión contrata a un laboratorio certificado en Bogotá para fabricar y a un laboratorio externo para algunos ensayos microbiológicos. Llega el primer lote y surge la pregunta: ¿quién lo libera al mercado, y con base en qué certificados? Si la respuesta no está escrita y firmada antes, cada parte asumirá que lo hace la otra. Para eso existe el acuerdo técnico de calidad."},"objetivos":["Identificar los elementos mínimos de un acuerdo técnico de calidad.","Construir una matriz de responsabilidades entre contratante y contratista.","Definir los flujos de cambios, desviaciones y quejas entre las partes."],"conceptos":[{"icono":"FileCheck","termino":"Acuerdo técnico de calidad","definicion":"Documento firmado por las áreas de calidad de ambas partes que define quién hace qué en materia de calidad. Complementa el contrato comercial."},{"icono":"ClipboardList","termino":"Matriz de responsabilidades","definicion":"Tabla que asigna cada actividad (compra de materiales, fabricación, análisis, liberación, retenciones, quejas) a una de las partes."},{"icono":"GitBranch","termino":"Gestión de cambios entre partes","definicion":"Regla de que ningún cambio con impacto en la calidad se implementa sin evaluación y aprobación del contratante."},{"icono":"Timer","termino":"Plazos de notificación","definicion":"Tiempos acordados para comunicar desviaciones críticas, resultados fuera de especificación o retiros."}],"secciones":[{"titulo":"Los elementos mínimos","parrafos":["Un acuerdo técnico de calidad normalmente incluye: las partes, el alcance y los productos; una **matriz de responsabilidades** (quién compra y aprueba materiales, quién fabrica, quién analiza, quién libera el lote, quién guarda las muestras de retención); los documentos maestros y el manejo de cambios; las desviaciones y los resultados fuera de especificación y su notificación; las quejas, los retiros del mercado y la farmacovigilancia; la conservación de registros y el acceso a ellos; el derecho de auditoría; la transferencia de tecnología y las validaciones; y las firmas de las personas responsables de calidad de ambas partes.","La guía de la FDA sobre acuerdos de calidad en la fabricación por contrato es útil para estructurarlo, y los manuales de BPM de la Resolución 1160 de 2016 dan el fundamento: las responsabilidades deben estar escritas y nada que afecte la calidad puede quedar en un acuerdo verbal."]},{"titulo":"El caso del ibuprofeno resuelto","parrafos":["En el ejemplo, el acuerdo define que el **fabricante** hace los controles en proceso y el análisis fisicoquímico; que el **laboratorio externo** hace el recuento microbiano; y que la **dirección técnica del titular** libera el lote al mercado con base en ambos certificados y en la revisión del registro de lote. También establece que el fabricante debe notificar cualquier desviación crítica dentro de las 24 horas y que ningún cambio de proveedor de materias primas se implementa sin aprobación del titular.","Un buen acuerdo se revisa periódicamente y cada vez que cambia algo importante: un producto nuevo, un sitio nuevo o una reorganización. Y se usa: cuando aparece una desviación, la primera pregunta es qué dice el acuerdo."]}],"errores":[{"error":"Acuerdos genéricos que no dicen quién libera.","correccion":"La matriz de responsabilidades debe nombrar quién libera y con qué evidencia."},{"error":"Firmar el acuerdo solo por las áreas comerciales.","correccion":"Lo firman los responsables de calidad de ambas partes."},{"error":"No prever plazos de notificación.","correccion":"Define plazos para desviaciones críticas, resultados fuera de especificación y retiros."}],"comprueba":[{"pregunta":"¿Quién firma el acuerdo técnico de calidad?","respuesta":"Los responsables de calidad de ambas partes."},{"pregunta":"Menciona cuatro actividades de la matriz de responsabilidades.","respuesta":"Compra y aprobación de materiales, fabricación, análisis y liberación del lote (también muestras de retención y quejas)."}],"resumen":["El acuerdo técnico define **quién hace qué** en calidad.","Su corazón es la **matriz de responsabilidades**, incluida la liberación.","Prevé **cambios, desviaciones, quejas y plazos** de notificación."],"referencias":[{"cita":"FDA. Contract Manufacturing Arrangements for Drugs: Quality Agreements (2016).","url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/contract-manufacturing-arrangements-drugs-quality-agreements-guidance-industry"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"}],"imagenes":[{"ubicacion":"En la sección de elementos","descripcion":"Tabla ilustrada de matriz de responsabilidades con columnas «titular», «fabricante» y «laboratorio externo» y marcas de verificación en colores de marca.","alt":"Matriz de responsabilidades de un acuerdo técnico de calidad"}],"keywords":["acuerdo técnico de calidad","quality agreement farmacéutico","matriz de responsabilidades fabricación por contrato","contrato de fabricación de medicamentos","acuerdo de calidad maquila","liberación de lotes por contrato"],"mapa":{"centro":"Qué contiene un acuerdo técnico","ramas":[{"titulo":"Alcance","icono":"Target","nodos":["Partes y productos","Actividades contratadas","Documentos maestros"]},{"titulo":"Responsabilidades","icono":"ClipboardList","nodos":["Materiales","Fabricación y análisis","Liberación y retenciones"]},{"titulo":"Comunicación","icono":"Users","nodos":["Cambios","Desviaciones y fuera de especificación","Quejas, retiros y farmacovigilancia"]},{"titulo":"Control","icono":"Search","nodos":["Registros y acceso","Auditorías","Firmas de calidad"]}]},"proceso":{"titulo":"Construir la matriz de responsabilidades","intro":"","pasos":[{"titulo":"Listar actividades","detalle":"Enumera cada actividad de calidad: compras, muestreo, análisis, fabricación, empaque, liberación, almacenamiento, distribución.","icono":"ClipboardList","evidencia":"Lista de actividades."},{"titulo":"Asignar responsables","detalle":"Para cada actividad, indica quién la ejecuta y quién la aprueba.","icono":"Users","evidencia":"Matriz con responsables."},{"titulo":"Definir comunicaciones","detalle":"Qué se notifica, a quién, en qué plazo y con qué formato.","icono":"Timer","evidencia":"Flujos de comunicación."},{"titulo":"Revisar vacíos","detalle":"Verifica que ninguna actividad quede sin responsable ni con dos responsables.","icono":"Search","evidencia":"Revisión cruzada de calidad."},{"titulo":"Firmar","detalle":"Las personas responsables de calidad de ambas partes firman y fechan.","icono":"Signature","evidencia":"Acuerdo firmado."},{"titulo":"Revisar periódicamente","detalle":"Actualiza el acuerdo ante cambios o en la revisión definida.","icono":"RefreshCw","evidencia":"Historial de versiones."}]},"caso":{"titulo":"Un cambio de proveedor de envases","contexto":"El fabricante por contrato cambia el proveedor de frascos de un jarabe porque el anterior subió precios. No avisa al titular porque «el frasco nuevo cumple la misma especificación».","pregunta":"¿Qué indica un buen acuerdo técnico?","opciones":[{"texto":"Que no era necesario avisar si cumple la especificación.","correcta":false,"retro":"Un cambio de material de envase primario puede afectar la estabilidad y requiere evaluación y aprobación del titular."},{"texto":"Que ningún cambio con impacto potencial en la calidad se implementa sin evaluación y aprobación del contratante; hay que gestionar el cambio y evaluar los lotes ya fabricados.","correcta":true,"retro":"El acuerdo debe prever la gestión de cambios entre las partes, y el envase primario es un cambio relevante."},{"texto":"Que el fabricante decide sobre sus proveedores.","correcta":false,"retro":"En materiales que afectan la calidad del producto del titular, la decisión es compartida y documentada."}]}}$j$::jsonb;
