  -- 32. Programa de autoinspección con las guías de inspección
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Encontrarlo antes que el inspector","texto":"En una autoinspección, una auditora interna revisa el área de pesaje con la guía de inspección del INVIMA en la mano y encuentra que la balanza de activos no tiene verificaciones diarias desde hace dos semanas. Lo corrigen, evalúan los lotes y documentan todo. Tres meses después llega la visita del INVIMA: el inspector revisa la misma balanza y encuentra un registro impecable y una desviación bien cerrada. Eso es una autoinspección que funciona."},"objetivos":["Diseñar un programa de autoinspección conforme a las BPM.","Usar las guías de inspección de la Resolución 1160 de 2016 como lista de verificación.","Asegurar la independencia y el seguimiento de la autoinspección."],"conceptos":[{"icono":"CalendarClock","termino":"Programa","definicion":"Plan que define la frecuencia, el alcance y los responsables de las autoinspecciones para cubrir todas las áreas y capítulos de las BPM."},{"icono":"UserCheck","termino":"Independencia","definicion":"Los auditores no evalúan su propia área, para garantizar una mirada objetiva."},{"icono":"ClipboardCheck","termino":"Guía de inspección","definicion":"La misma lista de verificación que usa el INVIMA, adoptada como herramienta interna."},{"icono":"FileCheck","termino":"Informe y seguimiento","definicion":"Cada autoinspección produce un informe con hallazgos, acciones, responsables y fechas, y se hace seguimiento hasta el cierre."}],"secciones":[{"titulo":"Qué exige y cómo se organiza","parrafos":["Los manuales de BPM de la Resolución 1160 de 2016 piden un programa de **autoinspección periódico**, con personal competente e independiente del área evaluada, una lista de verificación y informes con hallazgos y acciones correctivas que se sigan hasta cerrarlas. El objetivo es detectar deficiencias en la aplicación de las BPM y proponer las medidas necesarias.","Un programa sólido cubre **todas las áreas y todos los capítulos** de las BPM a lo largo del año: personal, instalaciones, equipos, sistemas de agua y aire, materiales, documentación, producción, control de calidad, contratos, quejas, retiros y la propia autoinspección. La frecuencia por área se define con criterio de riesgo: más frecuente donde el impacto en el producto es mayor o donde hubo hallazgos."]},{"titulo":"La guía de inspección como herramienta interna","parrafos":["Las guías de inspección de la Resolución 1160 de 2016 son la mejor lista de verificación porque son las mismas que usará el INVIMA. Cada pregunta se responde con **evidencia objetiva**: un documento, un registro, una entrevista o una observación directa. Los auditores recorren la planta, piden ejecuciones en vivo (por ejemplo, un despeje de línea) y cruzan registros.","El informe clasifica los hallazgos por riesgo (lo verás en la siguiente clase), se presenta a la dirección y genera un plan de acción. La autoinspección se cierra cuando las acciones se verifican como **eficaces**, no cuando se firman. Las tendencias de hallazgos de un año a otro muestran si el sistema mejora o si los mismos problemas regresan."]}],"errores":[{"error":"Autoinspecciones sin seguimiento de las acciones.","correccion":"Sigue cada acción hasta verificar su eficacia en sitio."},{"error":"Revisar solo documentos sin recorrer la planta.","correccion":"Observa ejecuciones en vivo y cruza registros con la realidad."},{"error":"Programas que dejan áreas sin revisar durante años.","correccion":"Cubre todas las áreas y capítulos con frecuencia basada en riesgo."}],"comprueba":[{"pregunta":"¿Por qué se usan las guías de inspección del INVIMA en la autoinspección?","respuesta":"Porque son los mismos criterios que aplicará el inspector, lo que permite anticipar hallazgos."},{"pregunta":"¿Cuándo se cierra un hallazgo de autoinspección?","respuesta":"Cuando se verifica que la acción fue eficaz, no solo cuando se ejecuta o se firma."}],"resumen":["La autoinspección es **periódica, independiente y completa**.","Las **guías de inspección** son la mejor lista de verificación.","Se cierra con **eficacia verificada**."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"},{"cita":"OMS. TRS 986, Anexo 2: WHO good manufacturing practices for pharmaceutical products: main principles (2014).","url":"https://www.who.int/publications/m/item/trs986-annex2"}],"imagenes":[{"ubicacion":"En la sección de la guía","descripcion":"Auditora ilustrada con una tableta que muestra la guía de inspección, recorriendo una sala de pesaje, con marcas de verificación turquesa.","alt":"Autoinspección con la guía de inspección en el área de pesaje"}],"keywords":["autoinspección bpm","programa de autoinspección farmacéutica","guía de inspección invima autoinspección","auditoría interna bpm","cómo hacer una autoinspección","independencia del auditor interno"],"mapa":{"centro":"Autoinspección que funciona","ramas":[{"titulo":"Planear","icono":"CalendarClock","nodos":["Todas las áreas y capítulos","Frecuencia por riesgo","Equipo competente"]},{"titulo":"Ejecutar","icono":"ClipboardCheck","nodos":["Guías de inspección","Recorrido y entrevistas","Evidencia objetiva"]},{"titulo":"Reportar","icono":"FileText","nodos":["Hallazgos clasificados","Informe a la dirección","Plan de acción"]},{"titulo":"Cerrar","icono":"CheckCircle2","nodos":["Seguimiento","Verificación de eficacia","Tendencias de hallazgos"]}]},"proceso":{"titulo":"Una autoinspección de principio a fin","intro":"","pasos":[{"titulo":"Planear el alcance","detalle":"Define áreas, capítulos de la guía, auditores independientes y fechas.","icono":"CalendarClock","evidencia":"Plan de autoinspección."},{"titulo":"Preparar","detalle":"Revisa hallazgos anteriores, desviaciones y quejas del área para enfocar la revisión.","icono":"FileSearch","evidencia":"Lista de puntos de enfoque."},{"titulo":"Ejecutar en sitio","detalle":"Recorre, entrevista, observa ejecuciones y revisa registros con la guía.","icono":"ClipboardCheck","evidencia":"Guía diligenciada con evidencias."},{"titulo":"Reunión de cierre","detalle":"Presenta los hallazgos al área para validar los hechos.","icono":"Users","evidencia":"Acta de cierre."},{"titulo":"Informar y planear acciones","detalle":"Emite el informe con hallazgos clasificados y acuerda acciones, responsables y fechas.","icono":"FileText","evidencia":"Informe y plan de acción."},{"titulo":"Verificar eficacia","detalle":"Comprueba en sitio que las acciones resolvieron el problema y cierra.","icono":"CheckCircle2","evidencia":"Cierre verificado."}]},"caso":{"titulo":"El jefe que audita su propia área","contexto":"Por falta de personal, el jefe de producción propone autoinspeccionar él mismo el área de producción este año.","pregunta":"¿Qué solución preserva el valor de la autoinspección?","opciones":[{"texto":"Aceptar, porque es quien mejor conoce el área.","correcta":false,"retro":"Conocer el área no reemplaza la independencia; es difícil ver los problemas propios."},{"texto":"Asignar auditores de otras áreas entrenados, o un auditor externo, y que el jefe de producción participe como auditado.","correcta":true,"retro":"La independencia es un requisito de la autoinspección; hay alternativas aunque falte personal."},{"texto":"Saltar la autoinspección de producción este año.","correcta":false,"retro":"Producción es una de las áreas de mayor riesgo; omitirla deja un vacío grave."}]}}$j$::jsonb;
