  -- 33. Clasificación de hallazgos y plan de mejoramiento
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Tres hallazgos, tres pesos distintos","texto":"En la autoinspección anual de un laboratorio de líquidos no estériles en Barranquilla aparecen tres hallazgos: un diferencial de presión registrado fuera de rango tres días sin investigación, un operario sin entrenamiento en el procedimiento de limpieza actualizado, y agua purificada usada como materia prima con resultados microbiológicos fuera de especificación aprobados sin investigar. No pesan lo mismo, y tratarlos igual sería un error. Clasificar es priorizar."},"objetivos":["Clasificar deficiencias como críticas, mayores o menores según su riesgo.","Explicar cómo la acumulación de deficiencias puede elevar su clasificación.","Construir un plan de mejoramiento con causa, acción, responsable, fecha y evidencia."],"conceptos":[{"icono":"XCircle","termino":"Deficiencia crítica","definicion":"Puede producir un medicamento que ponga en riesgo la salud del paciente, o hay evidencia de fraude o falsificación de datos."},{"icono":"AlertTriangle","termino":"Deficiencia mayor","definicion":"No crítica, pero puede generar un producto que no cumpla su registro sanitario, o es una falla importante del sistema."},{"icono":"Tag","termino":"Deficiencia menor","definicion":"Desviación de BPM que, por sí sola, no se espera que afecte la calidad, como un registro sin fecha aislado."},{"icono":"ClipboardList","termino":"Plan de mejoramiento","definicion":"Respuesta a cada hallazgo con descripción, causa raíz, acción correctiva y preventiva, responsable, fecha y evidencia de cierre."}],"secciones":[{"titulo":"Cómo se clasifica","parrafos":["En las guías de inspección, las deficiencias se clasifican por su **riesgo**. Una deficiencia **crítica** puede producir un medicamento que ponga en riesgo la salud del paciente, o hay evidencia de fraude o falsificación de datos: por ejemplo, la ausencia de área exclusiva para betalactámicos o la falsificación de registros de lote. Una **mayor** no es crítica, pero puede generar un producto que no cumpla su registro sanitario, o es una falla importante del sistema: equipos críticos sin calificar o despejes de línea sin verificar. Una **menor** es una desviación de BPM que, por sí sola, no se espera que afecte la calidad: un registro sin fecha aislado o un rótulo de limpieza deteriorado.","Varias deficiencias del mismo tipo pueden **sumarse** y elevar la clasificación: un operario sin entrenamiento es menor; la misma situación en varias áreas revela una falla del sistema de capacitación y puede ser mayor. El resultado de una inspección del INVIMA depende del número y del peso de las deficiencias, según el procedimiento vigente del Decreto 335 de 2022 y los lineamientos del instituto."]},{"titulo":"El caso de Barranquilla y el plan de mejoramiento","parrafos":["En el caso inicial, el agua purificada con resultados fuera de especificación aprobados sin investigar es **crítica**: afecta directamente los productos y sugiere aprobación indebida de datos. El diferencial de presión fuera de rango sin investigación es **mayor**: riesgo de contaminación cruzada y falla del sistema de monitoreo. El operario sin entrenamiento es **menor**, salvo que se repita en varias áreas. El comité de calidad prioriza el hallazgo crítico, suspende la liberación de los lotes afectados y documenta el plan.","Cada hallazgo se responde en el **plan de mejoramiento** con descripción, análisis de **causa raíz**, acción correctiva y preventiva, responsable, fecha comprometida y evidencia de cierre. La metodología de causa raíz y la verificación de eficacia se profundizan en los cursos de Desviaciones y CAPA y de Auditoría; aquí lo esencial es clasificar bien y priorizar."]}],"errores":[{"error":"Clasificar todo como menor para no alarmar.","correccion":"Clasifica por riesgo real; subestimar priva al sistema de recursos para corregir."},{"error":"Planes sin causa raíz.","correccion":"Sin causa raíz, la acción trata el síntoma y el hallazgo regresa."},{"error":"No sumar hallazgos repetidos.","correccion":"Evalúa si varios hallazgos menores revelan una falla del sistema."}],"comprueba":[{"pregunta":"Da un ejemplo de deficiencia crítica.","respuesta":"Falsificación de registros de lote o ausencia de área exclusiva para betalactámicos."},{"pregunta":"¿Cuándo un hallazgo menor puede volverse mayor?","respuesta":"Cuando se repite en varias áreas y revela una falla del sistema."},{"pregunta":"¿Qué elementos tiene cada línea del plan de mejoramiento?","respuesta":"Descripción, causa raíz, acción correctiva y preventiva, responsable, fecha y evidencia de cierre."}],"resumen":["Las deficiencias se clasifican en **críticas, mayores y menores** por su riesgo.","Los hallazgos repetidos **pueden escalar**.","El plan de mejoramiento ataca la **causa raíz** y se cierra con evidencia."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"Presidencia de la República. Decreto 335 de 2022: procedimiento para obtener los certificados de cumplimiento de buenas prácticas.","url":"https://www.invima.gov.co/sites/default/files/medicamentos-y-productos-biologicos/tecnico-medicamentos/medicamentos-sintesis-quimica-y-biologica/Decreto%20No.%20335%20de%202022.pdf"},{"cita":"FDA. Data Integrity and Compliance With Drug CGMP: Questions and Answers (2018).","url":"https://www.fda.gov/media/119267/download"},{"cita":"ICH. Q9(R1) Quality Risk Management (2023).","url":"https://database.ich.org/sites/default/files/ICH_Q9%28R1%29_Guideline_Step4_2023_0126_0.pdf"}],"imagenes":[{"ubicacion":"Junto al mapa conceptual","descripcion":"Semáforo ilustrado con tres niveles (crítica, mayor, menor) y ejemplos cortos al lado de cada luz, en tonos de la paleta.","alt":"Clasificación de deficiencias críticas, mayores y menores"}],"keywords":["clasificación de hallazgos bpm","deficiencia crítica mayor menor invima","plan de mejoramiento bpm","hallazgos de auditoría farmacéutica","causa raíz plan de mejoramiento","clasificación de no conformidades bpm"],"mapa":{"centro":"De hallazgo a mejora","ramas":[{"titulo":"Crítica","icono":"XCircle","nodos":["Riesgo para el paciente","Fraude o falsificación","Acción inmediata"]},{"titulo":"Mayor","icono":"AlertTriangle","nodos":["Producto fuera de registro","Falla importante del sistema","Prioridad alta"]},{"titulo":"Menor","icono":"Tag","nodos":["Sin impacto esperado aislado","Puede escalar si se repite","Se corrige y vigila"]},{"titulo":"Plan","icono":"ClipboardList","nodos":["Causa raíz","Acción, responsable y fecha","Evidencia de cierre"]}]},"proceso":{"titulo":"Del hallazgo al cierre","intro":"","pasos":[{"titulo":"Describir con evidencia","detalle":"Redacta el hallazgo con el requisito incumplido y la evidencia objetiva.","icono":"FileText","evidencia":"Hallazgo documentado."},{"titulo":"Clasificar por riesgo","detalle":"Determina si es crítico, mayor o menor y si se suma a otros del mismo tipo.","icono":"AlertTriangle","evidencia":"Clasificación justificada."},{"titulo":"Contener","detalle":"Para críticos y mayores, toma acciones inmediatas sobre producto y proceso.","icono":"Hand","evidencia":"Acciones de contención."},{"titulo":"Analizar la causa raíz","detalle":"Busca por qué ocurrió, no solo qué ocurrió.","icono":"Search","evidencia":"Análisis de causa raíz."},{"titulo":"Planear acciones","detalle":"Define acción correctiva y preventiva, responsable y fecha.","icono":"ClipboardList","evidencia":"Plan de mejoramiento."},{"titulo":"Cerrar con eficacia","detalle":"Verifica que el problema no se repite y archiva la evidencia.","icono":"CheckCircle2","evidencia":"Evidencia de cierre."}]},"caso":{"titulo":"Los registros completados por otra persona","contexto":"En una autoinspección se descubre que una analista firmaba resultados de ensayos que había ejecutado una compañera ausente, «para no retrasar la liberación».","pregunta":"¿Cómo se clasifica?","opciones":[{"texto":"Menor, porque los ensayos sí se hicieron.","correcta":false,"retro":"Firmar lo que otra persona ejecutó es una falsificación de la atribución del dato."},{"texto":"Crítica: es una falla de integridad de datos que compromete la confiabilidad de los resultados; se contiene, se investiga el alcance y se corrige la cultura y el sistema.","correcta":true,"retro":"La falsificación de registros es un ejemplo clásico de deficiencia crítica, aunque el resultado analítico fuera correcto."},{"texto":"Mayor, porque no afectó el producto.","correcta":false,"retro":"No se puede afirmar que no afectó: los datos dejaron de ser confiables y hay evidencia de falsificación."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Clasificación de hallazgos y plan de mejoramiento$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Clasificación de hallazgos y plan de mejoramiento$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 34. Procedimiento de certificación: Decreto 335 de 2022
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un trámite que empieza mucho antes de radicarlo","texto":"Una planta radica su solicitud de certificación con la idea de «empezar a prepararse cuando programen la visita». Cuando llega la fecha, faltan calificaciones, el plano no coincide con la obra y el plan maestro de validación está desactualizado. La certificación es un trámite administrativo, pero su resultado se decide en los meses previos. Conocer el procedimiento ayuda a planear ese trabajo."},"objetivos":["Describir las etapas generales del procedimiento de certificación ante el INVIMA.","Identificar la información y los documentos que conviene tener listos antes de solicitar.","Reconocer los posibles conceptos de una visita y sus consecuencias."],"conceptos":[{"icono":"Landmark","termino":"Decreto 335 de 2022","definicion":"Norma que regula el procedimiento para obtener los certificados de cumplimiento de buenas prácticas ante el INVIMA. Sus plazos, requisitos y vigencias se consultan en el texto vigente."},{"icono":"FileText","termino":"Solicitud","definicion":"La radicación ante el INVIMA con la información de la planta, las áreas y las formas farmacéuticas a certificar, según los requisitos del procedimiento."},{"icono":"ShieldCheck","termino":"Visita","definicion":"La inspección con la guía correspondiente, que termina con un acta y un concepto."},{"icono":"Award","termino":"Concepto y certificado","definicion":"El resultado de la visita (favorable, con requerimientos o no favorable) y, si corresponde, el certificado para las áreas evaluadas."}],"secciones":[{"titulo":"El procedimiento en términos generales","parrafos":["El Decreto 549 de 2001 creó la certificación de BPM para los laboratorios fabricantes de medicamentos, y el **Decreto 335 de 2022** actualizó el procedimiento para obtener los certificados de cumplimiento de buenas prácticas ante el INVIMA. En términos generales, el interesado **solicita** la certificación con la información de la planta y de las áreas y formas farmacéuticas a certificar; el INVIMA **programa y realiza la visita** con la guía de inspección correspondiente; la visita termina con un **acta** y un **concepto**; y, si el concepto lo permite, se expide el **certificado** para lo evaluado.","Los plazos, los requisitos documentales, la vigencia de los certificados y las condiciones de renovación están en el texto del decreto y en los lineamientos del INVIMA. Como cambian con el tiempo, **verifica siempre la versión vigente** antes de planear una solicitud o una renovación."]},{"titulo":"Qué tener listo antes de solicitar","parrafos":["Más allá de los requisitos del formulario, conviene llegar con el sistema de calidad funcionando y demostrable: un **plano actualizado** con flujos, áreas y clasificación; el **plan maestro de validación** al día, con equipos y sistemas calificados y procesos, limpiezas y métodos validados; procedimientos aprobados y entrenados; registros de lote completos; programas de monitoreo con tendencias; una **autoinspección reciente** con la guía de inspección y su plan de mejoramiento en ejecución; y contratos y acuerdos técnicos firmados si hay actividades tercerizadas.","Los posibles conceptos dependen del número y del peso de las deficiencias. Un concepto con requerimientos implica un **plan de mejoramiento** con plazos y su seguimiento; uno no favorable impide obtener el certificado hasta corregir. Recuerda que el certificado ampara áreas y formas farmacéuticas concretas: una ampliación o una forma nueva requieren su propia evaluación."]}],"errores":[{"error":"Usar requisitos o plazos de memoria.","correccion":"Consulta el texto vigente del Decreto 335 de 2022 y los lineamientos del INVIMA."},{"error":"Radicar con hallazgos críticos abiertos.","correccion":"Cierra lo crítico con evidencia antes de solicitar."},{"error":"Suponer que el certificado cubre ampliaciones.","correccion":"Toda área o forma nueva requiere su propia evaluación."}],"comprueba":[{"pregunta":"¿Qué norma regula hoy el procedimiento de certificación?","respuesta":"El Decreto 335 de 2022."},{"pregunta":"¿Qué conceptos puede tener una visita?","respuesta":"Favorable, favorable con requerimientos o no favorable."},{"pregunta":"¿Por qué hay que verificar el texto vigente del decreto?","respuesta":"Porque plazos, requisitos y vigencias pueden cambiar y no deben usarse de memoria."}],"resumen":["El **Decreto 335 de 2022** regula el procedimiento de certificación.","La certificación se **gana antes** de radicar: sistema listo y demostrable.","Verifica siempre **plazos y requisitos vigentes**."],"referencias":[{"cita":"Presidencia de la República. Decreto 335 de 2022: procedimiento para obtener los certificados de cumplimiento de buenas prácticas.","url":"https://www.invima.gov.co/sites/default/files/medicamentos-y-productos-biologicos/tecnico-medicamentos/medicamentos-sintesis-quimica-y-biologica/Decreto%20No.%20335%20de%202022.pdf"},{"cita":"Presidencia de la República. Decreto 549 de 2001: certificado de cumplimiento de Buenas Prácticas de Manufactura.","url":"https://www.invima.gov.co/invima_website/static/attachments/normatividad_normatividad_interna/decreto-549-de-2001_2.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"INVIMA. Resolución 1160 de 2016, texto compilado con sus modificaciones (normograma).","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_1160_2016.htm"}],"imagenes":[{"ubicacion":"Junto al mapa de proceso","descripcion":"Camino ilustrado con seis hitos hasta un certificado con sello, en azul y turquesa.","alt":"Ruta hacia la certificación de BPM ante el INVIMA"}],"keywords":["decreto 335 de 2022","certificación bpm invima procedimiento","cómo obtener el certificado de bpm","solicitud de certificación invima","concepto favorable con requerimientos","renovación certificado bpm"],"mapa":{"centro":"Certificación de BPM ante el INVIMA","ramas":[{"titulo":"Antes","icono":"ClipboardCheck","nodos":["Autoinspección con la guía","Documentos listos","Calificaciones y validaciones al día"]},{"titulo":"Solicitud","icono":"FileText","nodos":["Radicación según el decreto","Áreas y formas a certificar","Pago y requisitos"]},{"titulo":"Visita","icono":"ShieldCheck","nodos":["Inspección con la guía","Acta","Concepto"]},{"titulo":"Después","icono":"Award","nodos":["Certificado","Plan de mejoramiento","Mantenimiento y renovación"]}]},"proceso":{"titulo":"Ruta hacia la certificación","intro":"","pasos":[{"titulo":"Definir el alcance","detalle":"Determina qué áreas y formas farmacéuticas vas a certificar.","icono":"Target","evidencia":"Alcance aprobado por la dirección."},{"titulo":"Autoinspeccionar","detalle":"Aplica la guía de inspección y cierra las brechas críticas y mayores.","icono":"ClipboardCheck","evidencia":"Informe y plan de mejoramiento."},{"titulo":"Preparar la documentación","detalle":"Reúne los requisitos del decreto y la evidencia del sistema de calidad.","icono":"Files","evidencia":"Expediente completo."},{"titulo":"Radicar la solicitud","detalle":"Presenta la solicitud ante el INVIMA según el procedimiento vigente.","icono":"FileText","evidencia":"Radicado."},{"titulo":"Recibir la visita","detalle":"Atiende la inspección con el equipo preparado.","icono":"ShieldCheck","evidencia":"Acta de visita."},{"titulo":"Responder y obtener el certificado","detalle":"Atiende los requerimientos en los plazos y obtiene el certificado si el concepto lo permite.","icono":"Award","evidencia":"Certificado o plan aprobado."}]},"caso":{"titulo":"Radicar ya o esperar","contexto":"La gerencia quiere radicar la solicitud de certificación de una nueva área de líquidos esta semana. La autoinspección encontró dos hallazgos críticos aún abiertos.","pregunta":"¿Qué recomiendas?","opciones":[{"texto":"Radicar ya: el INVIMA tarda en programar la visita y para entonces estará todo cerrado.","correcta":false,"retro":"Es una apuesta con riesgo alto: si la visita llega antes del cierre, el concepto puede ser no favorable."},{"texto":"Cerrar primero los hallazgos críticos con evidencia y luego radicar, con un cronograma realista según los plazos del procedimiento vigente.","correcta":true,"retro":"La solicitud debe llegar cuando el sistema esté listo para demostrarse; los críticos abiertos comprometen el resultado."},{"texto":"Radicar sin mencionar los hallazgos.","correcta":false,"retro":"Los hallazgos no desaparecen; el inspector puede encontrarlos y además se pierde confianza."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Procedimiento de certificación: Decreto 335 de 2022$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Procedimiento de certificación: Decreto 335 de 2022$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  -- 35. La visita de certificación: preparación, desarrollo y cierre
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La pregunta que nadie esperaba","texto":"En plena visita, el inspector pide al operario de la blistera que le explique, con sus palabras, qué hace si la conciliación de plegadizas no cuadra. El operario duda, mira a su jefe y responde algo distinto del procedimiento. Ese momento vale más que cien páginas de documentos. Una visita de certificación evalúa si el sistema funciona en las personas, no solo en los papeles."},"objetivos":["Organizar la preparación de una visita de certificación.","Describir el desarrollo típico de la visita: apertura, recorrido, revisión documental y cierre.","Responder adecuadamente durante la visita y gestionar el resultado."],"conceptos":[{"icono":"Users","termino":"Equipo de visita","definicion":"Coordinador, acompañantes por área, responsables de documentos y personas clave disponibles para entrevistas."},{"icono":"DoorOpen","termino":"Reunión de apertura","definicion":"Presentación de los inspectores, el alcance y la agenda, y una breve presentación de la empresa."},{"icono":"Search","termino":"Recorrido y revisión","definicion":"Inspección de las áreas, entrevistas al personal, observación de ejecuciones y revisión de documentos y registros."},{"icono":"FileCheck","termino":"Reunión de cierre y acta","definicion":"Presentación de los hallazgos y firma del acta, con el concepto o los requerimientos."}],"secciones":[{"titulo":"Preparar sin maquillar","parrafos":["La preparación empieza con una **autoinspección reciente** con la guía de inspección y su plan de mejoramiento en ejecución. Luego se organiza la logística: una sala para los inspectores, un coordinador de la visita, acompañantes para cada área, una persona que localice documentos con rapidez y un registro de lo que se entrega. Los documentos clave deben estar ubicables: manual de calidad, organigrama, plano, plan maestro de validación, procedimientos, registros de lote, programas de monitoreo, desviaciones, CAPA, quejas, retiros y contratos.","El personal debe saber que habrá visita y entender que puede responder con honestidad: «No lo sé, pero el procedimiento está aquí» es una respuesta mejor que una improvisación. Preparar no es maquillar: limpiar a fondo o completar registros atrasados la noche anterior suele ser evidente para un inspector y genera más desconfianza que el hallazgo original."]},{"titulo":"Durante y después de la visita","parrafos":["La visita suele iniciar con una **reunión de apertura**, seguir con el **recorrido** de las áreas (con observación de ejecuciones, como un despeje de línea en vivo, y entrevistas) y la **revisión documental**, y terminar con una **reunión de cierre** en la que se presentan los hallazgos y se firma el acta. Durante la visita conviene responder solo lo que se pregunta, con evidencia; llevar un registro de lo solicitado y entregado; y aclarar con respeto cuando un hallazgo parte de un malentendido, aportando el documento que lo demuestra.","Después, la empresa responde a los requerimientos con un **plan de mejoramiento** realista: causa, acción, responsable, fecha y evidencia. Cumplir los plazos y demostrar la eficacia de las acciones construye la confianza para las siguientes visitas. Y lo aprendido alimenta el sistema: los hallazgos del INVIMA se tratan como cualquier otro hallazgo en la gestión de CAPA."]}],"errores":[{"error":"Completar registros atrasados antes de la visita.","correccion":"Gestiona lo atrasado como desviación; nunca lo «pongas al día»."},{"error":"Personal que responde de memoria o improvisa.","correccion":"Entrena al personal a responder con lo que hace y a apoyarse en el procedimiento."},{"error":"Planes de mejoramiento con fechas imposibles.","correccion":"Compromete plazos realistas y cúmplelos con evidencia."}],"comprueba":[{"pregunta":"¿Qué etapas tiene una visita típica?","respuesta":"Reunión de apertura, recorrido de áreas, revisión documental y reunión de cierre con acta."},{"pregunta":"¿Qué debe hacer el personal si no sabe una respuesta?","respuesta":"Decirlo con honestidad y apoyarse en el procedimiento o en el responsable, sin improvisar."}],"resumen":["La visita evalúa si el sistema **funciona en las personas**.","Preparar es **demostrar**, no maquillar.","Después, un **plan de mejoramiento** realista construye confianza."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016: manuales de Buenas Prácticas de Manufactura y guías de inspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"Presidencia de la República. Decreto 335 de 2022: procedimiento para obtener los certificados de cumplimiento de buenas prácticas.","url":"https://www.invima.gov.co/sites/default/files/medicamentos-y-productos-biologicos/tecnico-medicamentos/medicamentos-sintesis-quimica-y-biologica/Decreto%20No.%20335%20de%202022.pdf"},{"cita":"FDA. Data Integrity and Compliance With Drug CGMP: Questions and Answers (2018).","url":"https://www.fda.gov/media/119267/download"},{"cita":"PIC/S. PI 041: Good Practices for Data Management and Integrity in regulated GMP/GDP environments.","url":"https://picscheme.org/docview/4234"}],"imagenes":[{"ubicacion":"En la sección de desarrollo","descripcion":"Escena ilustrada de una reunión de cierre: dos inspectores y el equipo de calidad alrededor de una mesa con el acta, en la paleta de Edvanta.","alt":"Reunión de cierre de una visita de certificación del INVIMA"}],"keywords":["visita de certificación invima","cómo prepararse para una visita del invima","inspección bpm invima","reunión de apertura y cierre inspección","acta de visita invima","preparación de auditoría bpm"],"mapa":{"centro":"La visita del INVIMA","ramas":[{"titulo":"Preparar","icono":"ClipboardCheck","nodos":["Autoinspección reciente","Sala y documentos listos","Equipo y personal informado"]},{"titulo":"Abrir","icono":"DoorOpen","nodos":["Alcance y agenda","Presentación breve","Acompañantes asignados"]},{"titulo":"Inspeccionar","icono":"Search","nodos":["Recorrido de áreas","Entrevistas","Registros y documentos"]},{"titulo":"Cerrar","icono":"FileCheck","nodos":["Hallazgos y acta","Plan de mejoramiento","Seguimiento"]}]},"proceso":{"titulo":"Desarrollo de una visita de certificación","intro":"","pasos":[{"titulo":"Preparar el equipo y la sala","detalle":"Asigna coordinador, acompañantes y responsables de documentos; organiza la sala.","icono":"Users","evidencia":"Plan de atención de la visita."},{"titulo":"Reunión de apertura","detalle":"Recibe a los inspectores, confirma el alcance y la agenda y presenta brevemente la empresa.","icono":"DoorOpen","evidencia":"Registro de asistencia."},{"titulo":"Recorrido de áreas","detalle":"Acompaña sin interferir, permite entrevistas y ejecuciones en vivo.","icono":"Route","evidencia":"Notas del acompañante."},{"titulo":"Revisión documental","detalle":"Entrega lo solicitado con rapidez y registra cada documento entregado.","icono":"Files","evidencia":"Registro de documentos entregados."},{"titulo":"Reunión de cierre","detalle":"Escucha los hallazgos, aclara con evidencia los malentendidos y firma el acta.","icono":"FileCheck","evidencia":"Acta firmada."},{"titulo":"Plan de mejoramiento","detalle":"Responde en el plazo con causa, acción, responsable, fecha y evidencia.","icono":"ClipboardList","evidencia":"Plan radicado y seguimiento."}]},"caso":{"titulo":"El registro que se completó anoche","contexto":"Durante la revisión documental, el inspector nota que varios registros de limpieza de la última semana tienen la misma tinta y la misma letra, y que fueron completados en una sola sesión.","pregunta":"¿Cuál es la mejor respuesta de la empresa?","opciones":[{"texto":"Afirmar que se llenaron en su momento.","correcta":false,"retro":"Negar lo evidente agrava el problema y puede convertirlo en una deficiencia crítica de integridad."},{"texto":"Reconocer el hecho, explicar que se abrió o se abrirá una investigación de integridad de datos y comprometer acciones; y en la preparación de futuras visitas no completar registros atrasados.","correcta":true,"retro":"La transparencia preserva la confianza; la investigación demuestra que el sistema reacciona."},{"texto":"Retirar esos registros de la carpeta.","correcta":false,"retro":"Ocultar registros es una falla grave de integridad."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$La visita de certificación: preparación, desarrollo y cierre$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$La visita de certificación: preparación, desarrollo y cierre$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    UPDATE aula_lesson_blocks SET sort_order = sort_order + 1, updated_at = NOW()
     WHERE lesson_id = v_clase AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (121_experiencias_bpm.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Buenas Prácticas de Manufactura — BPM$t$, v_n;
END $exp$;
